/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#1":{"묶음":[{"머리":"물류의 정의와 변천","줄":[{"t":"물류(물류정책기본법): 재화가 공급자로부터 조달·생산되어 수요자에게 전달되거나 소비자로부터 회수되어 폐기될 때까지 이루어지는 운송·보관·하역 등과 이에 부가되어 가치를 창출하는 가공·조립·분류·수리·포장·상표부착·판매·정보통신 등","src":"물류정책기본법 제2조 제1항 제1호"},{"t":"물적유통(Physical Distribution): 판매영역 중심의 물자 흐름","src":"기출 2022-21, 2024-1"},{"t":"쇼(A.W. Shaw): 경영활동 내 유통의 한 영역으로 Physical Distribution 개념을 정의","src":"기출 2022-21"},{"t":"물적유통은 주로 수송·보관·하역·포장 등 부문별 효율화를 추구","src":"기출 2025-3"},{"t":"로지스틱스(Logistics): 병참(군사용어)에서 유래, 조달·생산·판매·회수물류를 포함하는 총체적 개념","src":"기출 2024-1, 2026-1"},{"t":"로지스틱스는 조달·생산·판매 등 기업 내 물류 효율화가 목표. 재화가 조달·생산되어 소비자에게 전달되고 폐기되는 과정까지 포함","src":"기출 2025-3, 2022-21"},{"t":"물류와 Logistics는 혼용되나 범위는 Logistics가 더 넓다","src":"기출 2023-11"},{"t":"SCM(공급사슬관리): 공급자·제조업자·도소매점·고객 등 공급사슬 전반의 효율화가 목적. 고객·공급업체·제조업체·유통업체 네트워크의 재화·정보·자금 흐름을 다룸","src":"기출 2025-3, 2024-1"},{"t":"범위 확대 순서: 물적유통 → 로지스틱스 → SCM. 2000년대부터 SCM으로 변천","src":"기출 2025-3, 2023-11"},{"t":"전통적 물류 개념: 사물의 흐름과 관련된 시간적·공간적 효용을 창출하는 경영활동","src":"기출 2023-11"},{"t":"물류시스템: 생산과 소비를 연결하며 공간적·시간적 효용을 창출","src":"기출 2022-1"},{"t":"물류의 목적: 물류서비스 증대와 물류비용 최소화","src":"기출 2022-1"},{"t":"물류시스템 자원: 인적·물적·재무적·정보적 자원","src":"기출 2022-1"},{"t":"물류하부시스템: 수송·보관·포장·하역·물류정보·유통가공","src":"기출 2022-1"},{"t":"유통(distribution): 생산자에서 소비자로 상품·서비스를 이전하며 장소적·시간적·소유적 효용을 창조하는 활동. 상적유통·물적유통·유통조성활동을 포함","src":"이론"},{"t":"상적유통(상류): 소유권 이전과 관련된 상거래활동. 사회적 불일치 해소·수량적 조정·품질적 조정 기능을 포함하고 도·소매업, 중개업, 무역업이 속함","src":"이론"},{"t":"물적유통(physical distribution function): 물품을 이동시켜 공간적·시간적 효용을 창출. 장소적 격차는 운송이, 시간적 차이는 보관이 해소하고 하역·포장·유통가공·물류정보도 포함","src":"이론"},{"t":"유통조성활동: 표준화 및 등급화(규격화), 금융, 보험, 위험부담, 시장정보 기능","src":"이론"},{"t":"물류: 생산에서 소비에 이르는 물적인 흐름. 상품을 생산해 고객에게 배달하기까지 전 과정에서 장소와 시간의 효용을 창출하는 제반 활동","src":"이론"},{"t":"물류: 원료·반제품·완제품을 출발지에서 소비지까지 효율적으로 이동시키는 것을 계획·실현·통제하기 위한 두 가지 이상의 활동","src":"이론"},{"t":"물류관리의 발전 순서: 물적유통 → 로지스틱스 → 공급사슬관리(SCM)","src":"이론"},{"t":"1960년대 물적유통: 운송·보관·포장·하역 중심으로 비용절감의 최적화가 우선. 이후 화주 서비스 증진까지 포함해 전체 물류 프로세스를 효율화한 로지스틱스가 등장","src":"이론"},{"t":"물적유통 단계: 운송·보관·하역 등 기능적 물류활동 중심, 비용절감과 기능별 최적화, 물류생산성 제고, 상물분리","src":"이론"},{"t":"로지스틱스 단계: 물류의 기능적 활동 + 전략적 고객서비스 강화, 물류 영역 전반의 최적화, 통합적 물류관리","src":"이론"},{"t":"SCM 단계: 로지스틱스 개념 + 공급망 전체의 통합. 공급망 전체 최적화·장기적 파트너십·정보공유","src":"이론"},{"t":"SCM: 원료 공급자부터 생산·유통·최종 고객까지 제품과 정보의 흐름을 통합 관리하기 위해 기업 간 전략적 관계 형성·정보공유·협력을 하는 프로세스. 기업 내·외부의 수요와 공급을 통합해 물류를 최적화","src":"이론"},{"t":"통합물류관리: 조달·생산·판매를 하나의 일관 시스템으로 보고 생산계획·고객서비스·주문처리·재고관리 등 물리적 재화의 흐름을 총체적으로 관리. 목표는 고객서비스의 최적화","src":"이론"},{"t":"통합물류관리 기법: 공급사슬관리(SCM), 전사적 자원관리(ERP), 효율적 소비자 대응(QR, ECR)","src":"이론"}]},{"머리":"물류 3S 1L과 7R","줄":[{"t":"3S 1L 원칙: 신속성(Speedy)·안정성(Safely)·확실성(Surely)·경제성(Low)","src":"기출 2024-1"},{"t":"스마이키(E.W. Smykey)의 7R: 적절한 상품(Commodity)·품질(Quality)·수량(Quantity)·시간(Time)·장소(Place)·가격(Price)·인상(Impression)","src":"기출 2021-5, 2023-2, 2024-1, 2026-5"},{"t":"7R에 해당하지 않는 것으로 출제된 것: 적절한 고객(Customer), 안전(Safety), 보안(Security), 포장(Packaging)","src":"기출 2021-5, 2023-2, 2024-1, 2026-5"}]},{"머리":"물류의 효과와 중요성","줄":[{"t":"물류 생산성 향상과 비용절감으로 물가상승을 억제","src":"기출 2021-1"},{"t":"물류 합리화로 유통구조를 선진화하고 사회간접자본 투자에 기여","src":"기출 2021-1"},{"t":"고객 요구에 따라 생산된 제품을 고객에게 전달하고 수요를 창출. 생산자와 소비자 사이의 인격적 유대를 강화하고 고객서비스를 높임","src":"기출 2021-1"},{"t":"물류비용 절감을 통한 이익 창출은 제3의 이익원","src":"기출 2023-6, 2025-6"},{"t":"물류관리의 목표: 비용절감을 통한 제품의 판매촉진과 수익증대","src":"기출 2023-6"},{"t":"물류관리는 구매·생산·마케팅과 밀접. 원자재·부품 조달, 구매상품 보관, 완제품 유통도 대상","src":"기출 2023-6, 2025-6"},{"t":"물류관리 대상: 고객서비스관리·재고관리·주문정보관리·운송관리. 인사관리는 대상이 아님","src":"기출 2023-1"},{"t":"중요성 증대 배경: 공급사슬 전체 경쟁력 강화, 생산부문 원가절감의 한계, 온라인쇼핑 증가에 따른 배송 중요성, 글로벌화에 따른 물동량 증가","src":"기출 2025-5"},{"t":"물류 합리화 추진 시 내부 기능 간 또는 기업 간 상충관계(trade-off) 발생 가능","src":"기출 2025-31"},{"t":"물류 합리화 추진 단계: 환경 분석 → 목표 설정 → 전략 수립","src":"기출 2025-31"},{"t":"지능형 자동화 기계를 물류 업무에 도입하는 것은 생지능형(省知能形) 합리화","src":"기출 2025-31"},{"t":"제1의 이익원(생산관리): 비용절감을 통한 이익창출","src":"이론"},{"t":"제2의 이익원(마케팅관리): 매출액 증대를 통한 이익창출","src":"이론"},{"t":"제3의 이익원(물류관리): 물류비 절감을 통한 이익창출. 생산·인사·마케팅관리를 통한 원가절감이 한계에 이르자 최후의 이익원으로 중요해짐","src":"이론"},{"t":"물류 중요성 증가 배경: 전자상거래 확대로 소량·다빈도 주문 증가, 글로벌 공급망 악화·도로정체·소량 다빈도 배송에 따른 운송시간·비용 상승, 공급사슬 전체 효율을 높이는 경쟁력 확보","src":"이론"},{"t":"물류관리 목표 1: 고객서비스를 개선해 고객 니즈에 대한 대응수준을 향상","src":"이론"},{"t":"물류관리 목표 2: 물류합리화로 상충관계에 있는 물류비용과 고객서비스 수준을 적정하게 조절","src":"이론"},{"t":"물류관리 목표 3: 물류비 절감을 통한 기업 이익 추구","src":"이론"},{"t":"물류관리 목표 4: 물류활동의 계획·실행·통제·성과평가로 기업 경쟁력과 공급사슬 전체의 효율성을 추구","src":"이론"}]},{"머리":"유통활동 구분: 상적유통과 물적유통","줄":[{"t":"물적유통 활동: 보관, 화물수송, 유통가공, 정보관리","src":"기출 2021-2, 2025-2"},{"t":"상적유통 활동: 거래(상거래)활동, 금융조성활동, 표준화 활동","src":"기출 2021-2, 2025-2"}]},{"머리":"물류 6대 기능","줄":[{"t":"운송(수송): 물자의 장소적 효용가치를 증대. 물자를 물류거점 간 및 고객에게 이동","src":"기출 2026-4, 2024-3"},{"t":"보관: 생산과 소비의 시기·수량 차이를 조정, 시간적 효용가치를 증대","src":"기출 2021-14, 2026-4, 2022-20"},{"t":"하역: 운송·보관·포장 사이에 발생하는 물자 취급 활동. 운송과 보관을 위해 화물을 싣거나 내리는 행위","src":"기출 2021-14, 2022-20, 2024-3"},{"t":"포장: 적절한 재료·용기로 물자를 보호하고 취급을 용이하게 하며 상품가치를 제고. 생산의 종착점이자 물류의 출발점이므로 표준화·모듈화가 중요","src":"기출 2021-14, 2022-20, 2024-3, 2026-4"},{"t":"유통가공: 유통과정에서 고객 요구에 부합하기 위해 행하는 단순 가공·재포장·조립·절단 등","src":"기출 2024-3, 2026-4, 2022-20"},{"t":"정보관리: 물류계획 수립과 통제에 필요한 자료를 수집·활용. 전자적 수단으로 물류활동을 효율화","src":"기출 2021-14, 2022-20, 2024-3"},{"t":"수송은 물류거점 간 대량·장거리 이동, 배송은 소량·단거리로 고객에게 인도하는 것으로 구분","src":"보충"},{"t":"운송활동(수송+배송)은 물류비용 중 가장 큰 비중을 차지하는 물류활동","src":"이론"},{"t":"운송: 재화와 용역의 효용가치를 낮은 곳(place)에서 높은 곳으로 이동시켜 장소적 효용을 증대","src":"이론"},{"t":"보관: 유통의 최전선으로서 고객서비스 기능까지 포함. 시간적 격차를 해소해 생산과 소비를 결합","src":"이론"},{"t":"하역: 운반관리 개념. 보관과 운송의 중간에서 물품 취급 효율을 높임. 하역 자체의 가치보다 운송·보관의 효율 향상을 지원하는 역할","src":"이론"},{"t":"정보: 무형의 자원인 정보를 유통시키는 경제활동. 물류활동 관련 정보를 제공해 물류관리 기능을 연결","src":"이론"},{"t":"유통가공: 물품 자체의 기능을 변화시키지 않고 부가가치만 부여. 간단한 가공·조립·재포장·주문에 따른 소분작업. 목적은 판매촉진·생산효율지원·물류합리화","src":"이론"},{"t":"물류 기능활동 간에는 상충관계(trade-off)가 있어 기능 간 조화를 통한 시스템 통합화가 필요","src":"이론"}]},{"머리":"물류의 영역별 분류","줄":[{"t":"조달물류: 물자의 조달처로부터 운송되어 매입자의 보관창고에 입고·관리되어 생산공정에 투입되기 직전까지의 물류활동","src":"기업물류비 산정지침 제7조 제1항 제1호, 기출 2022-22"},{"t":"사내물류(생산물류): 자재가 생산공정에 투입된 때부터 제품이 완성되기까지의 물류활동","src":"기출 2022-22, 2024-7, 2026-2"},{"t":"판매물류: 완제품이 판매창고에 입고된 후 고객에게 인도될 때까지의 물류활동","src":"기업물류비 산정지침 제7조 제1항 제3호, 기출 2026-2"},{"t":"역물류: 반품물류·폐기물류·회수물류를 포함하며 순물류와 반대 방향으로 이동","src":"기출 2022-22, 2024-7, 2025-1"},{"t":"회수물류: 판매물류를 지원하는 파렛트·컨테이너 등 포장용기·물류용기의 회수 활동","src":"기출 2022-22, 2024-7, 2026-2, 2025-1"},{"t":"반품물류는 고객요구 다양화·클레임 증가·유통채널 경쟁·전자상거래 확대로 중요성이 커짐","src":"기출 2021-3"},{"t":"영역별 분류에 정보물류는 없다","src":"기출 2023-5"},{"t":"순물류(forwarding logistics): 조달물류 → 생산물류 → 사내물류 → 판매물류. 역물류: 폐기·반품·회수물류","src":"이론"},{"t":"조달물류: 물류의 시발점. 원부자재 조달부터 매입자의 보관창고에 입고·관리되어 생산공정에 투입되기 직전까지. 구매 → 조달 → 공급망으로 개념 발전","src":"이론"},{"t":"생산물류: 원자재·부품이 생산공정에 투입되고 제품이 생산되어 판매를 위해 출하되기 직전까지의 물류활동. 핵심과제는 생산 리드타임 단축과 재고량 감축","src":"이론"},{"t":"사내물류: 제조업체에서 생산된 완제품의 출하부터 물류센터 보관창고에 이르기까지. 물류센터의 입·출고와 보관활동 포함","src":"이론"},{"t":"판매물류: 제품이 창고나 물류센터에서 판매를 위해 출하되어 소비자에게 인도되기까지의 물류활동","src":"이론"},{"t":"폐기물류: 원자재와 제품의 포장재·수배송용기 등 폐기물을 처분하기 위한 물류활동. 그린물류·환경물류로도 불림","src":"이론"},{"t":"반품물류: 판매된 제품이 하자 등의 이유로 교환되거나 공장으로 되돌아올 때까지의 물류. 제품 파손·기능 소멸과 관련","src":"이론"},{"t":"회수물류: 상품판매 시 부수적으로 발생하는 파렛트·컨테이너 같은 물류용기와 음료수 공병의 회수·재활용 물류활동. 운송용기 재활용, 차량·가전제품 리콜 포함. 친환경물류로 분류","src":"이론"},{"t":"정맥물류: 인간의 혈액순환에 빗댄 말. 소비지에서 쓴 폐기물을 순환자원으로 리사이클 시설로 수송하고, 재생산된 제품을 다시 소비지로 수송하는 물류","src":"이론"},{"t":"생산물류는 물자가 생산공정에 투입될 때부터 제품 생산과정까지의 물류활동. 핵심과제는 생산리드타임 단축과 재고량 감축","src":"기출 2020-3"}]},{"머리":"물류산업과 물류시설","줄":[{"t":"물류사업: 화물운송업·물류시설운영업·물류서비스업·종합물류서비스업","src":"물류정책기본법 제2조 제1항 제2호"},{"t":"물류서비스업: 화물운송의 주선, 물류장비의 임대, 물류정보의 처리, 물류컨설팅 등","src":"물류정책기본법 제2조 제1항 제2호 다목"},{"t":"물류시설운영업: 물류터미널이나 창고 등 물류시설을 운영","src":"물류정책기본법 제2조 제1항 제2호 나목"},{"t":"(2021 기출 당시 보기 분류) 하역·포장·가공·조립·상표부착·프로그램 설치·품질검사 등 부가 서비스 사업은 화물취급업","src":"기출 2021-6"},{"t":"물류체계: 효율적인 물류활동을 위하여 시설·장비·정보·조직 및 인력 등이 유기적으로 기능하도록 연계된 집합체","src":"물류정책기본법 제2조 제1항 제3호"},{"t":"데포(Depot): 국내용 2차 창고 또는 수출화물의 집화·분류·운송을 위한 내륙 CFS처럼, 대량 통합운송된 화물을 일시 보관하는 창고","src":"기출 2023-14"},{"t":"물류시설 용어: 물류터미널, 집배송센터, 공동집배송단지, 물류센터, 데포","src":"기출 2023-14"},{"t":"물류사업의 범위는 물류정책기본법 시행령 제3조(별표 1)에 규정. 물류정책기본법 제26조에 따라 고시된 기업물류비산정지침도 출제 대상","src":"이론"},{"t":"화물운송업 - 육상: 화물자동차운송사업, 화물자동차운송가맹사업, 철도사업","src":"이론"},{"t":"화물운송업 - 해상: 외항정기화물운송사업, 외항부정기화물운송사업, 내항화물운송사업","src":"이론"},{"t":"화물운송업 - 항공: 정기항공운송사업, 부정기항공운송사업, 상업서류송달업. 파이프라인운송업은 별도 세분류","src":"이론"},{"t":"물류시설운영업 - 창고업: 일반창고업, 냉장 및 냉동 창고업, 농·수산물 창고업, 위험물품보관업, 그 밖의 창고업(공동집배송센터운영업 포함)","src":"이론"},{"t":"물류시설운영업 - 물류터미널운영업: 복합물류터미널, 일반물류터미널, 해상터미널, 공항화물터미널, 화물차전용터미널, 컨테이너화물조작장(CFS), 컨테이너장치장(CY), 물류단지, 집배송단지 등 물류시설의 운영업","src":"이론"},{"t":"물류서비스업 - 화물취급업(하역업 포함): 화물의 하역, 포장, 가공, 조립, 상표부착, 프로그램 설치, 품질검사 등 부가적인 물류업","src":"이론"},{"t":"물류서비스업 - 화물주선업: 국제물류주선업, 화물자동차운송주선사업","src":"이론"},{"t":"물류서비스업 - 물류장비임대업: 운송장비·산업용 기계장비·운반용기·화물자동차·화물선박·화물항공기·운반적치하역장비·컨테이너 및 파렛트 등 포장용기 임대업, 선박대여업","src":"이론"},{"t":"물류서비스업 - 물류정보처리업: 물류정보 데이터베이스 구축, 물류지원 SW 개발·운영, 물류 관련 전자문서 처리업","src":"이론"},{"t":"물류서비스업 - 물류컨설팅업: 물류 업무프로세스 개선, 자동창고·물류자동화 설비 도입, 물류 정보시스템 도입 관련 컨설팅","src":"이론"},{"t":"해운부대사업: 해운대리점업, 해운중개업, 선박관리업","src":"이론"},{"t":"항만운송관련업: 항만용역업, 선용품공급업, 선박연료공급업, 선박수리업, 컨테이너 수리업, 예선업","src":"이론"},{"t":"항만운송사업: 항만하역사업, 검수사업, 감정사업, 검량사업","src":"이론"},{"t":"종합물류서비스업은 별도 대분류(세분류·세세분류 모두 종합물류서비스업)","src":"이론"}]},{"머리":"물류의 기본적 기능(5가지)","줄":[{"t":"장소적 기능: 운송을 통해 생산자와 소비자 간 장소적 격차를 조정해 장소적 효용 발생","src":"이론"},{"t":"시간적 기능: 보관을 통해 재화가 생산되는 시기와 소비되는 시기의 불일치를 조정해 시간적 효용 창출","src":"이론"},{"t":"수량적 기능: 집하·수배송·중계기능으로 수급불안정·과잉생산 등 생산단위와 소비단위의 수량적 불일치를 조정","src":"이론"},{"t":"가격적 기능: 운송에서 유통가공·물류정보활동 등을 통해 재화의 가격조정과 인플레이션 안정화 역할","src":"이론"},{"t":"품질적 기능: 가공·조립·포장기능 등으로 생산자가 제공하는 재화와 소비자가 소비하는 재화의 품질을 조정","src":"이론"}]},{"머리":"물류시스템의 개념과 목적","줄":[{"t":"물류시스템: 물류관리로 물적 효용을 극대화하고 운송·보관·하역·포장·물류정보·유통가공활동을 유기적으로 조정해 전체를 하나의 통합시스템으로 관리","src":"이론"},{"t":"물류시스템의 목표는 물류비용 절감과 고객서비스 개선. 두 목표는 상충관계라 적정 수준에서 결합","src":"이론"},{"t":"물류시스템은 보다 적은 물류비로 효용 창출을 극대화하고, 생산지에서 소비지까지 연계되게 구축","src":"이론"},{"t":"하부시스템: 수·배송시스템, 보관시스템, 하역시스템, 포장시스템, 정보시스템 등. 유기적으로 연계 구축","src":"이론"},{"t":"목적: 고객 주문 시 신속한 물류서비스 제공","src":"이론"},{"t":"목적: 화물 분실·오배송 감소로 신뢰성 높은 운송기능 수행","src":"이론"},{"t":"목적: 화물 변질·도난·파손 감소로 신뢰성 높은 보관기능 수행","src":"이론"},{"t":"목적: 적정 물류서비스 수준을 정한 뒤 이를 달성하는 물류비용 최소화","src":"이론"},{"t":"목적: 하역 합리화로 운송·보관 등 기능 향상","src":"이론"}]},{"머리":"물류시스템의 분류","줄":[{"t":"물류시스템 기능별 분류: 운송·보관·하역·포장·유통가공·물류정보 물류시스템","src":"기출 2020-14"},{"t":"물류시스템 영역별 분류: 구매(조달)·제조(생산)·판매·역물류시스템. 도시·지역 및 국가·국제 물류시스템은 지리적 범위에 따른 분류","src":"기출 2020-14"}]}],"함정":[{"x":"공급사슬관리를 통해 개별 기업의 독자적 경영 최적화를 달성한다.","o":"공급사슬관리는 공급사슬 전체의 최적화를 추구한다.","src":"기출 2021-5, 2025-3"},{"x":"수송기능은 물류 거점과 소비 공간을 연결하는 소량 화물의 단거리 이동을 말한다.","o":"수송은 물류거점 간 대량·장거리 이동, 소량·단거리 인도는 배송(교재 구분, 추정).","src":"기출 2021-14, 보충(추정)"},{"x":"물류 합리화를 위해서 물류하부시스템의 개별적 비용절감이 전체시스템의 통합적 비용절감보다 중요하다.","o":"전체시스템의 통합적 비용절감(총비용 관점)이 개별 하부시스템 비용절감보다 중요하다.","src":"기출 2022-1"},{"x":"운송활동은 생산시기와 소비시기의 불일치를 해결하는 기능을 수행한다.","o":"생산시기와 소비시기의 불일치를 조정하는 것은 보관활동. 운송은 장소적 효용.","src":"기출 2022-20"},{"x":"한국 물류정책기본법상 물류는 운송, 보관, 하역 등이 포함되며 가공, 조립, 포장 등은 포함되지 않는다.","o":"물류에는 운송·보관·하역과 가공·조립·분류·수리·포장·상표부착·판매·정보통신 등이 포함된다.","src":"물류정책기본법 제2조 제1항 제1호"},{"x":"사내물류 - 완제품의 판매로 출하되어 고객에게 인도될 때까지의 물류활동이다.","o":"그 설명은 판매물류. 사내물류는 생산공정 투입 후 제품 완성까지(또는 매입물자 보관창고~판매 장소까지).","src":"기출 2022-22, 2024-7, 기업물류비 산정지침 제7조 제1항 제2호"},{"x":"최근 전자상거래 활성화에 따라 물동량은 증가하는 반면 물류관리의 역할은 줄어들고 있다.","o":"전자상거래 활성화로 물동량이 늘면서 물류관리의 역할은 커지고 있다.","src":"기출 2023-6"},{"x":"생산단계에서 소비단계로의 전체적인 물적 흐름으로 조달부문을 제외한 모든 활동이다.","o":"물류(Logistics)는 조달부문을 포함한다.","src":"기출 2023-11"},{"x":"7R 원칙은 적절한 상품(Commodity), 품질(Quality), 수량(Quantity), 시간(Time), 장소(Place), 보안(Security), 가격(Price)이다.","o":"7R의 일곱째는 보안이 아니라 인상(Impression).","src":"기출 2024-1"},{"x":"보관활동은 물자를 수요가 낮은 국가에서 높은 국가로 이동시켜 물자의 효용가치를 증대시키기 위한 물류활동이다.","o":"그 설명은 운송(장소적 효용). 보관은 시간적 효용.","src":"기출 2024-3"},{"x":"사내물류는 완제품의 판매로 출하되어 고객에게 인도될 때까지의 물류활동이다.","o":"판매물류의 설명이다.","src":"기출 2024-7"},{"x":"물류는 통합적 물류관리의 개념에서 출발하여 물류영역 전반의 최적화를 거쳐 최종적으로 개별 기업의 물류생산성 제고의 차원으로 발전하였다.","o":"부문별 효율화(물적유통) → 기업 내 효율화(로지스틱스) → 공급사슬 전반(SCM)으로 확대되었다.","src":"기출 2025-3"},{"x":"소비자 니즈(needs)의 다양화로 소품종 대량생산이 증가하여 물류관리의 중요성이 증가하고 있다.","o":"다품종 소량생산이 증가하여 중요성이 커졌다.","src":"기출 2025-5"},{"x":"물류는 마케팅믹스의 4P 중 제품(product)과 가장 밀접한 관계가 있다.","o":"4P 중 유통(Place)과 가장 밀접.","src":"기출 2025-6"},{"x":"물적유통은 자재관리를 포함하는 물류개념이다.","o":"출제 오답(바른 서술 미확인). 자재관리를 포함하는 것은 로지스틱스 쪽으로 정리됨(추정).","src":"기출 2026-1"},{"x":"로지스틱스는 완성품을 소비자에게 유통하는 물류관리활동을 의미한다.","o":"완성품을 소비자에게 유통하는 활동은 물적유통(판매영역 중심)이다. 로지스틱스는 조달·생산·판매·회수를 포함.","src":"기출 2026-1, 2024-1"},{"x":"AMA(American Marketing Association)는 로지스틱스를 “생산지로부터 소비지까지 제품을 이동하고 취급하는 것”으로 정의한다.","o":"출제 오답(바른 수치 미확인). 그 정의는 물적유통(PD) 정의로 정리됨(추정).","src":"기출 2026-1, 보충(추정)"},{"x":"시대의 흐름에 따라 물류의 개념은 로지스틱스에서 물적유통관리로 발전되었다.","o":"물적유통 → 로지스틱스 → SCM 순서로 발전.","src":"기출 2026-1, 2025-3"},{"x":"리버스(Reverse)물류란 생산과정에서 발생한 불량품을 제조공정으로 재투입하는 물류활동이다.","o":"리버스물류는 회수·폐기·반품물류를 포함. 소비자로부터 회수되어 폐기될 때까지의 흐름.","src":"기출 2026-2, 기업물류비 산정지침 제7조 제1항 제4호"},{"x":"7R 원칙이란 적절한 상품(Commodity), 품질(Quality), 수량(Quantity), 경향(Trend), 장소(Place), 인상(Impression), 가격(Price)이 고려된 원칙이다.","o":"7R은 상품(Commodity)·품질(Quality)·수량(Quantity)·시간(Time)·장소(Place)·인상(Impression)·가격(Price). 경향(Trend)은 7R이 아님","src":"기출 2020-1"},{"x":"하역물류는 재화와 용역이 효용가치가 낮은 장소로부터 높은 장소로 이동시켜 효용가치를 증대한다.","o":"이는 운송(수배송)물류의 설명. 하역물류는 물자를 취급하고 이동하며 상·하차하는 행위로 운송·보관의 효율 향상을 지원","src":"기출 2020-2"},{"x":"정보물류는 물자의 수배송, 보관, 거래, 사용 등에 있어 적절한 재료, 용기 등을 이용하여 보호하는 기술이다.","o":"이는 포장물류의 설명. 정보물류는 물류활동 관련 정보를 제공해 물류관리 기능을 연결하고 효율화","src":"기출 2020-2"},{"x":"유통가공물류는 물류활동과 관련된 정보 내용을 제공하여 물류관리 기능을 연결시켜 물류관리의 효율화를 추구한다.","o":"이는 정보물류의 설명. 유통가공물류는 물품 자체의 기능을 변화시키지 않고 간단한 가공·조립·재포장 등으로 부가가치를 부여","src":"기출 2020-2"},{"x":"수배송물류는 물자를 취급하고 이동하며, 상·하차하는 행위 등 주로 물자의 선적·하역 행위이다.","o":"이는 하역물류의 설명. 수배송물류는 물자를 장소적으로 이동시켜 장소적 효용을 창출","src":"기출 2020-2"},{"x":"물적유통은 로지스틱스보다 관리범위가 넓다.","o":"로지스틱스가 물적유통보다 범위가 넓다(물적유통 → 로지스틱스 → SCM 순으로 확대)","src":"기출 2020-5"},{"x":"로지스틱스는 기업 간 정보시스템 통합을 추구한다.","o":"로지스틱스는 기업 내 물류효율화를 추구. 기업 간 통합은 SCM 단계","src":"기출 2020-5"}]},"#2":{"묶음":[{"머리":"물류환경 변화 방향","줄":[{"t":"국가 차원의 글로벌 종합물류기업 육성정책 시행","src":"기출 2021-4, 2024-2"},{"t":"e-비즈니스 확산으로 Door-to-Door 일관배송, 당일배송 증가. 전자상거래·홈쇼핑·온라인쇼핑으로 택배시장 확대","src":"기출 2021-4, 2024-2, 2025-4"},{"t":"유통가공·맞춤형 물류기능 확대 등 고부가가치 물류서비스 발전","src":"기출 2021-4"},{"t":"수요예측 등 종합적 물류계획의 수립·관리가 중요해짐","src":"기출 2021-4, 2024-2"},{"t":"노동력 부족·공해·교통 문제·지가 상승 등 사회적 환경변화로 물류비 절감의 중요성이 증가","src":"기출 2022-24"},{"t":"소품종 대량생산 → 다품종 소량생산으로 변화. 소량·다빈도 배송 증가","src":"기출 2022-24, 2026-3, 2025-4"},{"t":"국제화·글로벌 전략으로 국제물류의 중요성이 증가하고 물류관리 범위가 확대","src":"기출 2022-24, 2026-3"},{"t":"기후변화·친환경 물류정책으로 녹색물류 중요성이 증가하고 탄소배출 감축 방향으로 변화. 물류활동 폐기물 최소화 요구","src":"기출 2022-24, 2023-7, 2026-3"},{"t":"경제규모 확대에 따른 화물량 증가로 SOC 수요는 급증하나 물류 기반시설이 부족해 기업 원가부담이 가중","src":"기출 2023-7"},{"t":"정보기술·자동화기술 확산으로 물류작업의 고속화·효율화, 적정 재고관리 추진","src":"기출 2023-7"},{"t":"소비자 니즈 다양화와 제품 수명주기 단축으로 과잉재고를 지양하는 경향 심화","src":"기출 2023-7"},{"t":"하역의 로봇화, 화물의 단위적재 도입 등으로 물류 신속화·자동화 추구","src":"기출 2025-4"},{"t":"물류서비스 향상·비용절감을 위해 아웃소싱과 3PL 활용","src":"기출 2024-2, 2025-4"},{"t":"기업 간 경쟁 심화는 물류비용을 증대시키는 요인으로 작용","src":"기출 2026-3"},{"t":"기업 핵심역량 강화를 위해 물류기능을 전문업체에 아웃소싱하는 3PL·4PL 활용이 크게 증가","src":"이론"},{"t":"제조업 중심 생산자 물류에서 고객 중심 소비자 물류로 전환. 다품종 소량생산·다빈도 배송이 중요시됨","src":"이론"},{"t":"IoT·인공지능 기반 스마트팩토리가 고객맞춤형·다품종 소량생산·다빈도화를 촉진","src":"이론"},{"t":"유통시장 개방과 유통의 대형화로 유통채널 주도권이 제조업체에서 유통업체로 이전","src":"이론"},{"t":"환경문제가 중시되며 그린물류에 대한 관심 증가","src":"이론"},{"t":"물류국제화로 국내시장에서도 세계적 물류기업과의 경쟁 심화","src":"이론"},{"t":"CRM·SCM 등 정보기술을 이용한 물류관리체계의 합리화 정착","src":"이론"},{"t":"최종 사용자 중심의 부가가치 개념을 중시해 e-Logistics, e-SCM, e-Marketplace 등장","src":"이론"},{"t":"최근 물류환경은 물류효율성 측면에서 상물분리 개념이 확대(상물일치 확대가 아님)","src":"이론"}]},{"머리":"물류환경 변화의 요인","줄":[{"t":"제조부문의 원가절감이 한계에 부딪침","src":"이론"},{"t":"물류비용 절감과 서비스 향상이 기업경쟁력의 핵심요소로 인식됨","src":"이론"},{"t":"고객 요구의 다양화·전문화·고도화에 대한 대응 필요","src":"이론"},{"t":"기업 간 경쟁우위 확보를 위한 물류부문 변화 필요","src":"이론"},{"t":"재고비 증가, 운송시간과 비용의 상승","src":"이론"},{"t":"다품종·소량·다빈도·신속·정시·유통가공의 지속적 증가","src":"이론"},{"t":"운송·보관·하역·포장 및 물류정보 기술의 지속적 발전","src":"이론"},{"t":"생산혁신 및 마케팅을 통한 이익실현의 한계","src":"이론"},{"t":"글로벌화로 국제물류의 범위 확대","src":"이론"},{"t":"에너지 절감·친환경 물류·안전·보안을 강화한 물류의 필요성 증가","src":"이론"}]},{"머리":"2030 국가물류기본계획 6대 전략","줄":[{"t":"전략 1: 첨단 스마트 기술기반 물류시스템 구축과 디지털 전환 추진. 세부목표: R&D 상용화, 물류 R&D 투자, 물류 정보화 향상","src":"이론"},{"t":"전략 2: 단절 없는 물류서비스를 위한 공유·연계 인프라 및 네트워크 구축. 세부목표: 도시 물류 인프라 재정비, 공·항만 배후단지 투자 유치 활성화, 연계수송네트워크 구축, 지역 물류 인프라 확충","src":"이론"},{"t":"전략 3: 사람중심 좋은 일자리 마련과 수요자 관점의 고품질 물류서비스 창출. 세부목표: 전문물류인력 확보, 택배 서비스 수준, 물류산업 안전 향상, 물류산업 일자리 증가","src":"이론"},{"t":"전략 4: 지속가능한 물류산업 환경 조성. 세부목표: 공동화 제고, 친환경 운송수단 보급, 대량운송수단 활용 제고, 영업용 중심 도로 화물 수송 체계 구축, 자발적 기업참여 유도, 글로벌 환경규제 대응, 재난·재해 대응 물류체계","src":"이론"},{"t":"전략 5: 새로운 수요 대응을 위한 물류산업 경쟁력 강화 및 체질 개선. 세부목표: 국가물류비 절감, 글로벌 물류기업 육성, 물류기업의 수익성 제고, 물류시장의 확대, 물류 새싹기업 육성, 중소물류기업의 경쟁력 제고, 택배시장규모","src":"이론"},{"t":"전략 6: 글로벌 경제지도 변화에 따른 전략적 해외 시장 진출. 세부목표: 공·항만 허브기능 역량 강화, 국가물류서비스 품질 제고, 글로벌 네트워크 구축, 물류기업의 해외매출 확대, 해운시장 국제경쟁력 강화","src":"이론"}]},{"머리":"최근 물류관련 이슈","줄":[{"t":"글로벌 물류환경 변화: 물류산업의 국제화·대형화(국내시장에서도 세계적 물류기업과 경쟁 심화), 전략적 아웃소싱 증가, 친환경 녹색물류 중요성 부각(2016년 발효 파리협약), 물류보안 강화(9·11 이후)","src":"이론"},{"t":"글로벌 공급사슬(GVC) 재편: 주요국의 보호무역주의·자국 내 공급망 강화로 WTO 중심 다자주의 체제 재편. 코로나19로 공급망 효율성보다 안정성을 중시. 특정 국가 과도한 의존도를 줄이고 역내 핵심소재·부품·장비 대체 공급망 마련","src":"이론"},{"t":"콜드체인: 신선도 유지가 필요한 농·수산·축산물, 긴급 의료용품 등의 온도를 관리하는 공급사슬. 코로나19 백신·혈액·장기 운송 등 고부가가치 분야. 기능별로 냉장 운송시장·냉장 보관시장, 품목별로 식품 콜드체인·바이오·의약품 콜드체인","src":"이론"},{"t":"식품 콜드체인 관리 목적: 식품 안전, 식품의 맛 유지, 식자재 폐기물 발생 억제. 농산품 콜드체인은 농장에서 소비자 식탁까지 전 과정의 온도 등을 관리","src":"이론"},{"t":"스마트 물류(물류 4.0): 운송 기계화·자동화 → 하역 기계화·자동화 → 물류시스템 정보화 → 물류의 스마트화 단계로 발전","src":"이론"},{"t":"관세청은 2018년 세계 최초로 블록체인 기반 플랫폼을 구축해 수출 통관업무 효율을 높임. AI·IoT·물류로봇·AR/VR·빅데이터 활용, 드론 배송·라스트마일 배송·풀필먼트 물류센터·스마트물류센터 도입","src":"이론"},{"t":"퍼스트마일: 제조기업이 풀필먼트 센터까지 제품을 인도하는 단계. 라스트마일: 풀필먼트센터 등에서 최종 고객에게 인도되는 단계. 전자상거래 확산으로 중요하나 물류비 증가. 공급자 측에서 전체 물류비의 반 이상(53%)을 차지하며 노동집약적","src":"이론"}]}],"함정":[{"x":"기업의 핵심역량 강화를 위해서 물류기능을 직접 수행하는 화주기업이 증가하는 추세이다.","o":"핵심역량 강화를 위해 물류를 외부에 위탁(아웃소싱·3PL)하는 화주기업이 증가하는 추세이다.","src":"기출 2021-4, 2024-2"},{"x":"전자상거래의 확산으로 인해 라스트마일(Last Mile) 물류비가 감소하고 있다.","o":"출제 오답(바른 수치 미확인). 라스트마일 물류의 중요성과 비용 부담은 커지고 있다(추정).","src":"기출 2022-24, 보충(추정)"},{"x":"소비자 니즈(Needs)의 다양화에 따라 상품의 수요패턴이 소품종, 대량화되고 있다.","o":"다품종, 소량화되고 있다.","src":"기출 2023-7"},{"x":"소비자 중심 물류로의 전환으로 인하여 소품종 대량생산의 중요성이 증가하고 있다.","o":"다품종 소량생산이 늘어난다.","src":"기출 2024-2"},{"x":"물류의 중요성이 증가하여 상물일치의 개념이 확대되고 있다.","o":"상류(거래)와 물류를 분리하는 상물분리가 확대되고 있다(추정).","src":"기출 2025-4, 2026-3, 보충(추정)"},{"x":"물류의 중요성이 높아짐에 따라 상물일치의 개념이 확산되고 있다.","o":"상물분리의 개념이 확산(추정).","src":"기출 2026-3, 보충(추정)"},{"x":"제조업 중심의 생산자 물류에서 고객 중심의 소비자 물류로 전환되고 있어, 소품종 대량생산이 중요시되고 있다.","o":"소비자 물류로 전환되어 다품종 소량생산과 다빈도 배송이 중요시됨","src":"기출 2020-4"},{"x":"화물주선업: 화물의 하역, 포장, 가공, 조립, 상표부착, 프로그램 설치, 품질검사업","o":"이는 화물취급업(하역업 포함)의 세세분류. 화물주선업은 국제물류주선업·화물자동차운송주선사업","src":"기출 2020-6"}]},"#3":{"묶음":[{"머리":"물류관리 원칙 (2024 기출)","줄":[{"t":"신뢰성의 원칙: 필요한 물량을 원하는 시기와 장소에 공급하여 사용할 수 있도록 보장","src":"기출 2024-4"},{"t":"균형성의 원칙: 생산·유통·소비에 필요한 물자의 수요와 공급 및 조달과 분배의 균형 유지","src":"기출 2024-4"},{"t":"단순성의 원칙: 불필요한 유통과정을 제거하여 물자지원체계를 단순화·간소화","src":"기출 2024-4"},{"t":"경제성의 원칙: 최소한의 자원으로 최대한의 물자공급 효과를 추구하여 물류관리 비용을 최소화","src":"기출 2024-4"},{"t":"저장시설 보호 및 도난·망실·화재·파손 등으로부터 화물을 보호하는 원칙은 경제성이 아닌 다른 원칙(원칙명 미확인)","src":"기출 2024-4"},{"t":"보호의 원칙: 생산·유통·소비 분야 물자저장시설의 보호를 철저히 경계하고, 물자운송과정에서도 도난·망실·화재·파손으로부터 보호","src":"이론"},{"t":"적시성 원칙: 필요한 수량만큼 필요한 시기에 공급해 고객 만족도를 높이고 재고비용을 최소화","src":"이론"},{"t":"집중지원 원칙: 물자가 요구되는 상황에 따라 물량·장소·시기의 우선순위별로 집중하여 제공","src":"이론"},{"t":"간편성(단순성) 원칙: 물류계획·물류조직·물류수급 절차 등을 가장 간단·명료하게 단순화해야 효율적","src":"이론"},{"t":"물류관리 7원칙(한 분류): 신뢰성·경제성·적시성·균형성·간편성·집중지원·보호","src":"이론"}]},{"머리":"물류시스템 설계·관리의 기본 개념","줄":[{"t":"물류시스템 설계·범위 결정의 기준은 총비용 개념","src":"기출 2021-10"},{"t":"물류활동의 중심은 운송·보관·하역·포장 등이며 비용과 서비스 면에서 상충(trade-off) 관계","src":"기출 2021-10, 2022-26"},{"t":"취급 제품이 다양할수록 재고가 증가하고 비용상승 요인","src":"기출 2021-10"},{"t":"도로·철도·항만·공항 등 교통시설과의 접근성 고려","src":"기출 2021-10"},{"t":"고객서비스 달성 목표를 높이면 물류비용이 증가할 수 있음","src":"기출 2022-26"},{"t":"효과적 물류관리는 기능별 개별 물류비 절감보다 총물류비 절감","src":"기출 2024-8, 2026-10"},{"t":"물류서비스 수준은 매출액과 총물류비를 비교해 이윤이 극대화되는 수준으로 결정","src":"기출 2026-10"},{"t":"리드타임의 변동성은 안전재고 수준과 품절비용에 영향","src":"기출 2026-10"},{"t":"고객서비스 수준을 높이는 요인: EDI 도입, 리드타임 단축, 재고수준 상향, 물류거점 수 증가","src":"기출 2025-8"},{"t":"물류시스템 설계 시 고려: 고객서비스 수준 개선과 물류비 절감의 상충관계","src":"이론"},{"t":"물류시스템 설계 시 고려: 공동수·배송으로 인한 물류비 절감과 리드타임 증가 간의 상충관계","src":"이론"},{"t":"물류시스템 설계 시 고려: 고객 수요에 따른 재고수준 결정, 운송수단과 운송경로 결정","src":"이론"},{"t":"물류시스템 설계 시 고려: ISO 14001을 통한 환경친화적 물류시스템 방침·목표","src":"이론"},{"t":"물류시스템 설계 시 고려: 과잉포장 개선으로 폐기물 최소화와 용기 표준화","src":"이론"},{"t":"물류시스템 설계 시 고려: 미배송 잔량을 체크해 주문충족의 완전성 확보","src":"이론"},{"t":"물류시스템 구축방향: 수·배송·포장·보관·하역 등 주요 부문을 유기적으로 연계. 기존 제도·절차 개선으로 비용 절감과 서비스 향상 추구. 기업 이익을 최대화하는 방향. 장기적·전략적 사고 도입","src":"이론"},{"t":"물류시스템 구축절차: 목표·제약조건 설정 → 전담조직 구성 → 데이터 수집 → 데이터 분석 → 모델구축 및 시스템 적용 → 시스템 유지·관리","src":"이론"}]},{"머리":"물류관리 전략과 계획","줄":[{"t":"물류관리전략의 목표: 비용절감, 서비스 개선 등","src":"기출 2022-26"},{"t":"물류전략은 기업전략과 독립적이 아니라 기업전략에 연계되어 수립","src":"기출 2022-26, 2026-10"},{"t":"물류관리계획은 전략계획 → 전술계획 → 운영계획으로 단계적 수립","src":"기출 2022-26, 2025-6"},{"t":"제품수명주기별 물류전략: 도입기, 성장기, 성숙기, 쇠퇴기","src":"기출 2022-26, 2023-3, 2026-10"},{"t":"도입기: 거점 수·재고수준 결정 정보가 적어 물류관리자의 판단에 따른 계획이 필요","src":"기출 2025-9"},{"t":"성장기: 규모의 경제 달성 물류활동 필요, 비용과 서비스 간 상충관계를 본격 고려","src":"기출 2025-9"},{"t":"전략적 의사결정 활동 예: 시설 입지계획. 제품포장·재고통제·창고관리·주문품 발송은 운영적 활동","src":"기출 2021-9"},{"t":"물류관리전략: 상충관계에 있는 물류비용과 고객서비스 수준을 알맞게 조절해 물류효율성을 높임","src":"이론"},{"t":"효과적 물류관리전략: 유연성을 보유하면서 고객의 다양한 요구를 저렴한 비용으로 충족","src":"이론"},{"t":"물류관리전략 설정 시 우선 고려사항: 고객의 니즈 파악","src":"이론"},{"t":"고객서비스 평가의 중점 관리 척도: 주문 후 인도까지의 소요시간, 고객 주문에 대한 제품의 가용성, 주문처리의 정확성","src":"이론"},{"t":"SCM으로 구성원 간 파트너십을 구축하고 실시간 정보를 공유·협력해 공급사슬 전체의 이익을 극대화","src":"이론"},{"t":"물류관리의 전략적 중요성: 다품종 소량생산 시대에 물류비용이 증가해 효율적 물류관리 수단 필요","src":"이론"},{"t":"물류관리 목표는 전체 최적화 관점에서 물류비용을 절감하고 고객서비스를 향상해 새로운 부가가치를 창출","src":"이론"},{"t":"물류 통합이 기업 경계를 넘어 SCM 전체로 확대되면서 데이터와 프로세스의 표준화가 필요. 전체 효율화와 부문 간 결합을 위해 물류정보시스템 구축이 필요","src":"이론"},{"t":"기업의 물류관리는 구매·생산·영업·마케팅 활동과 상호 밀접","src":"이론"},{"t":"물류경영: 조직 구성원이 목표 달성을 위해 인적·물적 자원을 포함한 기업 내 경쟁력 있는 핵심역량을 조합하는 과정. 계획-조직-지휘-통제 관련 의사결정을 수행","src":"이론"},{"t":"계획화(Planning): 경영자가 목표를 설정하고 계획을 수립하는 과정. 자원배분과 조직원 활동에 대한 의사결정과정","src":"이론"},{"t":"물류계획은 기간과 의사결정 중요도에 따라 전략·전술·운영의 3단계","src":"이론"},{"t":"전략계획: 1~5년 또는 그 이상의 장기계획. 주로 공급사슬의 구조에 관한 의사결정","src":"이론"},{"t":"전술계획: 3개월~1년 정도의 중기계획. 개별품목이 아닌 제품군 위주","src":"이론"},{"t":"운영계획: 단기계획. 개별주문의 작업순서, 생산일정계획, 차량대수 결정, 배송순서 결정 등 운송일정계획","src":"이론"},{"t":"의사결정 주체: 전략은 최고경영층(CEO), 전술은 중간경영자, 운영은 일선관리자","src":"이론"},{"t":"의사결정 기간·환경·관점: 전략은 중·장기, 비반복적·비구조적, 전사적 관점. 전술은 중기, 반복성·구조화 정도와 관점은 전략과 운영의 중간. 운영은 단기, 반복적·구조적, 기능적 관점","src":"이론"},{"t":"운송관리 예: 전략 - 운송수단 선택 / 전술 - 정기·임대계약 / 운영 - 발송처리","src":"이론"},{"t":"재고관리 예: 전략 - 창고입지 결정 / 전술 - 안전재고수준 결정 / 운영 - 주문충족","src":"이론"},{"t":"창고관리 예: 전략 - 배치(Lay-Out)도 설계 / 전술 - 공간이용·활용도 / 운영 - 오더(주문) 피킹","src":"이론"},{"t":"물류전략: 기업의 사명·목표 달성, 환경 변화 대응, 경쟁우위 확보를 위해 전략을 수립·실행하는 과정","src":"이론"},{"t":"물류전략 수립 과정: 기업 목표 설정(계량화·계층화·실현가능성) → 환경 분석(SWOT·산업구조분석·가치사슬분석) → 전략 수립(기업전략·사업부전략) → 전략 실행(실행 및 피드백)","src":"이론"},{"t":"안소프(I. Ansoff) 기업수준 전략: 전사적 차원의 장기적 발전을 위한 자원배분·의사결정. 기업의 성장·유지·축소, M&A, 전략적 제휴, 해외투자","src":"이론"},{"t":"안소프 사업수준 전략: 사업부 단위의 경쟁우위 확보·유지 전략. 경쟁우위전략, 차별화, 집중화, 비용절감, 서비스개선","src":"이론"},{"t":"안소프 기능수준 전략: 기업 내 각 기능별 자원의 효율적 운영과 관련된 일상적 전략. 인력선발, 신기술도입, 자본조달, 마케팅·영업전략","src":"이론"},{"t":"물류관리전략 추진단계 대응(기출): 유통경로·물류 네트워크 설계 = 구조적(관리적) 단계, 최적의 서비스 수준 결정 = 전략적 단계, 물류거점·운송·재고관리 = 기능적 단계, 정보화 정책·설비 도입 = 실행 단계","src":"기출 2020-9"},{"t":"물류시스템 설계 시 운영적 계획의 고려사항은 주문처리(주문충족·발주·재고보충). 대고객 서비스 수준·설비 입지·운송수단과 경로·재고정책은 운영적 계획이 아님","src":"기출 2020-15"}]},{"머리":"물류시스템 설계 수준 (Robeson & Copacino, James & William)","줄":[{"t":"수준 구분: 전략적 → 구조적 → 기능적 → 실행적(이행) 수준","src":"기출 2022-7, 2024-9"},{"t":"구조적 수준: 유통경로 설계, 네트워크 전략","src":"기출 2024-9"},{"t":"기능적 수준: 창고설계 및 운영, 수송관리, 자재관리","src":"기출 2022-7, 2026-9"},{"t":"고객서비스는 기능적·구조적 수준이 아님(전략적 수준으로 정리됨, 추정)","src":"보충(추정)"},{"t":"설비 및 장치는 기능적·구조적 수준이 아님(실행적 수준으로 정리됨, 추정)","src":"보충(추정)"},{"t":"전략적 단계: 고객이 원하는 것을 파악하는 동시에 회사의 이익목표를 달성할 수 있는 최적의 고객서비스 수준을 정하는 단계","src":"이론"},{"t":"관리적(구조적) 단계: 원·부자재 공급에서 생산과정을 거쳐 완제품 유통과정까지의 흐름을 최적화하기 위해 유통경로와 물류 네트워크를 설계하는 단계","src":"이론"},{"t":"기능적 단계: 물류거점 설계 및 운영, 운송관리, 자재 및 재고관리를 하는 단계","src":"이론"},{"t":"실행단계: 정보시스템 구축 관련 정책·절차 수립, 정보화 설비·장비를 도입·조작·변화관리를 하는 단계","src":"이론"}]},{"머리":"물류 합리화","줄":[{"t":"제조원가 절감을 통한 이익 증대가 어려워져 물류 효율성 제고 필요성 증가","src":"기출 2025-31"},{"t":"물류 합리화 시 내부 기능 간 또는 기업 간 상충관계 발생 가능","src":"기출 2025-31"},{"t":"물류합리화: 기업은 비용절감으로 이윤을 극대화하고 고객은 적정 수준의 서비스를 받도록 물류 효율성을 높이는 것. 표준화·모듈화·공동화·상물분리가 함께 수반","src":"이론"},{"t":"물류합리화의 목표: 물류비용 절감과 고객서비스 향상. 두 목표는 상충관계라 적정 수준에서 결합","src":"이론"},{"t":"상충관계 유형: 물류비용 절감 vs 고객서비스 향상 / 고객서비스 수준 vs 보관시설 수 / 물류거점 수 증가에 따른 창고유지비용 vs 운송비 / 수송비용 vs 배송비용 / 재고유지비용 vs 운송비용","src":"이론"},{"t":"필요성: 물류서비스 원가 상승 대응, 글로벌화된 소비자 요구 변화 대응, 물류거점 집약화 등 산업계 변화 대응, 제품수명주기 단축에 따른 다품종 소량생산·소로트 다빈도 운송 대응","src":"이론"},{"t":"합리화 유형 - 생력형(省力形): 인적 노동력을 기계로 대체해 인력 절감을 주목적으로 하는 형태","src":"이론"},{"t":"합리화 유형 - 생지능형: 물류 전반에 지식기능을 갖춘 자동화로 업무량 감소와 업무능력 향상","src":"이론"},{"t":"합리화 유형 - 비용절감형: 단일 기계를 시스템화해 효과적인 시스템을 만들어 비용을 절감","src":"이론"},{"t":"합리화 유형 - 경영구조 혁신형: 기존 경영구조에서 탈피해 경영구조를 혁신","src":"이론"},{"t":"기능별 합리화 - 운송: 수·배송차량과 장비 현대화, 최적 운송수단 선택과 차량 대형화, ITS 활용 복화운송·영차율 향상","src":"이론"},{"t":"기능별 합리화 - 보관: 창고 기계화·자동화(WMS), 물류정보화를 통한 재고관리 개선, 거점별 물류센터 운영","src":"이론"},{"t":"기능별 합리화 - 하역: 기계화·자동화·표준화·단위화, 불필요한 중복작업 제거","src":"이론"},{"t":"기능별 합리화 - 포장: 대형화·대량화·규격화·표준화, 양질의 포장재료 개발, 포장을 고려한 제품설계","src":"이론"},{"t":"기능별 합리화 - 물류정보: 인터넷을 통한 물류정보 수집·활용, EDI·POS·RFID 구축과 SCM을 통한 정보통합","src":"이론"},{"t":"기능별 합리화 - 물류조직: 조직 내 물류 전담부서로 통합 관리, 수준별 물류전략을 SCM 관점의 전사적 계획으로 수립","src":"이론"},{"t":"상물분리: 상류(상적유통경로)와 물류(물적유통경로)가 같은 경로로 흘러 시간·비용이 과다 소비되던 문제를 두 경로로 분리해 물류 효율을 높이는 것","src":"이론"},{"t":"상물분리 효과: 영업력 강화 및 물류 전문화, 물류비 절감과 고객서비스 향상, 운송경로 단축·차량 대형화로 운송비 절감","src":"이론"},{"t":"상물분리 효과: 수주 통합으로 배송차량 적재율 향상, 재고의 편재·과부족 해소, 물류활동의 기계화·자동화, 저비용 고효율의 물류실현","src":"이론"}]},{"머리":"물류거점 수와 비용의 관계","줄":[{"t":"물류거점(창고) 수가 늘면 거점비용이 증가(창고 유지비 증가, 불확실한 수요에 대한 안전재고 증가)","src":"이론"},{"t":"창고 수가 많을수록 거점에서 최종 목적지까지 운송거리가 줄어 운송비가 감소","src":"이론"},{"t":"창고 수가 많을수록 보관 재고량이 늘어 재고유지비용이 증가","src":"이론"},{"t":"창고 수가 늘수록 수·배송 리드타임이 감소하고 고객서비스가 증가","src":"이론"},{"t":"총비용은 거점 수가 늘면 처음에는 감소하다가 재고비와 운송비가 교차하는 지점을 지나면 증가. 최적점은 총비용 최소점이면서 고객서비스가 높은 지점","src":"이론"},{"t":"배송차량 대형화와 화물 혼적(공동수·배송)은 적재율 향상과 운송비 절감이 가능하나 리드타임이 길어져 서비스 수준이 낮아질 수 있음","src":"이론"}]},{"머리":"제품수명주기별 물류전략(PLC)","줄":[{"t":"제품수명주기(PLC): 도입기 → 성장기 → 성숙기 → 쇠퇴기","src":"이론"},{"t":"도입기: 마케팅 목표는 제품 인지도 제고. 물류활동은 소수 혁신층 확보·제품가용성 제한. 매출액 낮음, 이익 적자 또는 극소. 핵심제품(기본사양), 원가기준가격, 조기 사용유도를 위한 강력한 촉진","src":"이론"},{"t":"성장기: 마케팅 목표는 시장점유율 극대화(소비자 구전이 중요). 물류활동은 물류비와 서비스 간 상충관계 고려·규모의 경제 실현. 매출 급격 성장, 한계이익 최대. 제품가용성 확대·제품보증 강화, 시장침투가격","src":"이론"},{"t":"성숙기: 마케팅 목표는 시장점유율 방어 및 이윤극대화. 물류활동은 차별화된 물류서비스 제공·다수의 거점 필요. 최대 매출액에서 체감적으로 증가, 최대 총이익에서 점차 감소. 제품 전문화·브랜드 강화, 경쟁자기준가격, 브랜드 차별화·상표전환 유도","src":"이론"},{"t":"쇠퇴기: 마케팅 목표는 철수를 위한 회수 또는 회생. 물류활동은 위험 최소화 전략. 매출·이익 감소. 취약품목 포기, 가격인하, 최소한의 촉진 또는 재마케팅 촉진","src":"이론"},{"t":"도입기 물류전략: 소수의 지점에 집중된 물류 네트워크 구축","src":"기출 2020-10"},{"t":"물류거점 집약화 효과: 공장~물류거점 운송경로 통합으로 대형차량 이용, 지점·영업소 수주 통합으로 안전재고 감소, 운송차량 적재율 향상, 물류거점의 기계화·창고 자동화 추진","src":"기출 2020-13"}]}],"함정":[{"x":"소비자 서비스는 모든 제품에 대해서 동일한 수준으로 제공되어야 한다.","o":"제품별로 서비스 수준을 차등화한다.","src":"기출 2021-10"},{"x":"물류관리의 중요성이 높아짐에 따라 물류전략은 기업전략과 독립적으로 수립되어야 한다.","o":"물류전략은 기업전략에 정합되게 수립한다.","src":"기출 2022-26"},{"x":"물류전략은 기업전략(Corporate strategy)의 상위개념으로 수립되어야 한다.","o":"물류전략은 기업전략의 하위전략으로 수립한다.","src":"기출 2026-10"},{"x":"제조업체가 핵심역량인 제조에 집중하기 위해서는 자가물류의 확대가 필요하다.","o":"핵심역량 집중을 위해서는 물류 아웃소싱(3PL) 확대가 필요하다.","src":"기출 2025-31"},{"x":"일반적으로 고객서비스 수준이 높아지면 물류비가 절감되고 매출액은 증가한다.","o":"서비스 수준이 높아지면 물류비는 증가한다(상충관계).","src":"기출 2021-8"},{"x":"고객만족을 위해 물류서비스 수준을 높이면 물류비는 절감된다.","o":"물류비는 증가한다.","src":"기출 2024-8"},{"x":"고객서비스 수준이 높아지면 물류비가 절감되고 매출액은 증가한다.","o":"서비스 수준이 높아지면 물류비는 증가한다.","src":"기출 2025-8"},{"x":"원·부자재 공급~완제품 유통 흐름을 최적화하기 위해 유통경로 및 물류 네트워크를 설계하는 단계는 전략적 단계이다.","o":"유통경로·물류 네트워크 설계는 구조적(관리적) 단계. 전략적 단계는 고객이 원하는 것을 파악하고 최적의 서비스 수준을 정하는 단계","src":"기출 2020-9"},{"x":"[제품수명주기 중 도입기의 물류전략] 광범위한 유통지역을 관리하기 위해 다수의 물류센터를 구축한다.","o":"도입기는 소수 지점에 집중된 물류 네트워크. 다수 거점은 성숙기 특징","src":"기출 2020-10"},{"x":"[제품수명주기 중 도입기의 물류전략] 경쟁이 심화되는 단계이므로 고객별로 차별화된 물류서비스를 제공한다.","o":"차별화된 물류서비스 제공은 성숙기 특징. 도입기는 소수 혁신층 확보·제품가용성 제한","src":"기출 2020-10"},{"x":"[제품수명주기 중 도입기의 물류전략] 장기적인 시장 점유율 확대를 위해 대규모 물류 네트워크를 구축한다.","o":"도입기는 소수 지점에 집중된 물류 네트워크. 시장점유율 극대화·규모의 경제는 성장기","src":"기출 2020-10"},{"x":"[제품수명주기 중 도입기의 물류전략] 물류센터를 통폐합하여 소수의 재고 보유 거점을 확보한다.","o":"출제 오답(바른 설명: 도입기는 소수의 지점에 집중된 물류 네트워크)","src":"기출 2020-10"},{"x":"[물류거점 집약화의 효과] 물류거점에서 재고집약과 재고관리를 함으로써 재고의 편재는 해소되나 과부족 발생가능성이 높아진다.","o":"재고를 집약·관리하면 재고의 편재와 과부족이 해소됨","src":"기출 2020-13"}]},"#4":{"묶음":[{"머리":"목표와 개념","줄":[{"t":"고객서비스의 목표: 고객만족을 통한 고객감동의 실현","src":"기출 2021-8"},{"t":"물류서비스의 목표: 서비스 향상과 물류비 절감을 통한 경영혁신","src":"기출 2021-8"},{"t":"경제적 관점의 최적 물류서비스 수준: 물류활동에 의한 이익을 최대화하는 수준","src":"기출 2021-8"},{"t":"고객서비스 수준은 시장점유율과 수익성에 영향","src":"기출 2021-8"},{"t":"고객 만족도는 기대(Expectation)수준과 성과(Performance)수준의 차이로 설명","src":"기출 2024-6"},{"t":"서비스 품질은 고객과 서비스 제공자 간 상호작용으로 결정","src":"기출 2024-6"},{"t":"제품 가용성(Availability) 정보제공은 물류서비스 신뢰성에 영향을 준다","src":"기출 2024-6"},{"t":"서비스 수준이 정해지지 않았다면 수익과 비용을 동시에 고려해 최적 서비스수준을 결정","src":"기출 2024-6"},{"t":"물류 고객서비스: 물류기업이 화주나 최종소비자에게 운송·보관·하역 등 서비스를 제공해 고객만족을 개선하는 활동. 물품 이동의 마지막 단계로서 부가상품(augmented product)의 역할도 함","src":"이론"},{"t":"물류서비스 차별화는 경쟁우위 확보의 중요 전략. 서비스 혁신·벤치마킹으로 경쟁력 강화","src":"이론"},{"t":"물류비를 최소화하면 고객서비스는 크게 낮아짐. 고객이 원하는 적정 서비스 수준을 정한 뒤 그 범위 내에서 물류비를 최소화","src":"이론"},{"t":"물류서비스 수준 향상은 고객과의 장기적 관계 형성에 도움. 수준 결정 시 시장 환경·경쟁 환경을 고려","src":"이론"},{"t":"물류서비스 향상을 효율적으로 실행하려면 3S1L 원칙과 7R 원칙을 고려","src":"이론"},{"t":"서비스 수준은 최대화가 아니라 적정화가 중요(서비스와 비용은 상충관계)","src":"이론"}]},{"머리":"SERVQUAL 5차원","줄":[{"t":"유형성(Tangibles)·신뢰성(Reliability)·반응성(대응성, Responsiveness)·확신성(Assurance)·공감성(Empathy)","src":"기출 2024-13, 2026-7"},{"t":"5차원이 아닌 것으로 출제: 무형성(Intangibility), 규칙성(Regularity)","src":"기출 2024-13, 2026-7"},{"t":"SERVQUAL: 서비스 품질 측정방법으로 가장 일반화된 모형. PZB(Parasuraman, Zeithaml, Berry)가 개발. 무형성 때문에 품질측정이 곤란했던 문제를 개선","src":"이론"},{"t":"서비스 품질은 고객이 서비스 제공 전에 기대하는 것과 완료 후 성과(인지수준) 간 차이로 결정","src":"이론"},{"t":"구성항목 RATER: 신뢰성(Reliability)·확신성(Assurance)·유형성(Tangibles)·공감성(Empathy)·응답성(Responsiveness)","src":"이론"},{"t":"신뢰성: 약속된 서비스를 정확히 수행하는 능력. 예: 신속·정확한 수주 정보처리, 재고관리 정확도 향상, 조달 리드타임 단축, 제품가용성 정보제공","src":"이론"},{"t":"확신성(보장성): 서비스 직원의 지식·예절, 신뢰성과 자신감을 전달하는 능력과 안정성","src":"이론"},{"t":"유형성: 물리적 시설·직원·장비 등 외관으로 확인 가능한 설비","src":"이론"},{"t":"공감성: 개별적 배려·관심, 원활한 의사소통, 고객에 대한 충분한 이해","src":"이론"},{"t":"응답성(반응성): 고객에 대한 대응성. 신속한 서비스를 제공하는 종업원의 자세","src":"이론"}]},{"머리":"LaLonde & Zinszer 물류서비스 요소","줄":[{"t":"거래 전 요소: 명시화된 회사 정책(고객서비스 명문화), 시스템의 유연성","src":"기출 2022-35, 2023-4"},{"t":"거래 시 요소: 재고품절 수준(재고수준), 주문 편리성, 시스템의 정확성","src":"기출 2022-35, 2023-4"},{"t":"거래 후 요소: 보증수리, 설치 및 조립, 제품추적, 고객클레임·불만 처리","src":"기출 2022-35, 2023-4, 2026-6"},{"t":"거래 전 요소: 고객서비스 관련 기업 정책과 연관. 기업정책 명문화, 고객서비스 명문화, 고객의 접근 용이성, 주기적 제품 점검, 시스템의 유연성, 경영관리·기술적 서비스, 목표 배송일, 재고가용성","src":"이론"},{"t":"거래 시 요소: 고객에게 인도하는 데 직접 관련된 요소. 재고 품절수준, 주문주기의 일관성(배송의 신뢰성), 주문의 편리성, 주문주기 및 주문처리능력, 정보시스템의 정확성, 제품 선적(shipping), 제품 교환·대체, 백오더(Back-order) 이용 가능성","src":"이론"},{"t":"거래 후 요소: 설치·보증·수리·서비스 부품, 고객 컴플레인 처리, 제품추적 및 보증, 수리기간 동안의 제품대체. 제품추적은 거래 후 요소","src":"이론"}]},{"머리":"주문주기와 시간 요소","줄":[{"t":"주문주기시간(Order Cycle Time): 고객이 제품을 주문해서 받을 때까지 걸리는 총 시간","src":"기출 2022-32"},{"t":"주문전달시간, 주문처리시간, 주문조립시간, 인도시간 등으로 구성","src":"기출 2022-32, 2025-7"},{"t":"주문조립시간(Order Assembly Time): 주문정보를 창고나 발송부서에 전달한 후부터 주문받은 제품의 발송을 준비하는 데 걸리는 시간","src":"기출 2025-7"},{"t":"주문주기시간은 재고정책의 개선활동으로 단축할 수 있음","src":"이론"},{"t":"구성요소 순서: 주문전달 → 주문처리 → 주문조립 → 재고가용성 → 인도시간","src":"이론"},{"t":"주문전달시간: 주문접수 후 관련부서와 주문을 주고받는 데 쓰는 방법(이메일·우편)별 소요시간","src":"이론"},{"t":"주문처리시간: 적재서류 준비, 재고기록 갱신, 신용장 처리, 주문확인, 주문정보를 생산·판매·회계부서 등에 전달하는 데 걸리는 시간","src":"이론"},{"t":"재고가용성 확보 시간: 창고에 재고가 없을 때 생산자의 재고로부터 보충하는 데 걸리는 시간","src":"이론"},{"t":"인도시간: 주문품을 재고지점에서 고객에게 전달하는 시간. 창고에 재고가 있으면 공장을 거치지 않고 바로 고객에게 전달하는 시간","src":"이론"},{"t":"주문처리 활동: 주문확인, 적재서류 준비, 재고기록 갱신, 주문정보 전달. 처리시간에는 재고 인출·적재지점 이동·포장·혼재작업 시간도 포함","src":"이론"}]},{"머리":"계산: 정시배송율","줄":[{"t":"공식: 정시배송율 = 지연 없이 완료된 건수 ÷ 전체 배송 완료 건수 × 100","src":"기출 2021-7"},{"t":"풀이 순서: 건별로 배송완료 일시가 배송예정 일시 이내인지 확인 → 이내인 건수 합계 → 전체 건수로 나눔","src":"기출 2021-7"},{"t":"예: 5건 중 3건이 예정시각 이내 완료 → 60%","src":"기출 2021-7"}]},{"머리":"서비스의 특징과 품질","줄":[{"t":"서비스의 특징(무비소이): 무형성, 비분리성, 소멸성, 이질성","src":"이론"},{"t":"무형성: 제공받기 전에는 형태·가치·품질을 파악·평가하기 어려움","src":"이론"},{"t":"비분리성: 생산과 소비가 동시에 일어나 분리될 수 없음(생산·소비의 동시성)","src":"이론"},{"t":"소멸성: 즉시 사용되지 않으면 소멸하므로 재고로 저장할 수 없음(비저장성)","src":"이론"},{"t":"이질성: 제공 주체마다 상이·비표준적·가변적이어서 표준화가 어려움","src":"이론"},{"t":"서비스 매트릭스(슈메너): 노동집약도와 고객과의 상호작용·개별화 정도로 서비스 프로세스를 분류","src":"이론"},{"t":"서비스 매트릭스: 노동집약도 높음·상호작용 낮음 = 대중 서비스(학교·학원, 도소매상, 은행업)","src":"이론"},{"t":"서비스 매트릭스: 노동집약도 높음·상호작용 높음 = 전문 서비스(변호사·의사·약사, 관세사·회계사, 건축사·설계사)","src":"이론"},{"t":"서비스 매트릭스: 노동집약도 낮음·상호작용 낮음 = 서비스 팩토리(호텔·리조트, 항공사·선사, 화물운송업)","src":"이론"},{"t":"서비스 매트릭스: 노동집약도 낮음·상호작용 높음 = 서비스 숍(병원, 자동차 정비소, 고객 서비스센터)","src":"이론"}]}],"함정":[{"x":"제품 가용성(Availability) 정보제공은 물류서비스 신뢰성에 영향을 주지 않는다.","o":"제품 가용성 정보제공은 신뢰성에 영향을 준다.","src":"기출 2024-6"},{"x":"제품 추적은 거래 시(transaction) 서비스 요소이다.","o":"제품추적은 거래 후 요소(설치·보증·수리·서비스 부품, 컴플레인 처리, 제품추적 및 보증, 수리기간 중 제품대체). 주문 편리성·주문주기·백오더 이용 가능성·재고품절 수준은 거래 시 요소","src":"기출 2020-7"}]},"#5":{"묶음":[{"머리":"유형 분류 관점 (2022 기출)","줄":[{"t":"형태 관점: 사내조직, 독립자회사","src":"기출 2022-5"},{"t":"관리 관점: 분산형, 집중형, 집중분산형","src":"기출 2022-5"},{"t":"기능 관점: 라인업무형, 스태프업무형, 라인스태프겸무형, 매트릭스형","src":"기출 2022-5"},{"t":"영역 관점: 개별형, 조달형, 마케팅형, 종합형, 로지스틱스형","src":"기출 2022-5"},{"t":"비공식·준공식·공식 조직 분류는 예산 관점이 아님(공식성 관점으로 정리됨, 추정)","src":"보충(추정)"},{"t":"물류조직은 형태에 따라 직능형 → 라인·스태프형 → 사업부형 → 그리드형 순으로 발전","src":"이론"},{"t":"물류조직은 고객서비스 개선과 대외 경쟁력 강화에 큰 역할. 물류비 절감·매출 증대 등 높은 물류경쟁력을 갖추게 함","src":"이론"}]},{"머리":"조직 형태별 특징","줄":[{"t":"분산형: 물류관리 업무를 각 공장·영업부서·운송부서·총무부서 등에서 개별적으로 운영","src":"기출 2024-11"},{"t":"자회사형: 물류관리 업무를 전문화해 독립된 회사로 분사","src":"기출 2024-11"},{"t":"그리드형: 다국적 기업에 많음. 모회사 물류본부의 스태프 부문이 여러 자회사의 해당 부문을 횡적으로 관리·지원","src":"기출 2021-12"},{"t":"사업부형: 기업 규모 확대에 따라 등장. 각 사업단위의 성과 극대화, 독립채산제, 물류 전문 인재 양성 용이","src":"기출 2025-10, 2026-11"},{"t":"사업부형 단점: 물류기능 중복으로 조직운영 비용이 큼, 전문인력 교류 경직, 전사적 통합성 결여로 경영효율 저하","src":"기출 2026-11, 2025-10"},{"t":"물류조직 유형 보기: 직능형, 사업부형, 라인스태프형, 그리드형, 매트릭스형, 기능특성형","src":"기출 2021-12, 2025-10, 2026-11"},{"t":"직능형(기능별) 조직: 부문화의 가장 기본 형태. 인사·생산·회계·마케팅 등 공통 경영기능 중심으로 부문화. 라인과 스태프가 아직 분화되지 않음","src":"이론"},{"t":"직능형 장점: 유사 기능별 구성으로 기능부문 내 협업·규모의 경제 가능, 기능별 전문성·효율성 제고","src":"이론"},{"t":"직능형 단점: 기능부서 간 협업·의견조정이 어려움, 부서별 기여도·책임소재 분리가 어려워 전체 최적화가 곤란, 환경변화 반응이 늦고 능동적 혁신이 어려움. 최고경영자에게 권한과 업무가 과하게 집중되는 경향","src":"이론"},{"t":"라인조직: 상급자의 명령체계가 수직적으로 하급자에게 전달되는 군대식 조직","src":"이론"},{"t":"라인-스태프조직: 직능형 단점을 보완하려고 라인과 스태프 기능을 세분화. 라인은 스태프로부터 조언을 받음. 스태프는 물류전략 수립·물류예산관리·채산성 분석 수행","src":"이론"},{"t":"라인부문 활동: 주문처리, 창고보관, 커뮤니케이션, 재고관리, 선적·운송·하역·포장, 수·배송 및 차량관리","src":"이론"},{"t":"스태프부문 활동: 재고분석 및 관리, 물류예산관리, 물류전략 수립, 창고배치, 물류채산성 분석, 물류시스템 절차 개선","src":"이론"},{"t":"사업부제 조직: 제품별·지역별로 사업부를 분화해 독립 경영. 각 사업부 내에 라인과 스태프 조직이 기능별로 작용. 책임·권한을 사업부에 부여해 책임소재 명확","src":"이론"},{"t":"사업부제 장점: 사업부에 전략적 결정을 분권화해 최고경영층이 전사 전략에 몰두, 대규모 조직의 환경변화 유연 대응, 하나의 이익 단위로 독립성·분권화된 의사결정·명확한 책임소재로 고객만족 제고","src":"이론"},{"t":"사업부제 단점: 부문 이기주의, 사업부문 간 통합조정·표준화·통일적 활동이 어려움, 각 사업부 내 규모의 경제 달성이 어려움","src":"이론"},{"t":"그리드형(격자형): 다국적기업에 많음. 모회사 스태프부문이 여러 자회사의 해당 물류부문을 관리·지원. 자회사 물류부서는 자사 경영자와 모회사 물류본부 양쪽에서 지시를 받음(이중지배구조, Two boss system). 해외 자회사는 직무 스트레스가 심한 형태","src":"이론"},{"t":"프로젝트 조직: 특정 프로젝트별로 형성. 여러 부서에서 파견된 사람으로 구성되어 과업 해결 시까지만 존재하는 임시적·탄력적 조직. 기동성과 환경적응성이 높음","src":"이론"},{"t":"매트릭스 조직: 기능식 조직(수직)과 프로젝트 조직 또는 사업부제 조직(수평)의 장점을 결합해 전문성과 제품혁신 목표를 동시에 달성. 프로젝트 조직과 달리 영구적 조직","src":"이론"},{"t":"매트릭스 조직 특징: 인적자원을 상황에 맞게 공유·유연 활용, 항공우주·기술개발·건설 등 대규모 사업에 사용, 이중 명령체계(two boss system) 문제, 명령계통 혼선과 역할 갈등 가능, 동시에 여러 프로젝트 수행 가능","src":"이론"},{"t":"네트워크 조직: 핵심역량 강화에 주력하고 비핵심역량은 전략적 제휴·아웃소싱으로 유지. 조직 경계와 구조가 없어 가상조직·모듈조직이라고도 함","src":"이론"},{"t":"네트워크 조직 등장배경: 경쟁 심화에 따른 전략적 제휴 필요(비용절감), 정보통신·IT 발전, 수평적·신축적 운영방식 중요성 인식, 효율적 생산·운영방식 등장","src":"이론"},{"t":"사업부형 조직 유형: 상품 중심 사업부제, 지역 중심 사업부제, 두 형태를 절충한 형태","src":"기출 2020-11"},{"t":"사업부형 조직: 각 사업부는 독립된 분권조직이며 사업부 내에 라인조직과 스태프조직이 있음. 전체 조직은 수직적 형태","src":"기출 2020-11"}]}],"함정":[{"x":"예산관점에서 비공식적, 준공식적, 공식적 조직으로 분류할 수 있다.","o":"출제 오답(바른 수치 미확인). 비공식·준공식·공식 분류는 공식성 관점(추정).","src":"기출 2022-5, 보충(추정)"},{"x":"[사업부형 물류조직] 사업부 간 횡적 교류가 활발하여 전사적 물류활동이 가능하다.","o":"사업부 간 횡적(수평적) 통합조정이 곤란해 전사적 물류활동이 어렵고 부문 이기주의가 발생할 수 있음","src":"기출 2020-11"}]},"#6":{"묶음":[{"머리":"지침의 성격","줄":[{"t":"기업물류비 산정지침은 물류정책기본법 제26조 및 영 제18조에 따라 물류기업·화주기업의 물류비 계산 절차와 방법의 기준을 제공. 목적은 물류회계 표준화와 물류비 산정의 정확성·관리 합리성 제고","src":"기업물류비 산정지침 제1조"},{"t":"물류비: 물류활동을 수행하기 위하여 발생하거나 소비한 경제가치","src":"기업물류비 산정지침 제2조 제2호"},{"t":"적용대상: 물류비 실적측정용. 제조업, 유통업(도·소매업 등), 물류업(수송업 등)","src":"기업물류비 산정지침 제3조"},{"t":"구성: 원가회계방식으로 별도 원가자료로부터 물류비를 계산하는 일반기준 + 재무회계방식으로 회계장부·재무제표로부터 물류비를 추산하는 간이기준","src":"기업물류비 산정지침 제4조"},{"t":"일반기준은 관리회계(원가회계) 방식, 간이기준은 재무제표 중심의 재무회계 방식. 간이기준은 정확한 물류비 파악이 어려움","src":"기업물류비 산정지침 제4조, 기출 2022-17"},{"t":"기업은 매출규모, 매출액 대비 물류비 비중, 물류비 변동 등을 고려해 일반기준과 간이기준을 선택하여 적용할 수 있다","src":"기업물류비 산정지침 제5조 제1항"},{"t":"물류비 계산범위는 국내에서 발생하는 물류비로 제한","src":"기업물류비 산정지침 제5조 제2항"},{"t":"물류비 개념(지침): 재화가 공급자로부터 조달·생산되어 수요자에게 전달되거나 소비자로부터 회수되어 폐기될 때까지의 여러 활동을 수행하기 위해 발생하거나 소비한 경제가치","src":"이론"},{"t":"산정 중요성: 적정가격 책정 자료, 물류 기본계획 수립 원가정보, 경영관리자 원가자료, 물류예산 편성·통제 원가자료, 재무제표 작성 및 관리회계 목적 원가정보, 객관적 고객정보로 합리적 의사결정 지원","src":"이론"}]},{"머리":"일반기준: 과목 분류 체계","줄":[{"t":"일반기준 분류: 영역별·기능별·지급형태별·세목별(실태 파악) + 관리항목별·조업도별(관리 목적)","src":"기업물류비 산정지침 제7조"},{"t":"영역별 물류비: 조달물류비·사내물류비·판매물류비·리버스(역)물류비","src":"기업물류비 산정지침 제7조 제1항, 기출 2022-17, 2026-20"},{"t":"영역별: 조달물류비·사내물류비·판매물류비·리버스물류비(반품·회수·폐기)","src":"이론"},{"t":"기능별: 운송비·보관비·포장비·하역비(유통가공비 포함)·물류정보·관리비","src":"이론"},{"t":"지급형태별: 자가물류비, 위탁물류비(2PL·3PL). 세목별: 재료비·노무비·경비·이자비용","src":"이론"},{"t":"조업도별: 물류고정비·물류변동비. 관리항목별: 조직별·지역별·고객별·활동별 등 개별기업 특성에 맞게 정의(지침 제7조 5항)","src":"이론"},{"t":"비목별 계산절차: 물류비 계산 욕구의 명확화 → 물류비 자료의 식별과 입수 → 물류비 배부기준의 선정 → 물류비 배부와 집계 → 물류비 계산의 보고","src":"이론"},{"t":"비목별 계산은 비용항목별로 집계하며 물류비 인식기준에 따라 영역별·기능별·지급형태별·세목별·관리항목별로 산정","src":"이론"}]},{"머리":"일반기준: 영역별","줄":[{"t":"조달물류비: 조달처에서 운송되어 매입자 보관창고 입고·관리, 생산공정 투입 직전까지의 물류비","src":"기업물류비 산정지침 제7조 제1항 제1호"},{"t":"사내물류비: 매입물자 보관창고에서 완제품 등의 판매를 위한 장소까지의 물류활동 비용","src":"기업물류비 산정지침 제7조 제1항 제2호"},{"t":"재료의 생산이나 제품 제조공정 내 발생 비용은 생산원가·제조원가에 산입되므로 물류비에서 제외","src":"기업물류비 산정지침 제7조 제1항 제2호"},{"t":"판매물류비: 완제품·상품을 판매창고에서 보관하는 활동부터 고객에게 인도될 때까지의 물류비","src":"기업물류비 산정지침 제7조 제1항 제3호"},{"t":"리버스물류비: 회수물류비·폐기물류비·반품물류비로 세분","src":"기업물류비 산정지침 제7조 제1항 제4호"},{"t":"회수물류비: 공용기·포장자재 등이 회수되어 재사용 가능할 때까지의 물류비","src":"기업물류비 산정지침 제7조 제1항 제4호 가목"},{"t":"폐기물류비: 제품·상품, 포장용·수송용 용기나 자재 등을 회수하여 폐기할 때까지의 물류비","src":"기업물류비 산정지침 제7조 제1항 제4호 나목"},{"t":"반품물류비: 판매한 제품·상품 또는 위탁판매 제품·상품의 취소, 위탁의 취소 등 물류활동에 따른 물류비","src":"기업물류비 산정지침 제7조 제1항 제4호 다목"},{"t":"회수물류비에는 파렛트·컨테이너·포장용기 등 공용기·포장자재의 회수 비용이 포함","src":"기출 2020-17, 기업물류비 산정지침 제7조 제1항 제4호"}]},{"머리":"일반기준: 기능별","줄":[{"t":"운송비: 물자를 물류거점 간 및 고객에게 이동시키는 활동 비용. 수송비(물류거점까지 이동)·배송비(고객에게 배달)로 세분 가능","src":"기업물류비 산정지침 제7조 제2항 제1호"},{"t":"보관비: 물자를 창고 등 물류시설에 보관하는 활동 비용","src":"기업물류비 산정지침 제7조 제2항 제2호"},{"t":"하역비: 유통가공·운송·보관·포장 등에 수반하여 상차·하차, 피킹, 분류 등 물자를 상하·좌우로 이동시키는 비용","src":"기업물류비 산정지침 제7조 제2항 제3호"},{"t":"포장비: 물자 이동·보관을 쉽게 하기 위한 상자·골판지·파렛트 등 물류포장 비용. 최종소비자를 위한 판매포장은 제외","src":"기업물류비 산정지침 제7조 제2항 제4호"},{"t":"물류정보·관리비: 물류활동·기능 관련 정보처리와 관리 비용. 물류정보비와 물류관리비로 세분 가능","src":"기업물류비 산정지침 제7조 제2항 제5호"},{"t":"물류정보비: 구매·수송·생산·창고운영·재고관리·유통망 등 물류 프로세스를 전자적 수단으로 지원하는 활동 비용","src":"기업물류비 산정지침 제7조 제2항 제5호 가목"},{"t":"물류관리비: 물류활동·기능의 합리화와 공동화를 위한 계획·조정·통제 등 관리 활동 비용","src":"기업물류비 산정지침 제7조 제2항 제5호 나목"},{"t":"수송비: 기업의 필요에 따라 물자를 물류거점까지 이동시키는 물류비. 배송비: 물자를 고객에게 배달시키는 물류비","src":"이론"},{"t":"포장비는 영역별이 아닌 기능별 물류비에 해당","src":"이론"}]},{"머리":"일반기준: 지급형태별·세목별","줄":[{"t":"자가물류비: 자사 설비·인력으로 물류활동을 수행해 소비된 비용. 재료비·노무비·경비·이자로 구분","src":"기업물류비 산정지침 제7조 제3항 제1호"},{"t":"위탁물류비: 물류활동의 일부·전부를 타사에 위탁해 소비된 비용. 물류자회사 지급분과 물류전문업체 지급분으로 구분","src":"기업물류비 산정지침 제7조 제3항 제2호"},{"t":"세목별 분류: 재료비·노무비·경비·이자","src":"기업물류비 산정지침 제7조 제4항 제1호, 기출 2025-16"},{"t":"시설부담이자: 물류시설에 투자된 자금의 이자부담분만큼의 기회손실","src":"기업물류비 산정지침 제7조 제4항 제2호"},{"t":"재고부담이자: 재고자산 가치에 대한 이자부담분만큼의 기회손실. 보관비에만 포함. 재고는 자가·영업창고 보관 원자재·부품·제품 일체","src":"기업물류비 산정지침 제7조 제4항 제2호"},{"t":"세목별 분류: 재료비·노무비·경비·이자. 이자는 물류시설에 투자된 자금의 이자부담분만큼의 기회손실이며 중요한 비용항목","src":"이론"},{"t":"재료비: 포장·운송활동과 관련된 재료의 소비로 발생하는 비용. 재료비·연료비 등","src":"이론"},{"t":"노무비: 물류활동을 수행하기 위한 노동력 비용. 운송·보관·포장·하역 등과 조달·사내·판매물류 전 영역에서 발생","src":"이론"},{"t":"경비: 재료비 이외에 물류활동과 관련해 발생하는 여러 비용. 주로 물류관리 기능에서 발생. 관리인 인건비·감가상각비 등","src":"이론"},{"t":"감가상각비: 물류 관련 유형자산의 시간경과에 따른 가치감소분 또는 원가의 배분","src":"이론"},{"t":"시설부담이자: 시설물의 잔존가치에 이자율을 곱해 산정. 잔존가치 = 시설물 취득원가 − 감가상각누계액","src":"이론"},{"t":"재고부담이자: 재고의 평균잔액에 이자율을 곱해 계산. 보관비에만 포함. 재고는 자가·영업창고에 보관 중인 원자재·부품·제품 일체","src":"이론"},{"t":"자가물류비(제1자 물류비): 자사 설비·인력으로 물류활동을 수행해 소비된 비용. 재료비·노무비·경비·이자로 구분","src":"이론"},{"t":"위탁물류비(제2자·3자 물류비): 물류활동의 일부·전부를 타사에 위탁해 소비된 비용. 물류자회사 지급분(2자물류)과 물류전문업체 지급분(3자물류)","src":"이론"},{"t":"물류고정비: 조업도의 증감과 관계없이 발생·소비 비용이 일정. 물류변동비: 조업도 증감에 비례해 변화","src":"이론"}]},{"머리":"일반기준: 관리 목적 분류","줄":[{"t":"관리항목별: 조직별·지역별·고객별·활동별 등 관리항목을 정의해 구분","src":"기업물류비 산정지침 제7조 제5항"},{"t":"조업도별: 물류고정비(조업도 증감과 무관하게 일정)·물류변동비(조업도 증감에 비례)","src":"기업물류비 산정지침 제7조 제6항"}]},{"머리":"인식·계산 방법","줄":[{"t":"인식 기준: 원칙적으로 발생기준. 시설부담이자·재고부담이자는 기회원가 개념 적용","src":"기업물류비 산정지침 제8조"},{"t":"물류비 계산은 실태파악 목적(영역별·기능별·지급형태별)과 관리 목적(조업도별·관리항목별)으로 구분","src":"기업물류비 산정지침 제9조"},{"t":"물류활동과 관련된 것만 계산하고 비정상적인 물류비는 제외","src":"기업물류비 산정지침 제9조 제1항 제1호"},{"t":"부수적·간접적 물류비는 합리적 배부기준(금액·인원·면적·시간·물량 등)으로 배부","src":"기업물류비 산정지침 제9조 제1항 제4호, 제5호"},{"t":"관리항목별 계산: 직접귀속 가능한 직접비는 직접 부과, 불가능한 간접비는 적절한 배부기준으로 배부","src":"기업물류비 산정지침 제9조 제2항 제2호"},{"t":"시설부담이자·재고부담이자는 자산명세서·재고명세서와 권위 있는 기관의 이자율로 계산","src":"기업물류비 산정지침 제9조 제2항 제3호"},{"t":"일반기준 적용 기업은 매 회계연도 당기·전기 실적을 비교하는 별지 제1호 서식 계산서 작성","src":"기업물류비 산정지침 제10조"},{"t":"물류비는 현금의 유출입보다 기업회계기준·원가계산준칙의 발생기준을 적용하며, 물류활동이 발생된 기간에 배정","src":"기출 2020-16, 기업물류비 산정지침 제8조"},{"t":"물류비 정확 파악은 재무회계방식(간이기준)보다 관리회계방식(일반기준)이 적합. 물류비는 직접비와 간접비를 모두 포함","src":"기출 2020-16, 기업물류비 산정지침 제8조"}]},{"머리":"간이기준","줄":[{"t":"간이기준 목적: 물류비 실태를 추정할 목적. 재무회계방식으로 회계장부·재무제표로부터 기능별·지급형태별로 계산","src":"기업물류비 산정지침 제11조"},{"t":"간이기준 기능별: 운송비, 보관비, 하역비, 포장비, 물류정보·관리비","src":"기업물류비 산정지침 제12조 제1항"},{"t":"간이기준 지급형태별: 자가물류비(재료비·노무비·경비·이자), 위탁물류비","src":"기업물류비 산정지침 제12조 제2항"},{"t":"간이기준 계산: 제조원가명세서·손익계산서 계정과목별로 물류비 해당 금액을 추계","src":"기업물류비 산정지침 제13조 제1항"},{"t":"간이기준에서 시설부담이자·재고부담이자는 자산명세서·재고명세서 기초로 계산","src":"기업물류비 산정지침 제13조 제2항"},{"t":"간이기준 적용 기업은 별지 제2호 서식 계산서 작성","src":"기업물류비 산정지침 제14조"}]},{"머리":"계산: 간접물류비 배부 (품목별)","줄":[{"t":"풀이 순서: 비목별 간접물류비 총액 확인 → 비목별 배부기준(운송비=운송물량×운송거리, 보관비=보관공간×보관일수, 하역비=상차수량+하차수량)으로 품목별 값 산출 → 품목별 비율 → 비목 총액×비율 → 품목별로 합산","src":"기출 2023-20"},{"t":"예: 운송비 10,000 중 15×250:10×125=3,750:1,250 → 7,500:2,500. 보관비 2,000 중 500×3:300×15=1,500:4,500 → 500:1,500. 하역비 1,000 중 9,000:1,000 → 900:100. P1=8,900, P2=4,100","src":"기출 2023-20"}]},{"머리":"계산: 판매물류비 집계","줄":[{"t":"풀이 순서: 각 지출을 영역으로 분류 → 판매물류비 항목(완제품 출고검사, 완제품 포장, 상차·배송)만 합산. 생산공정 투입 제조비(제조원가)는 물류비에서 제외","src":"기출 2024-17, 기업물류비 산정지침 제7조 제1항 제2호"},{"t":"예: 출고검사 20 + 포장 50 + 상차·배송 30 = 100만원","src":"기출 2024-17"}]},{"머리":"계산: 평균 보관체적 비례 배부","줄":[{"t":"풀이 순서: 제품별 연평균 보관량 = (기초재고+기말재고)÷2 → × 단위당 체적 = 연평균 보관체적 → 체적 비율 → 임대료 × 비율","src":"기출 2026-19"},{"t":"예: A (230+270)÷2×1.0=250, B (120+80)÷2×1.5=150 → 5,000만원 중 A 3,125, B 1,875","src":"기출 2026-19"}]},{"머리":"일반기준과 간이기준 비교","줄":[{"t":"일반기준(관리회계방식): 물류활동의 관리·의사결정에 필요한 회계정보를 얻기 위해 영역별·기능별·관리항목별로 발생비용을 집계. 인력·자금·시설 등의 계획·통제에 유용한 정보 제공. 기능별·관리항목별 계획수립·성과평가에 활용","src":"이론"},{"t":"일반기준의 목적: 물류비 실태를 상세하게 파악하기 위해 실적물류비를 발생요인별로 계산","src":"이론"},{"t":"일반기준의 물류비 인식은 발생기준. 시설부담이자·재고부담이자는 기회원가 개념. 비목별로 계산한 후 관리항목별로 구분","src":"이론"},{"t":"일반기준 장점: 필요한 시기·장소에서 영역별·기능별·관리항목별 계산 가능, 물류활동 개선방안 도출 용이","src":"이론"},{"t":"일반기준 단점: 상세한 분류·계산이 복잡, 사무절차 작업량이 많아 정보시스템 구축이 전제","src":"이론"},{"t":"간이기준(재무회계방식): 회계장부와 재무제표(주로 포괄손익계산서·제조원가명세서)로부터 간단히 추산. 목적은 물류비 실태 추정. 기능별·지급형태별로 계산(기업 실정에 따라 영역별·조업도별·관리항목별도 가능, 지침 제11조)","src":"이론"},{"t":"간이기준은 물류비 관리수준이 낮은 영세·중소업체에 적합. 제조원가명세서·손익계산서 계정과목별로 물류비 해당 금액을 추계","src":"이론"},{"t":"간이기준 장점: 대략적인 물류비 총액계산에 별도 분류·계산절차가 필요 없음. 전담조직이 없거나 전문지식이 부족해도 계산 가능","src":"이론"},{"t":"간이기준 단점: 상세한 물류비 파악이 곤란하고 물류비 절감효과 측정에 한계. 구체적 성과평가·계획수립이 어려움","src":"이론"}]},{"머리":"물류비 관리","줄":[{"t":"물류비관리 목적: 물류활동을 화폐적 가치로 파악해 중요성 인식, 물류 관련 비용을 물류관리의 기본 척도로 활용, 합리적 의사결정 정보 제공, 문제점 도출·개선으로 물류비 절감과 생산성 향상, 물류예산 편성·통제, 계획·관리·실적 평가에 활용","src":"이론"},{"t":"물류비를 10% 절감하면 그 이상의 매출액 증대 효과. 이익증가분이 투자로 이어지면 이자비용·위험비용 감소 등 부가가치가 더해져 제3의 이익원이 됨","src":"이론"},{"t":"물류예산 편성절차: 물류환경조건 파악 → 장기물류계획 설정 → 물류예산편성 방침 작성·제출 → 물류비 예산안 작성·제출 → 물류비 예산안 심의·조정 → 물류비 예산 확정","src":"이론"}]},{"머리":"계산: 조달물류비 집계","줄":[{"t":"풀이 순서: 각 지출을 영역으로 분류 → 조달물류비(부품 운송·하역, 창고 입고 검수)만 합산. 생산공정 투입 제조·가공은 제조원가, 출고검사·포장·상차·배송은 판매물류비, 홍보·광고는 물류비 아님","src":"기출 2020-19"},{"t":"예: 운송·하역 40 + 입고 검수 10 = 조달물류비 50만원 (제조·가공 60, 출고검사·포장 20, 상차·배송 30, 홍보·광고 50은 제외)","src":"기출 2020-19"}]}],"함정":[{"x":"재료비는 기능별 물류비 비목이다.","o":"재료비는 세목별(자가물류비의 세목) 비목. 기능별은 운송비·보관비·하역비·포장비·물류정보관리비.","src":"기출 2021-15, 기업물류비 산정지침 제7조"},{"x":"위탁비는 일반기준 기능별 물류비에 해당한다.","o":"위탁물류비는 기능별이 아니라 지급형태별 분류.","src":"기출 2023-15, 기업물류비 산정지침 제7조 제3항"},{"x":"물류기업의 물류비 산정 정확성을 높이기 위해 개발되었으므로 화주기업은 적용 대상이 될 수 없다.","o":"지침은 제조업·유통업·물류업을 대상으로 하므로 화주기업도 적용 대상이다.","src":"기출 2022-17, 기업물류비 산정지침 제3조"},{"x":"사내물류비는 제조공정 내에서 발생한 비용과 공정 간 물류비용을 포함한다.","o":"제조공정 내 발생 비용은 생산원가·제조원가에 산입되므로 물류비에서 제외한다.","src":"기출 2026-20, 기업물류비 산정지침 제7조 제1항 제2호"},{"x":"[물류비] 영역별로 조달, 생산, 포장, 판매, 회수, 폐기 활동으로 구분된 비용이 포함된다.","o":"영역별 물류비는 조달·사내·판매·리버스(회수·폐기·반품)물류비. 포장은 기능별 물류비","src":"기출 2020-16, 기업물류비 산정지침 제7조 제1항"},{"x":"[역물류비] 반품물류비는 판매된 상품에 대한 환불과 위약금을 포함한 모든 직접 및 간접 비용이다.","o":"반품물류비는 판매한 제품·상품 또는 위탁판매한 제품·상품의 취소, 위탁의 취소 등의 물류활동에 따른 물류비","src":"기출 2020-17, 기업물류비 산정지침 제7조 제1항 제4호"},{"x":"[역물류비] 반품물류비에는 운송, 검수, 분류, 보관, 폐기 비용이 포함된다.","o":"지침상 폐기하는 비용은 폐기물류비(제품·상품·포장용 수송용 용기나 자재 등을 회수해 폐기할 때까지). 반품물류비는 취소·위탁 취소 등의 물류활동에 따른 물류비","src":"기출 2020-17, 기업물류비 산정지침 제7조 제1항 제4호"},{"x":"[역물류비] 회수물류비는 판매된 제품과 물류용기의 회수 및 재사용에 들어가는 비용이다.","o":"회수물류비는 공용기와 포장자재 등이 회수되어 재사용 가능할 때까지의 물류비. 판매한 제품의 취소는 반품물류비","src":"기출 2020-17, 기업물류비 산정지침 제7조 제1항 제4호"},{"x":"[역물류비] 제품이 정상적으로 사용된 후 소멸 처리하는 것은 폐기비용으로 간주하지 않는다.","o":"지침은 폐기물류비를 제품·상품, 포장용·수송용 용기나 자재 등을 회수하여 폐기할 때까지의 물류비로 정의(사용 후 소멸 처리를 제외한다는 규정 없음)","src":"기출 2020-17, 기업물류비 산정지침 제7조 제1항 제4호"}]},"#7":{"묶음":[{"머리":"활동기준원가계산 (ABC)","줄":[{"t":"정의: 기업이 수행하는 활동을 기준으로 자원·활동·원가대상의 원가와 성과를 측정하는 원가계산방법","src":"기출 2022-18"},{"t":"업무를 활동단위로 세분하여 원가를 산출","src":"기출 2021-16"},{"t":"전통적 원가계산보다 제품·서비스의 실제 비용을 현실적으로 계산","src":"기출 2022-18"},{"t":"활동별로 원가를 분석하므로 낭비요인이 있는 업무 영역을 파악","src":"기출 2021-16, 2022-18"},{"t":"산정원가로 원가유발요인분석과 성과측정 가능","src":"기출 2021-16"},{"t":"물류서비스별·활동별·고객별·유통경로별·프로세스별 수익성 분석 가능","src":"기출 2021-16"},{"t":"소품종 대량생산보다 다품종 소량생산에서 유용성이 더 높음","src":"기출 2022-18"},{"t":"재료비·노무비·경비로 구분하는 계산은 전통적(비목별) 원가계산 방식","src":"기출 2021-16"},{"t":"전통적 원가계산의 문제: 임의적인 간접원가 배부기준(ABC가 극복하려는 대상)","src":"기출 2022-18"},{"t":"ABC: 기업 내 활동과 원가대상 간의 인과관계에 근거해 자원·활동·원가대상의 원가와 성과를 측정하는 원가계산기법","src":"이론"},{"t":"ABC는 재료비·노무비·제조간접비 귀속방식에서 더 나아가 원가가 발생한 원인을 찾아 이를 기반으로 원가를 배분","src":"이론"},{"t":"ABC의 기본 산출물은 제품·서비스별 원가와 활동원가. 활동기준 경영관리의 기초정보","src":"이론"},{"t":"ABC는 전통적 원가계산이 간접비를 제품원가에 정확히 반영하지 못해 생기는 원가왜곡을 보완","src":"이론"},{"t":"ABC 구성요소: 자원(Resource)과 자원동인(Resource driver), 활동(Activity)과 활동동인(Activity driver)","src":"이론"}]},{"머리":"균형성과표 (BSC, Kaplan & Norton)","줄":[{"t":"4가지 관점: 재무적 관점, 고객 관점, 내부 경영프로세스(내부 비즈니스 프로세스) 관점, 학습과 성장 관점","src":"기출 2021-18, 2022-19"},{"t":"전략적 관점은 4관점에 속하지 않는다","src":"기출 2021-18"},{"t":"재무성과뿐 아니라 전략실행에 필요한 비재무적 정보 제공. 전략과 관련된 측정지표의 집합","src":"기출 2022-19"},{"t":"무형자산을 차별화 전략이나 주주가치로 변환시키는 기법. 경영자의 단기적·재무적 근시안을 균형있게 함","src":"기출 2022-19"},{"t":"전 조직원이 전략을 공유하고 전략방향에 따라 행동하도록 유도하는 성과 측정 방법","src":"기출 2021-18"},{"t":"BSC는 조직의 목표와 전략을 효율적으로 실행·관리하기 위한 경영관리 기법으로 캐플란과 노튼이 제시","src":"이론"},{"t":"재무적 측면은 계량화 지표이고 고객 측면은 외부적, 내부 프로세스 측면은 내부적이며 비계량적, 학습 및 성장 측면은 미래지향적 지표. 이들의 균형적 결합으로 전략적 통제","src":"이론"},{"t":"재무적 측면: 영업이익·당기순이익 등이 개선되었는지 측정","src":"이론"},{"t":"고객 측면: 고객만족도 지표·CRM 등으로 고객 관련 사항의 개선 여부 측정","src":"이론"},{"t":"내부 프로세스 측면: 가치사슬분석으로 내부 가치창출 프로세스의 개선 여부 점검","src":"이론"},{"t":"학습과 성장 측면: 기업의 장기적 발전을 위해 인적자원개발에 노력했는지 점검","src":"이론"},{"t":"전통적 성과평가는 재무적 관점·내부 측정·정량 지표·단기 성과 중심. BSC는 재무+비재무, 내부+고객(외부), 정량+정성, 장기 성과까지 측정","src":"이론"},{"t":"BSC는 비재무적 성과까지 고려해 성과창출 동인(drivers)을 찾아 관리. 재무성과에 치우친 EVA(경제적부가가치)·ROI(투자수익률)의 한계를 극복","src":"이론"}]},{"머리":"손익분기점(BEP)","줄":[{"t":"공식: 손익분기점 판매량 = 고정비 ÷ (단위당 판매가격 − 단위당 변동비)","src":"기출 2021-17, 2022-16, 2024-20, 2025-14"},{"t":"손익분기점 매출액 = 고정비 ÷ 공헌이익률 (공헌이익률 = 1 − 변동비율)","src":"기출 2023-18"},{"t":"목표이익 달성 판매량 = (고정비 + 목표이익) ÷ 단위당 공헌이익","src":"기출 2021-17"},{"t":"풀이 순서: 단위당 변동비 계산(가격×변동비율) → 단위당 공헌이익 → 고정비를 나눔 → (목표이익 있으면 분자에 더함)","src":"기출 2021-17"},{"t":"예: 고정비 1억, 가격 10만, 변동비 60% → 공헌이익 4만 → BEP 2,500개, 목표이익 1억 포함 5,000개","src":"기출 2021-17"},{"t":"예: 고정비 10억, 가격 10만, 변동비 50% → 공헌이익 5만 → 20,000개, 매출 20억","src":"기출 2022-16"},{"t":"예: 가격 10만, 변동비 7.5만, 고정비 1억 → 공헌이익률 25% → BEP 매출 4억(40,000만원)","src":"기출 2023-18"},{"t":"예: 고정비 2천만원, 가격 1만, 변동비 80% → 공헌이익 2천 → 10,000개","src":"기출 2024-20"},{"t":"예: 고정비 2억, 가격 10만, 변동비 75% → 공헌이익 2.5만 → 8,000개","src":"기출 2025-14"}]},{"머리":"물류비 절감 효과와 이익률","줄":[{"t":"물류비 절감액은 그대로 이익 증가분. 동일 이익을 매출로 얻으려면 필요 매출 = 절감액 ÷ 이익률(경상이익률)","src":"기출 2024-5"},{"t":"예: 물류비 200억 5% 절감 = 10억, 경상이익률 60÷3000 = 2% → 필요 매출 500억","src":"기출 2024-5"},{"t":"예: 매출 400억, 물류비 20%=80억, 영업이익 20억 → 물류비 15%=60억이면 이익 40억 → 이익률 10%","src":"기출 2025-17"},{"t":"계산 - 영업이익률 목표 상향: 추가로 절감해야 할 물류비 = 매출액 × (목표 영업이익률 − 현재 영업이익률). 매출액이 같으면 절감한 물류비만큼 영업이익이 증가","src":"기출 2020-18"},{"t":"풀이 순서: 현재 물류비 확인 → 목표 영업이익률 − 현재 영업이익률 구함 → 매출액 곱함. 예: 매출 500억, 15%→20%이면 500×5% = 25억원 절감(현재 물류비 50억은 10%)","src":"기출 2020-18"}]},{"머리":"ROI·재무 지표","줄":[{"t":"ROI(총자본이익률) = 매출액순이익률 × 총자본회전율","src":"기출 2024-18"},{"t":"현금전환주기(Cash-to-Cash) = 재고기간 + 매출채권 회수기간 − 매입채무 지급기간","src":"기출 2024-19"},{"t":"예: 재고 3개월 + 매출채권 2개월 − 매입채무 3개월 = 2개월","src":"기출 2024-19"},{"t":"Cash-to-Cash Cycle Time: 원자재 구매비용을 지불한 날부터 제품 판매대금을 수금한 날까지 소요 시간","src":"기출 2023-24"}]},{"머리":"공급사슬 성과지표","줄":[{"t":"주문주기시간, 현금화 사이클타임(Cash-to-Cash), 공급사슬 배송성과(Delivery Performance to Request), 주문충족 리드타임, 공급사슬 생산유연성(Upside Production Flexibility)","src":"기출 2023-24"}]},{"머리":"감가상각","줄":[{"t":"정액법 연 감가상각액 = (취득원가 − 잔존가치) ÷ 내용연수","src":"기출 2026-16"},{"t":"예: (1억 − 2,000만) ÷ 10년 = 800만원","src":"기출 2026-16"}]},{"머리":"조업도와 고정·변동 물류비","줄":[{"t":"총물류비 = 고정물류비 + 변동물류비율 × 조업도","src":"기출 2026-18"},{"t":"풀이 순서: 전년 총물류비 계산 → 목표 조업도(전년×1.25) → (전년 총물류비 − 신규 고정비) ÷ 목표 조업도 = 필요한 변동비율","src":"기출 2026-18"},{"t":"예: 50 + 0.07×1,000 = 120억. 조업도 1,250. (120 − 60) ÷ 1,250 = 0.048","src":"기출 2026-18"}]},{"머리":"물류원가계산과 채산성분석","줄":[{"t":"물류원가계산: 예산기간 동안의 물류업무 활동실적을 평가하고 동일한 방식으로 예산기간별로 반복 수행","src":"기출 2026-21"},{"t":"물류채산성분석: 개선안의 채택 여부 등 의사결정에 활용. 분석 목적과 상황에 따라 적용 기법이 달라짐","src":"기출 2026-21"},{"t":"물류원가계산: 목적은 물류활동의 업적평가, 대상은 물류업무 전반, 산정방식은 항상 일정, 반복적, 실제원가만 대상","src":"이론"},{"t":"물류채산분석: 목적은 물류활동에 관한 의사결정, 대상은 특정 개선안·대체안, 산정방식은 상황에 따라 상이, 임시적, 특수원가도 대상","src":"이론"}]},{"머리":"재고자산·재고위험비용","줄":[{"t":"선입선출법(FIFO): 먼저 취득된 것부터 순차로 판매·출고되는 것으로 보고 기말재고액을 평가","src":"이론"},{"t":"후입선출법(LIFO): 기말재고를 평가하면 과소평가되어 당기순이익이 과소계상되는 문제","src":"이론"},{"t":"재고위험비용: 불용(Obsolescence, 모델·유형 변화·신기술로 쓸모없어짐), 손상(Damage, 보관·이동 중 손상), 절도(Pilferage, 분실·도난), 퇴화(Deterioration, 썩거나 수명 다함)","src":"이론"},{"t":"EOQ: 재고모형 중 확정적 모형의 고정주문량모형. 재고유지비용과 주문비용을 더한 연간 재고비용을 최소화하는 1회 주문량을 결정","src":"이론"}]}],"함정":[{"x":"재료비, 노무비 및 경비로 구분하여 계산한다. (ABC의 설명으로)","o":"재료비·노무비·경비 구분은 전통적 원가계산. ABC는 활동 단위로 세분.","src":"기출 2021-16"},{"x":"임의적인 직접원가 배부기준에 의해 발생하는 전통적 원가계산방법의 문제점을 극복하기 위해 활용된다.","o":"임의적인 간접원가 배부기준의 문제를 극복하기 위해 활용(추정).","src":"기출 2022-18, 보충(추정)"},{"x":"기업의 성과를 비재무적 관점, 고객 관점, 내부 비즈니스 프로세스 관점, 학습 및 성장 관점에서 측정한다.","o":"재무적 관점, 고객 관점, 내부 프로세스 관점, 학습 및 성장 관점.","src":"기출 2022-19"},{"x":"ROI: 매출액순이익률과 손익분기점의 곱으로 표현할 수 있다.","o":"매출액순이익률과 총자본회전율의 곱.","src":"기출 2024-18"},{"x":"ROI: 재고회전율과 총자본회전율의 곱으로 표현할 수 있다.","o":"매출액순이익률과 총자본회전율의 곱.","src":"기출 2024-18"},{"x":"ROI: 재고회전율과 손익분기점의 곱으로 표현할 수 있다.","o":"매출액순이익률과 총자본회전율의 곱.","src":"기출 2024-18"},{"x":"ROI: 손익분기점과 총자본회전율의 곱으로 표현할 수 있다.","o":"매출액순이익률과 총자본회전율의 곱.","src":"기출 2024-18"},{"x":"물류원가계산과 물류채산성분석은 시간에 따른 화폐 가치의 할인을 반영한다.","o":"출제 오답(바른 수치 미확인). 원가계산은 할인을 반영하지 않고, 채산성분석은 기법에 따라 달라짐(추정).","src":"기출 2026-21, 보충(추정)"}]},"#8":{"묶음":[{"머리":"물류정보의 특징","줄":[{"t":"관리대상 정보의 종류가 많고 내용이 다양","src":"기출 2021-23"},{"t":"성수기와 비수기의 정보량 차이가 큼","src":"기출 2021-23, 2023-36, 2026-25"},{"t":"정보의 발생원·처리장소·전달대상이 분산되어 있음","src":"기출 2021-23"},{"t":"상품과 정보의 흐름에 동시성이 요구됨","src":"기출 2021-23"},{"t":"구매·생산·영업활동과의 관련성이 큼","src":"기출 2021-23"},{"t":"정보: 관찰·측정으로 수집된 자료를 실제 문제해결에 도움이 되도록 분석·정리한 것","src":"이론"},{"t":"물류정보: 원자재 조달부터 판매·소비까지 물류 전 분야(주문처리·재고관리·창고관리·수배송관리·판매관리 등)에서 발생하는 정보","src":"이론"},{"t":"정보의 발생원·처리장소·전달대상이 넓게 분산돼 물류정보통신망도 LAN(근거리), MAN(광대역 지역), WAN(원거리) 등으로 다양하게 구축","src":"이론"},{"t":"물류정보는 구매·생산·영업·운송활동과의 관련성이 큼","src":"이론"}]},{"머리":"물류정보시스템(LIS)","줄":[{"t":"영어 약어 LIS. 물류정보의 수집·저장·가공·유통을 가능하게 하는 하드웨어·소프트웨어·업무프로세스·사용자 등의 집합체","src":"기출 2024-28, 2026-25"},{"t":"목적: 물류서비스 향상과 물류비 절감","src":"기출 2024-28, 2026-25, 2021-26"},{"t":"개별 물류활동의 통합을 통한 전체 최적화를 위해 구축","src":"기출 2024-28, 2026-25"},{"t":"정보량이 많을수록 수작업 대비 효율성·정확성 증대","src":"기출 2024-28"},{"t":"물류정보 시스템화는 상류정보(상거래 정보) 시스템화가 선행되어야 가능","src":"기출 2021-26"},{"t":"수주처리시스템: 최소의 주문입력 비용으로 고객서비스를 달성하는 것이 목적","src":"기출 2021-26"},{"t":"생산에서 소비까지 물류기능을 유기적으로 결합해 관리 효율성을 향상. 운송·보관·하역·포장 등 정보 포함","src":"기출 2023-36"},{"t":"LIS: 기업 내 또는 거래처를 연결하는 시스템으로 물류시스템에 연동되는 물류기기와 상호작용하는 지능형 시스템. 원재료 구입부터 완제품 유통까지 물류활동 전체 최적화를 위해 자료를 처리·가공하는 컴퓨터 기반 정보시스템","src":"이론"},{"t":"LIS 목표: 물류합리화로 적정 고객서비스를 최소 비용으로 달성하도록 지원","src":"이론"},{"t":"LIS 목표: 조달·생산·유통을 포괄적으로 연결해 물자 흐름 전체를 관리, 기업 간 정보 공유로 유통재고 최소화, 환경변화에 신속 대응하는 경쟁력 향상","src":"이론"},{"t":"LIS 목표: POS 실시간 정보로 공급계획을 세우고 풀(Pull)방식으로 유통망 지원","src":"이론"},{"t":"LIS 장점: 물동량이 늘어도 신속한 물류처리, 신속한 수주처리·즉각적 고객대응으로 판매기능 강화, 판매·재고정보 집약으로 생산·판매 조정, 재고 과부족에 따른 물류비용 절감, 단거리·장거리 운송 모두 효율적 관리","src":"이론"},{"t":"LIS 구축요건: 정보의 실시간 입력과 처리결과의 실시간 제공","src":"이론"},{"t":"LIS 구축요건: 통합물류관리를 위해 물류 이외 시스템과 연계 처리하는 프로세스 보유","src":"이론"},{"t":"LIS 구축요건: 바코드·RFID 등을 활용하는 물류기기와 연동","src":"이론"},{"t":"LIS 구축요건: 패키지 솔루션 도입보다 자사 실정을 고려한 자체 개발이 바람직","src":"이론"},{"t":"LIS 구축순서: 시스템 목표설정 → 적용범위 설정 → 구축조직 구성 → 업무현상 분석 → 시스템 구축 및 평가","src":"이론"},{"t":"LIS 구성: 주문관리·재고관리·창고관리·수배송관리·물류정보 통제시스템 5가지","src":"이론"},{"t":"주문관리 모듈(OMS): EOS·CAO 등으로 고객 주문에 최초 대응. 주문 제품의 가용성 파악, 고객 신용조회","src":"이론"},{"t":"재고관리 모듈: 주문량에 따라 적정재고를 유지하며 불필요한 재고를 억제해 재고유지 비용 절감","src":"이론"},{"t":"창고관리 모듈(WMS): 최저비용으로 창고 공간·작업자·하역설비를 유효 활용해 서비스 수준 제고. 입출고·재고이동정보 포함","src":"이론"},{"t":"수배송관리 모듈(TMS): 적기 배송체계 확립과 최적 운송계획 수립. 최근 CVO 도입으로 영차율 향상 지원","src":"이론"},{"t":"생산관리·마케팅관리 모듈은 LIS와 직접적 관계가 없음","src":"이론"}]},{"머리":"EDI","줄":[{"t":"EDI: 표준화된 상거래 서식으로 작성된 기업 간 전자문서교환 시스템. 거래업체 간 합의된 전자문서표준으로 컴퓨터 간 구조화된 데이터 전송","src":"기출 2021-26, 2023-40"},{"t":"효과: 정확한 실시간 업무 처리, 종이문서 수작업·처리 오류 감소, 국제 경쟁력 강화","src":"기출 2023-40"},{"t":"물류 EDI 도입 시 주문처리·물품추적·반품 영역에서 고객 만족도 향상","src":"기출 2025-8"},{"t":"국내에도 EDI 시스템 개발 사례가 있음(KL-NET, KT-NET 등)","src":"기출 2023-40, 보충"},{"t":"EDI 직접적 효과: 시간 절감·거래절차 단축, 자료 재입력 방지, 업무처리 오류 감소, 인건비·업무처리 비용 감소","src":"이론"},{"t":"EDI 간접적 효과: 재고 감소, 고객서비스 향상, 문서관리 효율성 증대, 효율적 인력활용","src":"이론"},{"t":"EDI: 표준화된 기업 간 거래서식이나 기업과 행정부서 간 공증서식을 합의된 의사전달 양식에 따라 컴퓨터 간에 교환하는 전자문서 교환방식","src":"기출 2020-23"}]},{"머리":"VAN","줄":[{"t":"VAN(부가가치통신망): 부가가치를 부여한 음성 또는 데이터를 정보로 제공하는 광범위하고 복합적인 서비스의 집합","src":"기출 2021-25"},{"t":"VAN은 이용이 늘어나는 서비스. 한정된 지역의 장치를 연결하는 것은 LAN의 설명","src":"기출 2021-25, 보충"},{"t":"VAN: 다자간 또는 제3자 네트워크를 매개로 기업 간 자료를 교환하는 통신망. EDI 수행의 가장 효율적 수단","src":"이론"},{"t":"VAN: 통신회선에 정보처리 기능을 결합해 부가가치를 부여한 서비스 통신망. 정보전송과 정보의 축적·가공·변환처리 등 부가가치를 부여","src":"이론"},{"t":"VAN 특징: 통신사업자로부터 고속통신회선을 임대받아 개별고객에게 할당하고 이용료 징수. 제한된 사용자만 사용 가능, 정보망 이용료가 높음, 저속이지만 아이디·비밀번호·IP 확인 등 상대적으로 보안수준이 높음","src":"이론"},{"t":"VAN 도입의 주요 경제적 효과: 정보전달 경로의 단축화","src":"이론"}]},{"머리":"POS","줄":[{"t":"POS(판매시점관리): 상품 판매 시점에 발생하는 정보를 저장하고, 실시간 매출 등록·자동정산·집계. 발주·구매·배송·재고관리와 연계","src":"기출 2023-37, 2025-25"},{"t":"소비동향이 반영된 판매정보를 실시간으로 파악해 판매·재고·고객관리 효율 향상","src":"기출 2021-26"}]},{"머리":"약어 연결","줄":[{"t":"TRS: 주파수공용통신","src":"기출 2022-13"},{"t":"ITS: 지능형교통정보시스템","src":"기출 2022-13"},{"t":"CVO: 첨단화물운송시스템","src":"기출 2022-13"},{"t":"KROIS: 철도화물정보망(철도운영정보시스템)","src":"기출 2022-13, 2024-27"},{"t":"POS: 판매시점관리","src":"기출 2022-13"},{"t":"CVO의 정식 영문은 Commercial Vehicle Operations","src":"보충"},{"t":"KL-NET: 물류거점 간 정보 및 물류 EDI 서비스. KT-NET: 무역정보망(무역자동화)","src":"보충"},{"t":"PORT-MIS: 해양수산부의 항만운영정보시스템","src":"보충"},{"t":"DPS(디지털 피킹 시스템): 랙·보관장소에 전자 표시기를 설치해 출고 품목의 보관구역·출고수량을 표시, 완료 시 신호가 꺼져 작업 완료 확인","src":"기출 2024-26, 2025-39"},{"t":"DAS(디지털 어소팅 시스템): 분배·분류 작업 지원(DPS와 구분)","src":"보충"},{"t":"ISDN(종합디지털서비스망): 디지털 통신망으로 음성·문자·영상 등을 종합적으로 사용하는 통신서비스. 기존 전화망에서 발전된 차세대 기간통신망","src":"이론"},{"t":"LAN(근거리통신망): 한정된 지역 내에서 고속 전송속도의 물리적 통신채널로 다수 개별장치가 통신하도록 구성한 시스템","src":"이론"},{"t":"WAN(원거리통신망): 원격지를 통신회선으로 연결한 광역 통신망. 해외지사·공장과 국내 본사를 연결하는 데 사용","src":"이론"},{"t":"KT-NET(한국무역정보통신): 우리나라 최초로 무역자동화시스템을 개통한 무역정보망. 수출입 업무를 EDI로 자동화. 서비스: 무역자동화(무역·통관·물류부문), 유통 EDI(수·발주 EDI·해외 EDI·유통정보교환), 시스템 통합서비스(컨설팅·개발), 네트워크 연구·개발","src":"이론"},{"t":"KL-NET(한국물류정보통신): 물류정보망. 우리나라 물류업무의 온라인화를 위해 개발. 종합물류정보전산망 전담사업자, PORT-MIS 사업, KROIS 연계사업자로서 물류업무 전 부문의 자동화·정보화 담당","src":"이론"}]},{"머리":"정보기술 용어","줄":[{"t":"ASP: 정보시스템을 자체 개발하는 것에 비해 구축기간이 짧음","src":"기출 2022-15, 보충"},{"t":"CALS: Computer Aided Acquisition & Logistics Support에서 Commerce At Light Speed로 발전","src":"기출 2022-15"},{"t":"CIM: 정보시스템으로 제조·개발·판매·물류 등 일련의 과정을 통합 관리하는 생산관리시스템","src":"기출 2022-15"},{"t":"IoT는 사물 간 통신 기술. 인간의 학습·추론·자연언어 이해능력을 컴퓨터로 구현한 기술은 인공지능(AI)","src":"기출 2022-15, 2024-40"},{"t":"QR코드는 컬러 격자무늬 패턴의 2차원 바코드(3차원 아님)","src":"기출 2022-15, 2025-23, 보충"},{"t":"GPS: 인공위성과의 무선교신으로 차량·선박 등의 위치를 파악","src":"기출 2025-25"},{"t":"IoT: 사람·사물·공간·데이터 등이 인터넷으로 연결되어 정보가 생성·수집·활용되게 하는 기술. 인간·사물·서비스 환경요소가 인간의 명시적 개입 없이 상호 협력적으로 센싱·네트워킹·정보처리","src":"이론"},{"t":"IoT·AI 기반 스마트팩토리의 고객맞춤형 생산은 물류의 다품종·소량·다빈도화를 촉진","src":"이론"},{"t":"유비쿼터스: 언제 어디서나 누구나 정보교환이 가능한 모바일 이동통신 정보시스템. 전제: 컨버전스 기술 일반화·광대역화·IT기기 저가화, RFID Tag·USN·Telematics·무선인터넷·모바일 서비스, 모든 전자기기에 컴퓨팅 기능","src":"이론"},{"t":"USN(Ubiquitous Sensor Network): 센서 네트워크를 이용해 유비쿼터스 환경을 구현하는 기술","src":"이론"},{"t":"CALS: 제품 생산부터 폐기까지 전 과정(life-cycle)의 모든 정보를 디지털 정보기술 통합으로 실시간 구현하는 산업 정보화 전략. Computer Aided Logistics Support에서 시작해 Commerce At Light Speed(광속상거래)로 발전","src":"이론"},{"t":"CALS 구성요소: 조달-EDI, 생산-JIT, 설계-동시공학(Concurrent Engineering), 제조-품질공학(Quality Engineering), 운용-물류(Logistics)","src":"이론"}]},{"머리":"ERP","줄":[{"t":"ERP: 생산·판매·구매·인사·재무·물류 등 기업업무 전반을 통합 관리하는 정보시스템","src":"기출 2025-24, 2026-28"},{"t":"기업의 인적·물적 자원을 효율적으로 관리. 공급사슬 계획·실행 시스템에 필요한 정보 제공","src":"기출 2025-24, 2026-28"},{"t":"성공적 도입을 위해 업무 표준화와 프로세스 정비가 중요. 자재 조달·생산소요시간 단축 효과","src":"기출 2025-24, 2026-28"},{"t":"자재소요계획 MRP에서 MRP-II를 거쳐 ERP로 발전","src":"기출 2024-22, 2025-24"},{"t":"기업 내부 단위기능 중심의 생산성 향상이 아니라 전사 통합","src":"기출 2026-28"}]},{"머리":"물류정보시스템의 운영기법","줄":[{"t":"EOS(전자주문시스템): 체인매장에서 상품이 판매되면 POS 데이터가 거래처에서 중앙컴퓨터에 자동 입력. 한정된 매장 공간에 더 많은 상품 진열, 상품코드에 의한 정확한 발주, 발주작업 표준화·매뉴얼화로 신속한 발주체계 확립","src":"이론"},{"t":"CAO(자동발주시스템): EDI 기반. 자동화된 주문관리로 수요관리 효율을 높여 재고수준 감소. 단품관리가 쉽고 판매단위 수량관리로 판매예측과 판매결과 차이 최소화","src":"이론"},{"t":"POS 개념: 판매시점에 상품 바코드로 발생하는 데이터를 실시간 처리. 단품별 정보를 자동 수집해 발주·매입·발송·재고관리 시점에 정보 제공","src":"이론"},{"t":"POS 도입효과: 계산원 생산성 향상, 입력오류 방지, 점포사무작업 간소화, 가격표 부착작업 감소, 판매정보 실시간 파악으로 판매·재고·고객관리 효율 향상","src":"이론"},{"t":"POS 구성: POS 터미널, 스토어 컨트롤러, 호스트 컴퓨터. 바코드와 바코드 리더기 부착","src":"이론"},{"t":"POS 활용 - 유통업체: 판매동향·ABC분석으로 인기/비인기 제품 분석, 적절한 가격설정·매출극대화 전략, 상품구색·진열관리, 경쟁점포 판매동향 비교","src":"이론"},{"t":"POS 활용 - 제조업체: 생산계획·마케팅 전략 수립, 광고 등 판촉효과 분석, 신상품 동향 파악, 경쟁사 제품 판매동향 비교","src":"이론"},{"t":"TMS(운송관리시스템): 출하 화물량·목적지 수·배차 가능 차량으로 가장 효율적인 배차방법, 운송차량 선정, 운송비 계산, 차량별 운송실적 관리. 최적차량 운용과 배송루트 선정으로 배송 리드타임·운송비 절감","src":"이론"},{"t":"ITS(지능형 교통시스템): 도로·차량·교통시스템 등에 전자·제어·통신 등 첨단기술을 접목한 차세대 교통체계. ATMS(첨단교통관리)·ATIS(첨단교통정보)·CVO(첨단화물운송) 등으로 구성","src":"이론"},{"t":"CVO(첨단화물운송시스템, Commercial Vehicle Operation System): 차주와 화주를 연결. 화물차량 위치·적재화물 종류·운행상태·노선상황·화물알선정보를 자동 파악해 운행을 최적화하는 ITS의 하나","src":"이론"},{"t":"CVO 하위시스템: FFMS(Freight and Fleet Management System, 화물 및 화물차량관리), HMMS(Hazardous Material Monitoring System, 위험물차량관리)","src":"이론"},{"t":"GPS: 인공위성과 통신망을 이용한 위치측정시스템. 이동체 위치파악, 운행차량 관리·통제, 최단경로 탐색에 활용. 인공위성으로 신호를 보낼 수는 없고 인공위성이 보내는 신호를 받기만 함","src":"이론"},{"t":"TRS(주파수공용통신): 화물추적용 무선통신시스템. 중계국에 할당된 여러 채널을 공동 사용하는 무전기 시스템으로 이동 중 실시간 송·수신. 화주가 화물정보센터에 의뢰하면 센터가 해당 지역 공차 상태 트럭기사에게 일감정보를 알림","src":"이론"},{"t":"KROIS(철도운영정보시스템): 1996년부터 운영, 2011년 말 차세대로 발전. 차량열차·화물운송·승무원관리·운송정보·차량기계 업무를 모듈화. KL-Net과 연계해 EDI로 운용. 철도공사·화주·운송업체·터미널이 서비스 대상. 차량열차운용·화물운송·고객지원·운송정보 하부시스템","src":"이론"},{"t":"PORT-MIS(해운항만물류정보시스템): 선박 입출항 관련 업무와 안전 항행에 관한 항만운영정보처리시스템. 수출입 관련 정부기관(해양수산부 등)·물류업체(선사·화주·부두운영회사)·정보중개업자(KL-Net)가 참여해 구축, 해양수산부와 항만공사가 운영","src":"이론"},{"t":"국토교통부 국가물류통합정보시스템: 지능형 교통시스템(ITS), 철도운영정보시스템(KROIS), 항만운영정보시스템(PORT-MIS), 항공물류정보시스템(AIRCIS)으로 구성","src":"이론"},{"t":"WMS 개념: 공급망 전체의 원활한 흐름을 지원하도록 창고를 효율적으로 관리. 제품 입·출고, 보관, 품질보전, 보관효율, 창고비, 운송지원, 정보처리를 지원","src":"이론"},{"t":"WMS 목적: 창고 공간효율 극대화와 작업자·하역설비 유효 활용으로 고객서비스 수준 제고·물류비용 감소. '입고 → 피킹 → 출하' 프로세스 자동화로 운반관리 효율화","src":"이론"},{"t":"WMS 증가 효과: 재고 정확도, 공간·설비 활용도, 제품처리 능력, 재고회전율, 고객서비스, 노동·설비 생산성","src":"이론"},{"t":"WMS 감소 효과: 재고망실, 보관위치 오지정, 제품 피킹시간, 직·간접 인건비, 서류·전표 작업, 설비비용","src":"이론"}]}],"함정":[{"x":"정보의 발생원, 처리장소, 전달대상 등이 한 곳에 집중되어 있다.","o":"물류정보의 발생원·처리장소·전달대상은 분산되어 있다.","src":"기출 2021-23"},{"x":"한정된 지역의 분산된 장치들을 연결하여 정보를 공유하거나 교환하는 것이다. (VAN)","o":"그 설명은 LAN. VAN은 부가가치통신망.","src":"기출 2021-25"},{"x":"컴퓨터 성능의 발달로 정보수집 능력이 우수한 대기업에 정보가 집중되므로 중소기업의 활용 가능성은 낮아지고 있다.","o":"중소기업의 활용 가능성은 높아진다(추정).","src":"기출 2021-25, 보충(추정)"},{"x":"1990년대 미국의 AT&T가 전화회선을 임대하여 특정인에게 통신 서비스를 제공한 것이 효시이다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2021-25"},{"x":"VAN 서비스는 컴퓨터 성능 향상으로 인해 이용이 감소되고 있다.","o":"출제 오답(바른 수치 미확인). 이용이 감소한다는 서술이 틀림.","src":"기출 2021-25"},{"x":"물류정보시스템의 목적은 물류비가 증가하더라도 고객서비스를 향상시키는 것이다.","o":"물류서비스 향상과 물류비 절감이 목적이다.","src":"기출 2021-26"},{"x":"정보의 종류가 다양하고 규모가 크지만, 성수기와 평상시의 정보량 차이는 작다.","o":"성수기와 비수기의 정보량 차이가 크다.","src":"기출 2023-36"},{"x":"국제적으로는 다양한 EDI 시스템이 존재하지만, 국내 EDI 시스템 개발 사례는 존재하지 않는다.","o":"국내에도 EDI 시스템 개발 사례가 있다.","src":"기출 2023-40"},{"x":"개별 물류활동들의 통합을 통한 전체 최적화보다는 특정한 물류활동의 최적화를 위하여 구축한다.","o":"개별 활동 통합을 통한 전체 최적화를 위해 구축한다.","src":"기출 2024-28, 2026-25"},{"x":"개별 물류활동의 통합을 통한 전체 최적화보다 특정 물류활동의 최적화를 위하여 구축한다.","o":"개별 활동 통합으로 전체 최적화를 이루기 위해 구축한다.","src":"기출 2026-25"},{"x":"1970년대 생산현장 관리를 위해 개발된 MES(Manufacturing Execution System)에서 유래하였다.","o":"출제 오답(바른 수치 미확인). ERP는 MRP → MRP-II → ERP로 발전(보충).","src":"기출 2025-24"},{"x":"기업 내부의 단위기능 중심의 생산성 향상을 추구한다. (ERP)","o":"기업 전반(전사)의 통합 관리를 추구한다.","src":"기출 2026-28"},{"x":"ASP는 정보시스템을 자체 개발하는 것에 비해 구축기간이 오래 걸린다.","o":"ASP는 구축기간이 짧다.","src":"기출 2022-15"},{"x":"CALS 개념은 Commerce At Light Speed로부터 Computer Aided Acquisition & Logistics Support로 발전되었다.","o":"Computer Aided Acquisition & Logistics Support에서 Commerce At Light Speed로 발전.","src":"기출 2022-15"},{"x":"IoT(Internet of Things)는 인간의 학습능력과 지각능력, 추론능력, 자연언어의 이해능력 등을 컴퓨터 프로그램으로 실현한 기술을 의미한다.","o":"그 설명은 인공지능(AI).","src":"기출 2022-15"},{"x":"QR코드는 컬러 격자무늬 패턴으로 정보를 나타내는 3차원 바코드이다.","o":"QR코드는 2차원 바코드이다.","src":"기출 2022-15"},{"x":"KT-NET은 물류거점 간의 원활한 정보 및 물류 EDI 서비스를 제공한다.","o":"출제 오답(바른 수치 미확인). KT-NET은 무역정보망(보충).","src":"기출 2024-27, 보충"},{"x":"PORT-MIS는 항만 및 공항에 관한 정보를 제공하며 국토교통부에서 관리하는 정보망이다.","o":"출제 오답(바른 수치 미확인). 해양수산부 관리 항만정보시스템(보충).","src":"기출 2024-27, 보충"},{"x":"CVO는 Common Vehicle Operations의 약어이다.","o":"CVO는 Commercial Vehicle Operations(보충).","src":"기출 2024-27, 보충"},{"x":"KL-NET은 우리나라 최초의 무역정보망으로서 무역자동화 서비스를 제공한다.","o":"출제 오답(바른 수치 미확인). 무역자동화는 KT-NET(보충).","src":"기출 2024-27, 보충"},{"x":"RFID는 태그 데이터의 변경 및 추가는 불가능하나, 능동형 및 수동형 여부에 따라 메모리의 양을 다르게 정의할 수 있다.","o":"RFID는 태그 데이터의 변경·추가가 가능(읽고 쓰기)하며 능동형·수동형에 따라 메모리 양을 다르게 정의 가능","src":"기출 2020-26"},{"x":"USN은 센서 네트워크를 이용하여 유비쿼터스 환경을 구현하는 기술이며, 사물에 QR코드를 부착하여 정보를 인식하고 관리하는 정보기술을 말한다.","o":"USN은 센서 네트워크로 유비쿼터스 환경을 구현하는 기술. 사물에 QR코드를 부착하는 기술이 아님","src":"기출 2020-26"},{"x":"CALS의 개념은 Commerce At Light Speed로부터 Computer Aided Logistics Support로 발전되었다.","o":"순서가 반대. Computer Aided Logistics Support에서 시작해 Commerce At Light Speed(광속상거래)로 발전","src":"기출 2020-26"},{"x":"ASP란 응용소프트웨어 공급서비스를 뜻하며 사용자 입장에서는 시스템의 자체 개발에 비하여 초기 투자비용이 더 많이 발생하는 단점이 있다.","o":"ASP는 자체 개발에 비해 구축기간이 짧고 초기 투자비용이 적게 드는 것이 장점","src":"기출 2020-26"},{"x":"[물류정보망] CVO는 Carrier Vehicle Operations의 약어로서, 화물차량에 부착된 단말기를 이용하여 실시간으로 차량 및 화물을 추적·관리하는 방식이다.","o":"CVO는 Commercial Vehicle Operation(첨단화물운송시스템)의 약어. 화물차량·화물의 위치를 실시간 추적·관리하는 ITS의 하나","src":"기출 2020-27"},{"x":"[물류정보망] KL-NET는 무역정보망으로서, 무역정보화를 통한 국가경쟁력 강화를 목적으로 개발되었다.","o":"이는 KT-NET의 설명. KL-NET(한국물류정보통신)은 물류업무 온라인화를 위한 물류정보망","src":"기출 2020-27"},{"x":"KT-NET는 물류정보망으로서, 물류업무의 온라인화를 위해 개발된 정보망이다.","o":"이는 KL-NET의 설명. KT-NET(한국무역정보통신)은 무역자동화를 위한 무역정보망","src":"기출 2020-27"},{"x":"[물류정보망] PORT-MIS는 항만운영관리 시스템으로서, 한국물류협회가 개발 및 운영하는 시스템이다.","o":"PORT-MIS는 해양수산부와 항만공사가 운영하는 항만운영정보시스템. 정부기관·물류업체·정보중개업자(KL-Net)가 참여해 구축","src":"기출 2020-27"},{"x":"[블록체인(Block Chain)] 퍼블릭 블록체인(Public Block Chain)과 프라이빗 블록체인(Private Block Chain)은 누구나 접근이 가능하다.","o":"퍼블릭은 누구나 참여하는 개방형, 프라이빗은 미리 정해진 조직·개인만 참여하는 폐쇄형, 컨소시엄은 허가받은 사용자만 접근","src":"기출 2020-40"}]},"#9":{"묶음":[{"머리":"GS1 표준코드와 EAN-13","줄":[{"t":"GS1 표준코드는 미국이 제정한 UPC와 유럽이 제정한 EAN 등을 표준화한 것","src":"기출 2021-24, 2026-27"},{"t":"EAN-13 구성: 국가식별코드 + 제조업체코드 + 상품품목코드 + 체크디지트(1자리)","src":"기출 2022-12, 2023-39"},{"t":"국가식별코드 2~3자리. 3자리 구성이며 1982년 이전 EAN International 가입국은 2자리","src":"기출 2022-12, 2023-39"},{"t":"제조업체코드: EAN-13(A) 4자리, EAN-13(B) 6자리","src":"기출 2022-12, 2023-39"},{"t":"상품품목코드: EAN-13(A) 5자리, EAN-13(B) 3자리","src":"기출 2022-12, 2023-39"},{"t":"체크디지트 1자리: 스캐너 판독 오류 방지","src":"기출 2022-12, 2023-39"},{"t":"EAN-13(B)는 제조업체코드 6자리·상품품목코드 3자리라 취급 품목 수가 적은 기업에 활용(품목이 많으면 A)","src":"기출 2022-12"},{"t":"EAN-13은 물류식별코드를 갖지 않음. 물류용기용은 GS1-14(ITF-14)처럼 물류식별코드를 가진 별도 코드","src":"기출 2023-39, 2026-27"},{"t":"GS1-14: 기업 간 거래 시 주로 골판지 박스에 사용. 물류식별코드·국가식별코드·제조업체코드·상품품목코드·체크디지트로 구성","src":"기출 2026-27"},{"t":"GS1-13의 처음 세 자리는 국가식별코드","src":"기출 2026-27"},{"t":"바코드: 스캐너가 판독하도록 굵기가 다른 흑백 막대를 조합한 코드. 표준형과 비표준형. POS 시스템의 효과적 이용을 위한 중요 구성요소","src":"이론"},{"t":"발전사: 1973 미국 UPC 도입 → 1988 영국·프랑스·독일·일본 EAN 도입 → 1988 한국 EAN 가입(KAN 880 부여) → 2002 UPC 사용국의 EAN 가입 → 2005 GS1 통합, GTIN(국제거래 단품식별코드) 적용","src":"이론"},{"t":"GS1: 제품·운송 단위·위치·서비스를 고유하게 식별해 글로벌 다업종 공급사슬을 효율적으로 관리하게 하는 표준","src":"이론"},{"t":"바코드 구조: Quiet Zone(시작문자 앞·멈춤문자 뒤 공백), 시작·멈춤문자(시작문자는 입력 방향과 바코드 종류를 스캐너에 알림), Interpretation Line(수동 입력용 숫자·문자), 체크디지트, Bar/Space(가장 좁은 바/스페이스를 X 디멘션이라 함)","src":"이론"},{"t":"체크디지트: 스캔 오류로 엉뚱한 값을 치르지 않도록 메시지가 정확히 읽혔는지 검사","src":"이론"},{"t":"바코드 장점: 제작 용이·도입비용 저렴, 데이터 입력 간소화, 인건비·관리유지비 절감, 표시 용이·응용범위 광범위, 신속한 데이터수집","src":"이론"},{"t":"바코드 단점: 정보의 변경·추가 불가, 쓰기 불가, 파손되면 잘 읽지 못함, 제품에 대한 충분한 정보수집에 한계","src":"이론"},{"t":"KAN 코드는 대한상공회의소 유통물류진흥원에서 부여. 표준형(KAN-13)과 단축형(KAN-8). 백화점·슈퍼마켓·편의점 등에서 최종 소비자에게 판매되는 상품에 사용","src":"이론"},{"t":"KAN-13 표준형(A): 13자리. 국가식별코드 880, 제조업체 4자리, 상품품목 5자리, 체크디지트 1자리. 표준형(B): 제조업체 수 증가로 제조업체코드를 6자리로 늘림","src":"이론"},{"t":"표준형 A는 의류 등 다품목 취급업체에, 표준형 B는 식품·화장품·잡화 등 소스마킹을 요하는 업체에 부여","src":"이론"},{"t":"단축형(KAN-8): 국가코드(3) + 제조업체코드(3) + 상품코드(1) + 검증코드(1)","src":"이론"},{"t":"GTIN-8·12·13·14: 앞에 AI 01이 붙고 국가/업체코드 + 상품코드 + 체크디지트(C/D)로 구성","src":"이론"},{"t":"GS1 국제표준바코드 = GTIN 상품식별코드(번호체계) + EAN/UCC 바코드 형태","src":"이론"},{"t":"EAN-13(표준형): KAN-13과 동일. 표준형 상품식별코드(GTIN-13)를 GS1-13 바코드에 입력. 소매 상품에 가장 일반적으로 사용","src":"이론"},{"t":"EAN-8(단축형): KAN-8과 동일. 단축형 상품식별코드(GTIN-8)를 나타내며 EAN-13 적용이 어려운 소형 물품 식별에 제한적으로 사용","src":"이론"},{"t":"EAN-13 심볼 구성 예: 국가표시(880) + 제조업체코드 + 자체상품코드 + 검증코드","src":"이론"},{"t":"ITF-14(표준물류 바코드) = GTIN-14(표준물류 식별코드) + ITF-14(바코드 심벌). 주로 골판지상자에 직접 인쇄. 생산공장·물류센터 입·출하 시 동일 상품의 물류단위 인식에 사용","src":"이론"},{"t":"ITF-14는 소매점 계산대를 거치지 않는 상품의 GTIN 바코드에만 사용","src":"이론"},{"t":"GS1-14 구성: 물류식별코드 1자리 + 국가식별코드 3자리 + 제조업체코드 4자리 + 상품품목코드 5자리 + 체크디지트 1자리. 물류식별코드는 0~9로 표시","src":"이론"},{"t":"EAN-128(GS1-128): 총 18자리. 바코드 규격이 커서 파렛트·컨테이너 등 물류단위(외부포장)에 사용. 주로 비소매품에 적용","src":"이론"},{"t":"ISBN 구성: 유통분류번호(3) + 국가코드(2) + 발행자번호 및 서명식별(7) + 검증번호(1)","src":"이론"}]},{"머리":"1차원·2차원 바코드","줄":[{"t":"1차원 바코드: EAN-8, EAN-13, ITF-14, GS1-128","src":"기출 2024-24"},{"t":"2차원 바코드: PDF-417 등. 1차원보다 대량 데이터, 훼손·오염 시 오류 정정 용이, 텍스트·그래픽·사진 저장","src":"기출 2024-24, 2025-23"},{"t":"2차원 바코드 분류: 다층형(스택형)과 매트릭스형","src":"기출 2025-23, 2026-27"},{"t":"다층형: 1차원 바코드처럼 몇 개 문자가 수평으로 열을 구성하여 쌓음. Code 49, PDF-417","src":"기출 2026-27"},{"t":"매트릭스형: 정방형의 동일 폭 흑백요소를 모자이크식으로 배열. QR Code, Maxi Code","src":"기출 2026-27"},{"t":"QR코드 개발국: 일본(덴소웨이브). 미국 UPS가 개발한 것은 MaxiCode","src":"보충"},{"t":"2차원 바코드 종류: 매트릭스형(QR Code, Maxicode, DataMatrix)과 다층형(PDF-417, Code 49)","src":"이론"},{"t":"2차원 바코드는 한국어뿐 아니라 외국어도 코드화 가능","src":"이론"},{"t":"정보량: 1차원 바코드 최대 30자, 2차원 바코드 최대 3,000자","src":"이론"},{"t":"2차원 바코드는 오류 정정기능이 내장되어 오염된 경우 데이터 복원 가능. 1차원 바코드는 손상·누락 시 판독이 어려움","src":"이론"},{"t":"2차원 바코드는 텍스트뿐 아니라 그래픽·사진 등 다양한 데이터를 담을 수 있음","src":"이론"},{"t":"QR Code는 일본에서 개발. QR Code 외의 2차원 바코드는 전부 미국에서 개발","src":"이론"},{"t":"QR코드: 정사각형 모양의 흑백 격자무늬 2차원(매트릭스형) 바코드. 1차원 바코드보다 많은 정보 수용·오류복원 기능 우수. 1994년 일본 덴소웨이브가 개발","src":"기출 2020-25"}]},{"머리":"RFID","줄":[{"t":"RFID: 무선주파수 식별(Radio Frequency Identification). 바코드·스캐닝이 아닌 무선주파수 기반","src":"기출 2024-25, 2026-26"},{"t":"태그에 접촉하지 않아도 인식 가능","src":"기출 2022-11, 2024-25, 2026-26"},{"t":"바코드와 달리 읽고 쓰기(Read/Write) 가능. 태그 데이터 변경·추가 가능","src":"기출 2022-11, 2024-25"},{"t":"일시에 복수 태그 판독 가능","src":"기출 2022-11, 2025-25"},{"t":"바코드보다 가격이 비쌈. 개인정보 노출·사생활 침해 위험","src":"기출 2022-11"},{"t":"원거리·고속 이동 시에도 인식 가능. 반영구적 사용. 데이터 신뢰도 높음","src":"기출 2021-22"},{"t":"주파수 대역에 따라 태그 인식 거리와 인식 속도가 다름. 국가별 사용 주파수가 동일하지 않음","src":"기출 2024-25, 2021-22, 2026-26"},{"t":"능동형 태그: 내장 배터리 전원, 지속적 식별정보 송신, 수동형보다 비싸고 원거리 통신 가능, 반영구 사용은 불가(배터리 수명)","src":"기출 2023-38"},{"t":"수동형 태그는 지속적 식별정보 송신이 불가. 능동형은 송수신 모두 가능하고 구조가 복잡","src":"기출 2026-26, 보충"},{"t":"RFID: 전자태그에 생산·수배송·보관·판매·소비 전 과정 정보를 담고 안테나로 리더가 정보를 읽는 무선주파수 인식기술. 바코드와 달리 원산지·중간이동과정 등 다량의 데이터 저장 가능","src":"이론"},{"t":"RFID 구성: Tag, 안테나, 리더, 호스트(Local Host), 케이블링·네트워크","src":"이론"},{"t":"Tag: 데이터가 입력되는 IC 칩과 안테나로 구성","src":"이론"},{"t":"능동형(active) Tag: 배터리 전원을 내장해 자발적으로 원거리 전파를 송신","src":"이론"},{"t":"수동형(passive) Tag: 판독기(리더)의 동력만으로 칩 정보를 읽고 통신. 전파의 수신만 가능하고 구조가 간단. 배터리가 없어 저렴하며 2~3m 내 단거리 판독에 효율적","src":"이론"},{"t":"반수동형(semi-passive) Tag: 배터리를 내장하나 판독기 신호를 받을 때까지 작동하지 않아 오래 사용. 지속적 식별이 필요하지 않은 상품에 사용","src":"이론"},{"t":"안테나: 무선주파수를 발사하고 태그가 전송한 데이터를 받아 리더에 전달. 리더: 주파수 발신 제어와 수신 데이터 해독(고정형·이동형). 호스트: 대량의 태그자료 처리와 분산된 리더 시스템 관리","src":"이론"},{"t":"RFID는 주파수 대역에 따라 다양한 분야에 응용. 주파수 대역은 저주파·고주파가 있고 국가별로 사용 주파수도 다름","src":"이론"},{"t":"RFID는 능동형·수동형 여부에 따라 메모리의 양을 다르게 정의 가능. 비접촉식 무선시스템. 읽기·쓰기 모두 가능","src":"이론"},{"t":"RFID 구축비용이 바코드보다 높아 바코드를 완전히 대체하기엔 한계","src":"이론"},{"t":"주파수 대역별: 고주파수일수록 중장거리용, 태그를 소형으로 제작 가능, 인식속도 빠름. 저주파수일수록 구축비용 저렴, 장애물 영향을 덜 받음. 환경·장애물 영향은 고주파대역이 더 큼","src":"이론"},{"t":"RFID 도입효과: 자동차 제조공정 응용, 창고관리, 파렛트·컨테이너 등 물류용기 부착, 장기적으로 채찍효과 감소 기여. 개별 상품 부착 시 상품 가치와 태그 가격 비교 필요","src":"이론"},{"t":"RFID는 일시에 다량 태그를 판독할 수 있으나 금속·액체에 의한 전파장애가 발생할 수 있음","src":"이론"}]},{"머리":"신기술","줄":[{"t":"블록체인: 분산원장을 통해 거래기록을 참여자가 분산 보관, 투명성·신뢰성 확보. 해킹 방지를 위해 개발","src":"기출 2022-34, 2026-40"},{"t":"블록체인 유형: 퍼블릭, 프라이빗, 컨소시엄","src":"기출 2022-34"},{"t":"블록체인으로 화물 추적·관리 상황을 점검하고 운송 중 문제에 실시간 대처. 공급사슬 가시성·투명성 향상","src":"기출 2022-34, 2024-40, 2025-25"},{"t":"스마트물류의 특징: 초연결성, 초지능화, 공유경제","src":"기출 2024-40"},{"t":"IoT: 사물 간 통신으로 실시간 데이터 수집","src":"기출 2026-40"},{"t":"빅데이터: 공급사슬 데이터를 수집·저장·처리·분석·시각화","src":"기출 2024-40, 2026-40"},{"t":"AI: 자연어 처리, 시각적·인지적 인식 등으로 의사결정 지원","src":"기출 2024-40, 2026-40"},{"t":"클라우드 서비스: IaaS, PaaS, SaaS로 구분","src":"기출 2024-40"},{"t":"3D 프린팅: 쾌속조형(Rapid Prototyping)에서 유래. 다품종 소량생산 유리, 재고수준 감소, 시제품 제작시간 단축","src":"기출 2025-27"},{"t":"3D 프린팅은 고가의 금형제작 비용이 발생하지 않음","src":"기출 2025-27"}]},{"머리":"블록체인","줄":[{"t":"블록체인: 분산원장 또는 공공거래장부. 다수 상대방과 거래할 때 데이터를 중앙 서버가 아닌 사용자들의 개인 디지털 장비에 분산·저장해 공동 관리하는 분산형 정보기술. 암호화폐 거래 시 해킹을 막는 기술에서 출발","src":"이론"},{"t":"비트코인은 블록체인 기술을 이용한 전자화폐. 블록체인은 비트코인 거래기록을 저장한 공공거래장부","src":"이론"},{"t":"물류 적용: 화주가 화물 추적·관리 상황을 실시간 점검, 운송 중 관리 부실에 의한 과실을 실시간 파악·대처. 항만운송·항공운송·관세청 수출통관 등에서 활용 추진","src":"이론"},{"t":"프라이빗 블록체인: 미리 정해진 조직이나 개인만 참여하는 폐쇄형. 퍼블릭 블록체인: 누구든 자유롭게 참여하는 개방형. 컨소시엄 블록체인: 허가받은 사용자만 접근 가능","src":"이론"}]},{"머리":"인공지능(AI)","줄":[{"t":"AI: 컴퓨터 시스템이 인간의 언어·지능을 모델링하는 기술. 인간과 유사하게 사고하는 컴퓨터 지능을 일컫는 포괄적 개념. 2000년대 알파고·왓슨, 최근 ChatGPT","src":"이론"},{"t":"생성형 AI: 비정형 딥러닝 모델을 활용해 사용자 입력 기반으로 콘텐츠를 생성(예: ChatGPT)","src":"이론"},{"t":"대화형 AI: 챗봇·가상 상담원 등. 대용량 데이터·머신러닝·자연어 처리로 음성·텍스트 입력을 인식하고 다양한 언어로 의미를 변환","src":"이론"},{"t":"딥러닝: 인공신경망 기반의 기계 학습기술. 인간 두뇌가 데이터에서 패턴을 발견해 사물을 구분하는 방식을 모방","src":"이론"}]}],"함정":[{"x":"태그 데이터의 변경 및 추가는 자유롭지만 일시에 복수의 태그 판독은 불가능하다.","o":"일시에 복수의 태그를 판독할 수 있다.","src":"기출 2022-11, 2025-25"},{"x":"상품품목 코드는 3자리로 구성된다. (EAN-13(A))","o":"상품품목코드는 EAN-13(A) 5자리, (B) 3자리.","src":"기출 2022-12"},{"x":"반영구적으로 사용 가능하다. (능동형 RFID 태그)","o":"능동형은 배터리 수명 때문에 반영구적이지 않다.","src":"기출 2023-38"},{"x":"EAN-13(A)와 EAN-13(B) 모두 물류용기에 부착하기 위한 물류식별코드를 가지고 있다.","o":"EAN-13에는 물류식별코드가 없다.","src":"기출 2023-39"},{"x":"바코드와 스캐닝 기술 기반으로 구축된다. (RFID)","o":"RFID는 무선주파수 기술 기반.","src":"기출 2024-25, 2026-26"},{"x":"2차원 바코드의 하나인 QR 코드는 미국의 UPS사가 개발하였다.","o":"QR코드는 일본 덴소웨이브 개발(보충).","src":"기출 2025-23, 보충"},{"x":"주파수 대역과 무관하게 태그 인식거리 및 인식속도는 동일한 성능을 발휘한다.","o":"주파수 대역에 따라 인식거리·속도가 다르다.","src":"기출 2026-26"},{"x":"수동형 태그는 지속적인 식별정보 송신이 가능하다.","o":"지속 송신은 능동형.","src":"기출 2026-26"},{"x":"능동형 태그는 전파의 수신만 가능하고 구조가 간단하다.","o":"능동형은 송수신 가능, 구조가 복잡(보충).","src":"기출 2026-26, 보충"},{"x":"GS1 표준코드는 미국에서 제정한 EAN과 유럽에서 제정한 UPC 등을 표준화한 것이다.","o":"미국 UPC, 유럽 EAN.","src":"기출 2026-27"},{"x":"1차원 바코드 GS1-13의 처음 세 자리는 물류식별코드를 의미한다.","o":"처음 세 자리는 국가식별코드.","src":"기출 2026-27"},{"x":"2차원 다층형 바코드는 정방형의 동일한 폭의 흑백요소를 모자이크식으로 배열하여 구성하며 QR Code, Maxi Code 등이 있다.","o":"그 설명은 매트릭스형. 다층형은 Code 49, PDF-417.","src":"기출 2026-27"},{"x":"2차원 매트릭스형 바코드는 1차원 바코드와 같이 몇 개의 문자가 모여 수평으로 열을 구성하며, Code 49, PDF-417 등이 있다.","o":"그 설명은 다층형. 매트릭스형은 QR Code, Maxi Code.","src":"기출 2026-27"},{"x":"사물인터넷(IoT)은 논리적인 문제해결뿐만 아니라 자연어처리, 시각적 및 인지적 인식 등의 물류정보처리를 위한 의사결정 기술이다.","o":"그 설명은 인공지능(AI).","src":"기출 2024-40"},{"x":"VAN 서비스는 IaaS, PaaS, SaaS 등으로 구분하며 사이버 보안을 강화한 기술이다.","o":"IaaS·PaaS·SaaS는 클라우드 서비스의 구분.","src":"기출 2026-40"},{"x":"고가의 금형제작 비용이 발생한다. (3D 프린팅)","o":"3D 프린팅은 금형이 필요 없다.","src":"기출 2025-27"},{"x":"EAN-13 바코드에는 공급업체 코드가 포함된다.","o":"EAN-13은 국가식별코드·제조업체코드·상품품목코드·체크디지트로 구성. 공급업체 코드는 없음","src":"기출 2020-24"},{"x":"QR코드는 1차원 바코드에 비하여 오류복원 기능이 낮아 데이터 복원이 어렵다.","o":"QR코드(2차원 바코드)는 오류 정정기능이 내장되어 오염·손상 시에도 데이터 복원이 가능","src":"기출 2020-25"}]},"#10":{"묶음":[{"머리":"SCM의 개념","줄":[{"t":"SCM: 원자재 조달, 생산, 고객에게 제품·서비스 제공까지 프로세스 지향적이고 통합적인 접근 방법","src":"기출 2021-27, 2026-31"},{"t":"가치사슬 관점에서 원자재부터 소비까지의 구성원을 하나의 집단으로 간주하여 물류와 정보 흐름을 체계적으로 관리","src":"기출 2021-27"},{"t":"전체 공급사슬을 관리하여 비용과 시간을 최소화하고 이익을 최대화하도록 지원","src":"기출 2021-27, 2026-31"},{"t":"정보통신기술로 공급자·제조업자·소매업자·소비자 관련 상품·정보·자금 흐름을 신속하고 효율적으로 관리하여 부가가치를 향상","src":"기출 2021-27"},{"t":"공급사슬(SC): 원자재 공급자에서 공장·창고를 거쳐 소비자에게 제품이 전달되기까지 모든 과정의 물자·정보·지불·서비스 흐름. 공급자 → 생산기업 → 유통기업 → 최종소비자 간 공급활동의 연쇄적 구조","src":"이론"},{"t":"SCM: 생산자에서 사용자에 이르는 공급사슬의 정보 통합(integration)과 공유(share)로 불필요한 시간·비용을 절감하는 관리기법","src":"이론"},{"t":"SCM: 원재료·부품공급자 → 생산자 → 유통기관 → 최종소비자의 가치사슬(Value Chain)을 대상으로 정보 공유와 업무프로세스의 근본적 변혁으로 공급망 전체 효율을 극대화하는 경영활동","src":"이론"},{"t":"포터의 가치사슬: 지원활동(기업 하부구조·인적자원관리·기술개발·조달)과 주활동(본원적 활동: 물류투입·생산운영·물류산출·마케팅과 판매·서비스)","src":"이론"},{"t":"SCM 특징: 관련 기업 간 협력은 수평적 관계 추구, 단절 없는 흐름(Seamless Flow), 공급사슬 간 협업(Collaboration), 실시간 정보 공유, 동기화(Synchronization)","src":"이론"}]},{"머리":"SCM 도입 배경 (환경 변화)","줄":[{"t":"공급사슬 조직 간 상호 의존성 증대","src":"기출 2021-29"},{"t":"정보통신기술 발전으로 새로운 시장 등장과 경영방식 변화","src":"기출 2021-29"},{"t":"기업 간 경쟁 심화로 비용절감과 납기개선(납기준수)의 중요성 증대","src":"기출 2021-29, 2024-14"},{"t":"고객의 다양한 니즈에 맞춘 생산·납품 필요성 증대. 대량고객화 보편화","src":"기출 2021-29, 2023-28"},{"t":"물자 이동이 국내·역내에 국한되지 않고 글로벌화","src":"기출 2021-29"},{"t":"부가가치의 60~70%가 제조공정 외부 공급망에서 발생","src":"기출 2023-28"},{"t":"외부 불확실성(부품 납기·품질, 주문 납기·수요) 심화. 글로벌화로 공급망 리드타임이 길어지고 불확실해짐","src":"기출 2023-28, 2024-14"},{"t":"공급사슬 계획·운영을 지원하는 IT 솔루션 개발. 고객 요구 다양화와 제품 수명주기 단축","src":"기출 2024-14"},{"t":"부가가치 발생: 부가가치의 2/3 이상이 제조과정 외부 공급사슬에서 발생. 리드타임 중 제조 소요기간보다 공급사슬상 소요시간이 길어 전체 관리가 중요","src":"이론"},{"t":"불확실성 증가: 원·부자재 납기·품질과 고객수요의 불확실성을 제조업체가 수동적으로 흡수하던 방식에서 SCM으로 리드타임·재고 감축","src":"이론"},{"t":"고객요구의 다양성 증가와 제품수명주기 단축. 채찍효과(정보전달 지연·왜곡) 발생","src":"이론"},{"t":"글로벌화로 공급사슬상 조달기간(리드타임)이 길어지고 불확실. 대량고객화(다품종 소량 생산) 보편화로 긴밀한 협력 필요","src":"이론"},{"t":"기업 내부의 조직·기능별 관리만으로는 경쟁력·부가가치·고객만족 개선이 어려워 통합적 공급사슬관리가 중요","src":"이론"}]},{"머리":"채찍효과 (Bullwhip Effect)","줄":[{"t":"정의: 최종소비자의 수요 정보가 공급자 방향(상류)으로 전달되는 과정에서 수요변동이 증폭되는 현상","src":"기출 2022-38, 2025-30"},{"t":"공급사슬 상류로 갈수록 수요정보가 증폭·왜곡","src":"기출 2024-14, 2025-30"},{"t":"원인: 중복·부정확한 수요예측(구성원의 독립적 수요예측)","src":"기출 2021-28, 2023-32"},{"t":"원인: 결품을 우려한 과다 주문, 공급부족에 따른 과다 주문","src":"기출 2021-28, 2023-32"},{"t":"원인: 로트(lot) 단위 또는 대단위 일괄(batch) 주문, 경제성을 고려한 일괄주문","src":"기출 2021-28, 2023-32, 2025-30"},{"t":"원인: 가격변동(판촉활동·수량할인)과 가격변동에 의한 선행구입, 구매자의 사전구매(Forward Buying)","src":"기출 2021-28, 2023-32, 2025-30"},{"t":"원인: 공급사슬 참여기업 간 정보 왜곡","src":"기출 2022-38"},{"t":"납품주기 단축·납품횟수 증대, 리드타임 단축은 채찍효과의 원인이 아님(완화 방향)","src":"기출 2021-28, 2023-32"},{"t":"완화 방법: 수요정보 공유, 파트너십 구축, 상시저가전략(EDLP)","src":"기출 2022-38, 2025-30"},{"t":"채찍효과: 공급사슬에서 최종 소비자로부터 멀어질수록 정보가 지연·왜곡되어 수요와 재고의 불안정이 확대되는 현상","src":"이론"},{"t":"채찍효과의 결과: 공급사슬 전체 재고 증가, 고객서비스 수준 하락, 생산능력 계획 오류, 수송 비효율, 생산계획 난맥","src":"이론"},{"t":"원인 - 다단계 수요예측(중복 수요예측): 소비자 실수요가 아닌 개별 주체의 발주량에 근거해 수요 예측. 해결: 통합적 수요예측을 위한 정보공유·정보통합","src":"이론"},{"t":"원인 - 공급사슬상 분배의 문제(과잉주문): 수요 폭증 시 유통업체가 품절에 대비해 실수요보다 많이 주문. 해결: 과거 판매·주문실적에 따라 공급량 배정, 리드타임 단축","src":"이론"},{"t":"원인 - 일괄주문 처리방식(Order batching): 일정 수준 판매될 때까지 기다렸다가 한 번에 주문. 해결: 실시간(real-time) 주문처리","src":"이론"},{"t":"원인 - 불규칙한 수요와 가격정책: 할인기간에 많은 물량을 주문해 쌓아두고 이후 추가주문 안 함. 해결: EDLP 정책으로 가격 불확실성·변동성 제거","src":"이론"},{"t":"채찍효과 완화: 공급사슬 정보의 통합·실시간 공유, 실시간 주문처리, 불확실성 제거, 주문량 변동폭 감소, 리드타임 단축. 일괄주문처리(order batching)를 지향하는 것은 해결방안이 아님","src":"이론"}]},{"머리":"SCM의 효과","줄":[{"t":"SCM 효과: 생산자·공급자 간 정보교환이 원활해지고 생산계획 조정·협력이 용이, 공급사슬 전·후방 수요변동성 감소, 재고품절 가능성 감소","src":"기출 2020-29"},{"t":"SCM 파트너십 효과: 경쟁우위 확보, 재고품절 위험 감소, 물류비용 절감, 소비자 만족 극대화","src":"기출 2020-31"}]}],"함정":[{"x":"ABM(Activity Based Management)을 근간으로 하여 각 공급사슬과 접점을 이루는 부문에서 계획을 수립하는 시스템이다.","o":"출제 오답(바른 수치 미확인). SCM의 설명이 아님.","src":"기출 2021-27"},{"x":"물자의 이동이 주로 국내나 역내에서 이루어지고 있다.","o":"글로벌화로 국제 이동이 늘고 있다.","src":"기출 2021-29"},{"x":"구매자의 사전구매(Forward Buying)를 통해 채찍효과를 감소시킬 수 있다.","o":"사전구매는 채찍효과의 원인이다.","src":"기출 2022-38, 2025-30"},{"x":"공급망 하류로 갈수록 정보가 왜곡되는 현상이 심화되고 있다.","o":"공급망 상류로 갈수록 정보 왜곡이 심화된다.","src":"기출 2023-28"},{"x":"글로벌화로 인해 부품공급의 리드타임이 짧아지고 있다.","o":"리드타임이 길어지고 불확실해진다.","src":"기출 2024-14"},{"x":"참여기업들의 개별적 수요 예측을 통해 완화할 수 있다.","o":"개별 예측은 원인. 수요정보 공유·공동 예측으로 완화.","src":"기출 2025-30"},{"x":"VMI(Vendor Managed Inventory)는 소비자가 판매자의 매장 또는 물류센터의 재고를 관리하는 전략을 말한다.","o":"VMI는 공급업체가 구매자(유통업체)의 재고를 관리하는 방식.","src":"기출 2026-31, 2025-28"},{"x":"물류센터 통합으로 인해 리스크 풀링(Risk Pooling)이 사라진다.","o":"물류센터를 통합하면 리스크풀링 효과로 수요 불확실성이 줄어 안전재고가 감소","src":"기출 2020-29"},{"x":"[공급사슬관리(SCM: Supply Chain Management)의 효과] 생산자와 공급자 간의 협력을 통하여 이익 평준화를 실현할 수 있다.","o":"SCM 효과는 경쟁우위 확보·재고품절 위험 감소·물류비 절감·소비자 만족 극대화","src":"기출 2020-31"}]},"#11":{"묶음":[{"머리":"업계별 협업 모델","줄":[{"t":"QR(신속대응): 의류 부문에서 시작. 제조업체와 유통업체가 협력하여 적절한 시기에 적절한 양을 적절한 가격으로 제공","src":"기출 2023-25, 2023-29, 2024-29"},{"t":"ECR(효율적 소비자 대응): 식품 부문에서 시작","src":"기출 2023-25"},{"t":"EHCR: 의약품 부문에서 시작","src":"기출 2023-25"},{"t":"CRP(지속적 보충): 유통업체의 실제 판매 데이터를 토대로 제조업체가 상품을 지속적으로 공급. 별도 주문 없이 지속 보충","src":"기출 2023-29, 2024-29"},{"t":"VMI(공급업체 주도 재고관리): 공급업체가 구매자의 재고를 관리. 수요업체가 정보공유시스템으로 재고 보충 책임을 공급업체에 이전. 부품공급자가 제조업자의 생산계획을 공유하여 제조업자 재고 관리","src":"기출 2025-28, 2024-29"},{"t":"VMI는 유통업체와 제조업체가 공동으로 유통업체의 재고를 관리하는 방식이 아님(공급업체 단독 관리)","src":"기출 2023-29"},{"t":"CPFR(협업적 계획·예측·보충): 거래파트너가 특정시장 목표 사업계획을 공동 수립·공유, 판매·재고 데이터로 수요를 예측해 생산계획에 반영하고 자동 보충","src":"기출 2021-30, 2023-29"},{"t":"ECR: 제품에 대한 고객 반응을 측정해 재고관리·생산효율을 달성하는 방식(선지 형태로 출제)","src":"기출 2023-29"},{"t":"SCM 구성체계: 1단계 SCM → 2단계 산업별 적용(QR·ECR·EFR·EHCR·CRP·CPFR·VMI·CMI·C/D·CALS) → 3단계 구현수단(바코드·POS·RFID·EDI/VAN·XML·LAN·WAN·TMS·WMS·OMS(CAO·EOS)·ERP)","src":"이론"},{"t":"산업별 표현: 섬유·의류 QR, 식품·잡화 ECR, 신선식품 EFR, 의약품 EHCR","src":"이론"},{"t":"QR: 생산·유통업자가 전략적으로 협력해 소비자 선호 등을 즉시 파악하고 시장변화에 신속 대응. 시장에 적합한 제품을 적시·적소에 적절한 가격으로 제공. EDI·바코드·POS 등 유통정보 기술 필요","src":"이론"},{"t":"QR 효과: 제조업자는 주문량에 맞춘 유연생산, 공급자 수 감소, 높은 자산회전율 유지. 상품 품절 방지, 리드타임 단축에 의한 재고감소, 고객정보의 효율적 활용, 고객서비스 제공 및 비용절감, 신속한 물류서비스","src":"이론"},{"t":"ECR: 유통업체와 제조업체가 효율적 소비자 대응 활동으로 고객에게 더 저렴한 가격으로 상품을 제공하고 만족도를 높이기 위해 공급체인을 푸시(Push)에서 풀(Pull) 방식으로 변화시키고 POS 등으로 자동 충원하는 전략","src":"이론"},{"t":"ECR 세부 구현전략: 효율적 매장(점포)진열, 효율적 재고(상품)보충, 효율적 판매촉진, 효율적 신제품 도입(상품개발)·소개","src":"이론"},{"t":"CRP: 공급업자와 소매업자가 POS 정보를 공유해 별도 주문 없이 공급업자가 제품을 보충. 결품비율을 낮추고 협업기능을 강화. 최근 제조업체 사이에서도 도입","src":"이론"},{"t":"CPFR: 유통업체와 공급업체가 함께 비즈니스를 계획(planning)하고 수요를 예측(forecasting)하며 이에 근거해 재고를 보충(replenishment). 도입 선행조건은 거래당사자 간 협업관계(partnership) 구축, 거래파트너가 특정시장을 목표로 사업계획을 공동 수립하고 정보를 공유","src":"이론"},{"t":"VMI: 공급자(제조업체)가 유통업체 재고를 직접 관리하는 공급자주도형 재고관리. POS 판매정보가 실시간 공급업체에 제공되어 판매·생산정보가 동기화","src":"이론"},{"t":"VMI: 구매자가 공급자에게 재고주문권을 부여하고 공급자는 자율적으로 공급 스케줄을 관리. 제조업자는 부품공급자와 생산계획을 공유하고 유통업자로부터 판매정보를 제공받음","src":"이론"},{"t":"CMI(Co-Managed Inventory): VMI에서 한 단계 보완된 것으로 유통업체와 공급업체가 협업으로 공동 재고관리. JMI(Jointly Managed Inventory)라고도 함","src":"이론"},{"t":"CAO(자동발주시스템): 제조업자 창고·유통센터·소매업자 전체 재고를 컴퓨터가 자동주문하게 해 운반·배달계획을 지원하고 물류비용 감소. 재고 효율적 관리와 정확한 수요예측에 도움","src":"이론"},{"t":"EOS: 체인사업에서 상품이 판매되면 POS 데이터가 거래처 중앙본부 컴퓨터에 자동 입력되고, 부족분을 컴퓨터가 거래처에 자동 주문해 해당 점포에 배달","src":"이론"},{"t":"e-Procurement: 인터넷 기반으로 구매 요청·승인·주문·운반·결제 및 인도 프로세스를 전략적으로 관리. 원재료 조달 파트너 선정, e-카탈로그에 의한 물품수량 결정·주문, 전자대금 지불을 실시간 지원. 장점: 운영비용 절감, 조달효율성 개선, 조달가격 절감, 문서처리 비용 감소","src":"이론"}]},{"머리":"크로스도킹·지연전략","줄":[{"t":"크로스도킹(Cross Docking): 입고 상품을 보관하지 않고 곧바로 소매점포에 배송. 공급업체·소매업체 차량이 약속 시간에 도착해 보관작업 없이 이동","src":"기출 2022-39, 2024-30"},{"t":"Postponement(지연): 공통모듈을 먼저 생산하고 주문 접수 후 최종 조립(전원케이블 등). 직조 후 염색(베네통)","src":"기출 2022-37, 2025-26, 2026-30"},{"t":"차별화지연(Delayed Differentiation): 제품 차별화를 최대한 뒤로 미루고 최신 수요정보를 활용해 수요의 불확실성을 감소","src":"기출 2026-31"},{"t":"리스크풀링(Risk Pooling): 공급사슬에 분포된 불확실성을 하나로 모아 시스템 전체의 불확실성을 줄임. 공통모듈 수요는 개별 제품 수요의 합이라 변동이 작아짐","src":"기출 2022-30, 2026-31"},{"t":"크로스도킹: 1980년대 Wal-Mart가 최초 도입. 창고·물류센터에서 수령한 상품을 재고로 보관하지 않고 바로 배송하는 통과형 물류센터","src":"이론"},{"t":"크로스도킹은 EDI·바코드·스캐닝 기술로 자동화된 창고·재고관리를 지원. 물류센터가 보관거점 기능에서 탈피하고 대기시간이 단축되어 고객서비스 개선","src":"이론"},{"t":"크로스도킹 효과: 적재시간·비용 절감, 창고비용 절감, 유통업체 결품률 감소, 입출고 시간·비용 감소. EDI·바코드·RFID 활용 시 더 효과적","src":"이론"},{"t":"지연전략(postponement): 생산 프로세스에서 제품이 서로 차별화되는 시점을 가능한 판매시점에 가깝게 지연. 연기·유예전략이라고도 함. 확정주문 전에는 모듈화된 반제품 상태로 전략거점에 대기, 확정주문 접수 후 고객별 상표 부착·최종 조립","src":"이론"},{"t":"Page & Cooper 전략적 지연: 투기전략(예측에 의해 표준화 제품 생산·시장 가까이 보관), 제조지연전략(특정 제품으로 구체화하지 않고 범용 상태 유지), 물류지연전략(생산된 제품을 전략적 위치에 집중해 재고 유지), 완전지연전략(제조·물류 프로세스를 주문 접수 이후 진행)","src":"이론"},{"t":"Zhang & Tan 전략적 지연: 형태지연(표준품에 고객 요구 기능을 부가), 시간지연(프로세스·제조시점 재구축), 장소지연(제조공정 지리적 위치 재설계)","src":"이론"}]},{"머리":"효율적 공급사슬 vs 대응적 공급사슬","줄":[{"t":"효율적: 비용 절감(리드타임 단축보다), 공급사슬 전반 재고 최소화, 가동률 최대화가 생산운영 전략","src":"기출 2022-36, 2025-29"},{"t":"대응적: 불확실한 수요에 빠르고 유연하게 대응하는 것이 목표","src":"기출 2022-36"},{"t":"모듈화를 통한 제품 유연성·다양성 확보와 공급의 유연성 우선은 대응적 공급사슬의 성격","src":"기출 2022-36, 2025-29"},{"t":"효율적 공급사슬: 제품수명주기가 길어 수요가 안정적·예측가능한 경우 비용절감·효율 운영을 위한 공급사슬. 저비용을 위한 재고 최소화, 높은 가동률","src":"이론"},{"t":"대응적(반응적·혁신적) 공급사슬: 의류처럼 수명주기가 짧고 수요변동성이 큰 경우 시장수요 변화에 민감하고 유연하게 반응. 목표는 재고품절·시즌 말 가격할인 최소화를 위한 예측불가능한 수요에 신속 대응","src":"이론"},{"t":"주요목표: 효율적은 최저 가격으로 예측 가능한 수요에 효율적 공급, 대응적은 예측 불가능한 수요에 신속 대응","src":"이론"},{"t":"제품디자인: 효율적은 비용 최소화·성과 극대화 디자인, 대응적은 제품 차별화를 위한 모듈(module) 디자인","src":"이론"},{"t":"가격전략: 효율적은 저가격·저마진, 대응적은 고가격·고마진. 재고전략: 효율적은 높은 재고회전율·재고 최소화, 대응적은 부품 및 완제품 안전재고 유지","src":"이론"},{"t":"생산전략: 효율적은 높은 가동률, 대응적은 유연한 생산능력. 공급자전략: 효율적은 비용과 품질, 대응적은 속도·유연성·신뢰성·품질","src":"이론"},{"t":"리드타임 초점: 효율적은 비용 증가 없이 단축, 대응적은 비용이 증가하더라도 단축","src":"이론"}]},{"머리":"제약이론 (TOC, Goldratt)","줄":[{"t":"골드랫(E.M. Goldratt)이 제안. 제약을 찾아 집중적으로 개선. 개선 대상에는 자원·부서·인식·환경 등 제약이 되는 모든 것 포함","src":"기출 2025-13"},{"t":"지속적 개선 5단계: 제약자원 식별 → 제약자원 최대 활용 → 비제약자원을 제약자원에 종속화 → 제약자원 개선 → 개선 프로세스 반복","src":"기출 2023-12"},{"t":"DBR: Drum(제약공정의 속도), Buffer, Rope. Rope는 대열의 선두와 가장 느린 사람을 연결, 원자재·부품 재고보충이 공급업체로 전달되도록 정보교환","src":"기출 2024-15, 2022-10"},{"t":"DBR은 공정 간 자재 흐름 관리로 재고를 최소화하고 제조기간을 단축하며 제약공정을 중점 관리","src":"기출 2022-10"},{"t":"Thinking Process: 제약요인 개선으로 목표 달성 해결방안을 도출. 전체 최적화 추구","src":"기출 2022-10"},{"t":"CCPM(Critical Chain Project Management): 프로젝트 단계별 작업을 효과적으로 관리하여 기간을 단축하고 돌발상황에서도 납기수준을 높임","src":"기출 2022-10"},{"t":"산출회계(Throughput Accounting): 제약이론의 회계적 접근. 통계적 품질개선 도구가 아님","src":"기출 2025-13, 2022-10"},{"t":"재고는 판매를 위하여 재화에 투자된 자금으로 정의","src":"기출 2025-13"},{"t":"OPT(Optimized Production Technology): 정의·측정·분석·개선·관리의 DMAIC를 쓰지 않음","src":"기출 2022-10"},{"t":"TOC: 골드랫 박사가 개발한 생산 스케줄링 소프트웨어 OPT(Optimized Production Technology)에서 출발한 경영과학이론","src":"이론"},{"t":"제약요인인 병목공정이 전체 생산성을 결정. 병목의 처리량(Throughput) 증대가 전체 생산성 증대의 핵심","src":"이론"},{"t":"DBR 시스템: 재고를 줄이면서 산출을 증대. 제약공정이 쉬는 일이 없도록 충분한 재공품을 공급","src":"이론"},{"t":"Drum: 전체 생산 프로세스를 병목의 속도에 맞춤. Buffer: 병목 이전 공정이 병목이 쉬지 않도록 버퍼 형성. Rope: 병목 이후 공정이 병목과 속도를 맞추어 흐름이 이어지도록 프로세스 전체를 최적화","src":"이론"},{"t":"TOC 3요소: 스루풋(판매에 의한 현금창출, 매출액에서 직접재료비 차감), 재고투자(판매를 위해 취득한 재화에 투자된 자금), 운영비용(재고를 스루풋으로 전환하는 데 쓰는 일체의 지출)","src":"이론"},{"t":"TOC는 스루풋 증대를 최우선으로 두고 그 다음 재고와 운영비용 감소를 추구","src":"이론"},{"t":"Thinking Process는 시스템 개선과 조직의 제약을 판별하는 도구. 제약요인을 개선해 목표를 달성하는 구체적 해결방안을 도출하며 전체 최적화를 추구","src":"이론"}]},{"머리":"6시그마 (DMAIC)","줄":[{"t":"모토로라에서 처음 도입. 시그마(σ)는 표준편차. 대표 방법론 DMAIC","src":"기출 2024-16"},{"t":"2시그마 수준은 3시그마 수준보다 불량률이 큼. 6시그마 수준은 3.4PPM","src":"기출 2024-16, 보충"},{"t":"Define(정의) → Measure(측정) → Analyze(분석) → Improve(개선) → Control(관리)","src":"기출 2021-13, 2023-13, 2026-17"},{"t":"Measure: 프로세스의 현재 상태를 파악. 통계기법으로 현재 프로세스 능력을 계량화, CTQ 충족 정도 평가. 적절한 프로세스 측정방법 확인","src":"기출 2023-13, 2025-12, 2026-17"},{"t":"Analyze: 현재 수준과 목표 수준의 차이 원인 규명, 품질을 저하시키는 근본 원인 발견. 파레토도·특성요인도 활용","src":"기출 2021-13, 2025-12"},{"t":"Improve: 품질 개선 활동을 실행하고 결과를 수치화","src":"기출 2025-12"},{"t":"Control: 개선 결과를 문서화하고 개선된 프로세스가 유지되도록 통제. 점검계획 수립·실행, 지속방법 모색 및 절차 제도화","src":"기출 2025-12, 2026-17"},{"t":"새로운 품질 개선 아이디어를 환류(Feedback)하는 단계는 PDCA의 Act(Do는 실행 단계)","src":"기출 2025-12, 보충"},{"t":"6시그마: 제품 설계·제조·서비스의 품질편차를 최소화해 상한·하한이 품질 중심으로부터 6σ 이내에 들게 하는 것. 품질규격을 벗어날 확률은 100만 개 중 3.4개(3.4PPM=3.4DPM) 수준","src":"이론"},{"t":"DPMO(Defect Per Million Opportunity): 제품 백만 개당 결함의 수","src":"이론"},{"t":"6시그마 활용 시 제품·서비스의 리드타임 단축, 재고감축, 비용절감 효과","src":"이론"},{"t":"Define(정의): 고객 요구사항과 품질 중요 영향요인(CTQ)을 인지하고 개선할 프로세스를 선정","src":"이론"},{"t":"Measure(측정): CTQ에 영향을 미치는 프로세스에서 발생하는 결함을 측정","src":"이론"},{"t":"Analyze(분석): 결함의 형태·발생원인을 조사해 직접적·잠재적 변동원인을 파악","src":"이론"},{"t":"Improve(개선): 결함의 원인을 제거해 문제나 프로세스를 개선","src":"이론"},{"t":"Control(통제): 개선효과를 분석하고 개선 프로세스의 지속방법을 모색","src":"이론"}]},{"머리":"공급사슬 성과 관점","줄":[{"t":"공급사슬 성과지표(Cash-to-Cash, 배송성과, 주문충족 리드타임, 생산유연성)","src":"기출 2023-24"},{"t":"BSC는 과거지향적·재무적 관점에 국한된 기존 기준을 고객·내부 프로세스·학습과 성장 관점으로 확대. 성과측정·전략적 경영관리·의사소통의 도구","src":"이론"},{"t":"SCOR: 공급사슬 프로세스 전 범위와 단계를 포괄하는 참조모델. 회사 내부 기능과 공급사슬 파트너 간 의사소통의 공통 언어","src":"이론"},{"t":"SCOR 5대 기본관리 프로세스: 계획(Plan), 조달(Source), 제조(Make), 배송(Deliver), 반품(Return)","src":"이론"},{"t":"SCOR 지표 - 계획: 수요예측 정확도, 계획달성률, 재고회전율, 계획사이클 타임. 조달: 조달·구매비용, 리드타임, 원부자재 품질·재고수준","src":"이론"},{"t":"SCOR 지표 - 제조: 생산원가(효율적 공급사슬), 제품품질, 생산의 유연성(대응적 공급사슬). 배송/반품: 정시 배송률, 주문 충족률 및 배송시간, 공급사슬 대응시간, 인도 성과, 서비스 달성률","src":"이론"},{"t":"린 공급사슬(=JIT II): 프로세스 개선으로 낭비를 제거하고 평준화된 일정계획의 대량생산으로 비용 절감·생산성 향상. 상품 다양성이 낮고 수요 변동성이 낮은 편의품에 적합","src":"이론"},{"t":"린 공급사슬의 7가지 낭비: 수요예측 미비로 인한 과잉생산, 대기시간, 운반시간, 불필요한 생산 과정, 불필요한 재고, 불필요한 행동, 불량품 생산","src":"이론"},{"t":"민첩 공급사슬(Agile): 소규모 인원이 신속하게 제품을 개발·업데이트해 변동성 큰 수요에 대응. 상품 다양성이 크고 수명주기가 짧고 수요 변동성이 높으며 고객 요구가 다양한 제품에 적합","src":"이론"},{"t":"e-SCM: 인터넷 기반으로 원자재 공급·생산·수배송·유통판매·고객관리 등 물류활동 전체를 e-비즈니스 환경에서 통합 관리. 효과적 운영에 ERP·CRM 지원 필요","src":"이론"},{"t":"e-SCM 효과: 공급자-구매자 신속한 의사소통으로 리드타임 단축, 거래비용 감소, 수평적 사업기회 확대, 실시간 재고관리로 안전재고 적정 유지, 핵심정보 피드백 원활, 맞춤서비스, 수직적 상하관계에서 수평적 협력관계로 변화","src":"이론"},{"t":"물류서비스 신뢰성 향상 방안: 신속·정확한 수주정보 처리, 조달 리드타임 단축, 제품 가용성 정보 제공, 재고관리 정확도 향상","src":"이론"}]},{"머리":"TQM","줄":[{"t":"TQM(전사적 품질경영): 경영자가 소비자 지향적 품질방침을 세우고 최고경영진과 모든 종업원이 전사적으로 참여해 품질향상을 추구하는 활동","src":"이론"},{"t":"TQM 원칙: 고객만족, 지속적 공정개선, 팀워크와 참여의식, 과정지향, CEO의 솔선수범","src":"이론"}]},{"머리":"린 생산·대량고객화·BPR","줄":[{"t":"린 생산시스템(Lean): 일본에서 개발된 JIT를 미국 환경에 맞게 재정립한 생산시스템. lean은 얇은·마른의 뜻으로 어떤 유형의 낭비도 철저히 제거. 고객관점의 가치창조를 위해 전체 프로세스 흐름 최적화에 중점","src":"이론"},{"t":"BPR: 마이클 해머가 주장. 기존 조직·업무체계를 근본부터 재설계해 모든 경영활동을 프로세스 중심으로 재편. 최고경영층 주도와 구성원 공감대가 성공 전제조건. 정보기술을 창의적으로 활용","src":"이론"},{"t":"대량고객화(Mass Customization): 비용·효율성·효과성을 희생하지 않고 개별 고객 욕구를 파악·충족하는 전략. 대량생산의 비용절감과 차별화 전략의 장점을 합친 다품종 대량생산 추구","src":"이론"}]},{"머리":"리스크풀링","줄":[{"t":"리스크풀링: 여러 지역의 수요를 한 곳에서 통합 관리하면 수요 불확실성이 상대적으로 감소. 분산된 물류거점을 통합하면 적은 재고로 불확실성에 대응. 안전재고가 감소하고 물류비 절감","src":"이론"},{"t":"안전재고는 수요의 표준편차에 비례. 통합 표준편차 = √(σ₁² + σ₂² + …)","src":"이론"},{"t":"예: 센터 2개, 일평균수요 100·표준편차 10 → (100+10)×2 = 220개. 통합 시 수요 200 + 안전재고 √(10²+10²) ≈ 14 → 214개. 효과 6개","src":"이론"}]},{"머리":"글로벌 가치사슬과 SCM 정보시스템","줄":[{"t":"글로벌 가치사슬: 제품의 기획·생산·조립·마케팅·고객서비스 등 부가가치 창출 활동이 전 세계적 차원에서 이루어지는 것. 활동을 최적 분배해 생산성 향상","src":"이론"},{"t":"글로벌 가치사슬에서 개별국가 법적 규제나 리더기업의 제품·프로세스 기준이 기술무역장벽으로 작용할 수 있음. 발전배경: WTO 체제 발족, 운송기술 발전, ICT 발전 및 표준 확산","src":"이론"},{"t":"SCP(공급사슬계획): 의사결정·계획수립 지원. 수요예측, 생산계획, 생산일정계획, 재고보충계획. CPFR, APS(협력업체와 생산계획 공유), DRP(유통기관 수요배분) 등","src":"이론"},{"t":"SCE(공급사슬실행): 주문처리·SCM 통합 실행·관리. OMS·WMS·TMS 등. 공급자·수배송업체 선정, 재고수준 결정, 채널 간 정보공유 등 담당","src":"이론"},{"t":"SCP: 수요계획·생산계획·재고계획·재고보충계획·스케줄링. SCE: 주문관리(OMS)·창고관리(WMS)·운송관리(TMS)·공급자 및 배송업체 선정·재고수준 및 채널 간 정보공유 수준","src":"이론"},{"t":"SRM: 공급자와 구매기업의 비즈니스 프로세스를 통합해 모든 공급자와 장기적 협업관계 형성을 목표. 정보·프로세스 흐름 가시화 수준 향상, 거래 프로세스 자동화, 고객중심 대안을 신속 제공해 시장변화 대응력 향상","src":"이론"},{"t":"CRM: 기존 우수고객 유지·이탈방지로 장기적 관계구축이 목적. 고객관계 형성 → 유지 → 강화 단계. 고객 평생가치를 높이는 분석 필요. 고객을 분류해 차별화된 제품·서비스 제공","src":"이론"}]}],"함정":[{"x":"Drum, Buffer, Rope는 공정간 자재의 흐름 관리를 통해 재고를 최소화하고 제조 기간을 단축하는 기법으로서 비제약공정을 중점적으로 관리한다.","o":"제약공정을 중점 관리한다.","src":"기출 2022-10"},{"x":"Thinking Process는 제약요인을 개선하여 목표를 달성하는 구체적 해결방안을 도출하는 기법으로서 부분 최적화를 추구한다.","o":"전체 최적화를 추구한다.","src":"기출 2022-10"},{"x":"Throughput Account는 통계적 기법을 활용한 품질개선 도구이다.","o":"산출회계는 제약이론의 회계 기법이고, 통계적 품질개선 도구는 6시그마.","src":"기출 2022-10, 2025-13"},{"x":"Optimized Production Technology는 정의, 측정, 분석, 개선, 관리의 DMAIC 프로세스를 활용한다.","o":"DMAIC는 6시그마.","src":"기출 2022-10"},{"x":"6시그마 수준은 불량률 4.3 PPM을 의미한다.","o":"6시그마 수준은 3.4PPM(보충).","src":"기출 2024-16, 보충"},{"x":"Do는 새로운 품질 개선 아이디어를 환류(Feedback)하는 단계이다.","o":"환류 단계는 Act. Do는 실행.","src":"기출 2025-12"},{"x":"효율적 공급사슬은 모듈화를 통한 제품 유연성 확보에 초점을 둔다.","o":"모듈화·유연성 확보는 대응적 공급사슬.","src":"기출 2022-36, 2025-29"},{"x":"대응적 공급사슬은 리드타임 단축보다 비용최소화에 초점을 둔다.","o":"대응적은 리드타임 단축에 초점. 비용최소화는 효율적.","src":"기출 2022-36"},{"x":"공급자 선정과정에서 비용보다는 공급의 유연성을 우선적으로 고려한다. (효율적 공급사슬)","o":"효율적은 비용을 우선. 유연성 우선은 대응적.","src":"기출 2025-29"},{"x":"VMI(Vendor-Managed Inventory): 유통업체와 제조업체가 실시간 정보공유를 통해 공동으로 유통업체의 재고를 관리하는 방식","o":"VMI는 공급업체가 구매자 재고를 관리.","src":"기출 2023-29"},{"x":"[공급자 재고관리(VMI: Vendor Managed Inventory)] 생산자와 부품공급자는 신제품을 공동 개발한다.","o":"VMI는 공급자가 구매자 재고를 관리하는 방식. 제조업자는 부품공급자와 생산계획을 공유하고 유통업자로부터 판매정보를 제공받음","src":"기출 2020-30"}]},"#12":{"묶음":[{"머리":"3자물류 정의","줄":[{"t":"제3자물류: 화주가 대통령령으로 정하는 특수관계에 있지 아니한 물류기업에 물류활동의 일부 또는 전부를 위탁하는 것","src":"물류정책기본법 제2조 제1항 제10호"},{"t":"3자물류: 화주와 물류업체 간 전략적·장기적 협력관계. 운송·보관 포함 물류 프로세스 대부분을 수행","src":"기출 2025-11"}]},{"머리":"4자물류(4PL)","줄":[{"t":"3PL, 물류컨설팅 업체, IT 업체 등이 결합한 형태. 3자물류에 IT·기술·전략적 컨설팅 추가","src":"기출 2021-11, 2022-25, 2023-35, 2024-10, 2025-11, 2026-12"},{"t":"공급사슬 전체의 관리·운영 대상. 포괄적 SCM 서비스를 위한 통합서비스로 공급사슬 전반 최적화","src":"기출 2021-11, 2023-35, 2024-10, 2026-12"},{"t":"합작투자 또는 장기 제휴 형태. 참여 업체 공통의 목표설정과 이익분배","src":"기출 2021-11, 2022-25, 2023-35, 2024-10"},{"t":"다양한 기업이 파트너로 참여하는 혼합조직","src":"기출 2021-11, 2023-35"},{"t":"목적: 수입증대, 운영비용 감소, 운전자본 감소, 고정자본 감소. 사이클 타임 단축","src":"기출 2024-10, 2022-25"},{"t":"기존 물류업체의 한계를 극복하고 지속적 개선효과 창출","src":"기출 2024-10"},{"t":"기능별 서비스와 상하계약관계는 4PL의 특징이 아님","src":"기출 2021-11"},{"t":"모회사 유휴인력의 물류자회사 파견은 4PL의 특징이 아님","src":"기출 2026-12"},{"t":"4PL: 물류 기본기능과 함께 전자상거래 발전으로 3PL 기업이 공급체인 해결책을 제시하고 변화·관리능력과 전략적 컨설팅까지 포함하는 물류영역","src":"이론"},{"t":"4PL 서비스 제공자는 공급사슬 전체를 관리·운영하며 다양한 기업을 파트너(설비투자)로 참여시킴. 참여업체는 이익분배를 통해 공통 목표를 설정·관리(수입공개·운영비용 및 고정자본 감소 효과)","src":"이론"},{"t":"조직 형태: 3PL이 물류컨설팅업체·IT기업 등과 네트워크로 연계된 네트워크형 물류조직. 아웃소싱과 인소싱의 장점을 통합한 형태","src":"이론"},{"t":"4PL 유형 - 시너지플러스: 복수의 화주에게 물류서비스를 제공하는 서비스제공업체의 브레인 역할","src":"이론"},{"t":"4PL 유형 - 솔루션통합자: 복수의 서비스 제공업체(3PL·SI업체·컨설팅사 등)를 통합해 화주에게 물류서비스 제공","src":"이론"},{"t":"4PL 유형 - 거래파트너: 화주와 서비스 제공자 간 조정·통제 역할, 공급망 설계 및 계획 서비스 제공","src":"이론"},{"t":"4PL 유형 - 산업혁신자: 복수의 서비스 제공업체를 통합하고 동일 산업군에 대한 통합서비스를 제공해 시너지 극대화","src":"이론"},{"t":"4PL의 대표적 형태는 네트워크형 조직(매트릭스형 물류조직이 아님)","src":"이론"},{"t":"4PL: 3PL·물류컨설팅업체·IT업체 등이 결합한 형태. 이익분배를 통해 공통 목표를 관리하며 공급사슬 전체의 관리·운영을 실시","src":"기출 2020-12"}]},{"머리":"외주물류(아웃소싱)와 3자물류 비교","줄":[{"t":"외주물류: 운영 측면 원가절감 목표, 기능별 서비스(수송·보관) 수행, 단기적 관계, 중간관리층 의사결정·수의계약 중심","src":"기출 2023-30, 2026-13"},{"t":"3자물류: 원가절감과 경쟁우위·물류전략 지원·고객서비스 향상, 종합물류 지향, 중장기 협력, 최고경영층 의사결정·경쟁계약 중심","src":"기출 2023-30, 2026-13"},{"t":"외주물류는 수동적 서비스, 3자물류는 능동적·적극적 서비스","src":"기출 2026-13"},{"t":"아웃소싱: 화주와 물류기업 간 효과적 관계를 구축해 조직 간소화·적응력·유연성을 강화하는 혁신기법. 한정된 자원을 핵심사업에 집중하고 나머지(운송·보관·포장·하역 등)는 외부 전문기업에 위탁해 효율 극대화. 화주는 아웃소싱 이전에 자사 물류비 현황을 정확히 파악해야 함","src":"이론"},{"t":"물류아웃소싱은 주문 수·발주나 재고관리 등 일부만 대행하는 것이 아니라 물류센터 관리·물류정보시스템·수출입 업무·수배송 전 분야를 대행. 계약조건을 협상으로 확정하므로 외주 물류기능 계약범위 내에서만 화주 통제 가능","src":"이론"},{"t":"3PL: 일반적으로 물류아웃소싱과 동일시되나 구체적으로는 아웃소싱보다 포괄적·종합적 서비스를 제공","src":"이론"},{"t":"물류정책기본법 제37조: 국토교통부장관은 해양수산부장관·산업통상자원부장관과 협의해 화주기업과 물류기업의 제3자물류 촉진 시책을 수립·시행·지원하여야 함","src":"이론"},{"t":"외주물류(아웃소싱)와 3PL 비교 - 기간·관계: 단기·일시적 / 중·장기 협력관계. 전략 수준: 주로 운영수준 / 운영·관리·전략","src":"이론"},{"t":"외주물류와 3PL 비교 - 계약방식: 수의계약 / 경쟁계약. 의사결정점: 중간관리층 / 최고경영층. 관리형태: 분산관리형 / 통합관리형","src":"이론"},{"t":"외주물류와 3PL 비교 - 화주와 관계: 수직적 계약 / 협력관계·전략적 제휴. 서비스 범위: 기능별 서비스(운송·보관·하역 등) / 종합물류서비스","src":"이론"}]},{"머리":"아웃소싱의 장단점","줄":[{"t":"제조업체 단점: 고객 불만에 신속한 대처가 어렵다. 물류정보 유출 가능. 내부 전문가 상실과 사내 전문지식 축적 곤란","src":"기출 2024-12, 2025-11"},{"t":"제조업체 장점: 물류거점 자본투입 최소화, 전문 물류업체 인프라의 전략적 활용","src":"기출 2024-12"},{"t":"물류업체 장점: 규모의 경제를 통한 효율 증대","src":"기출 2024-12"},{"t":"아웃소싱 전반적 장점: 물류비용 절감·리드타임 단축으로 고객서비스 향상, 유연성 있는 고용형태와 급여체계","src":"이론"},{"t":"화주 측 장점: 물류설비 등 막대한 자본투자비용 절감, 핵심역량 집중으로 기업경쟁력 제고","src":"이론"},{"t":"물류기업 측 장점: 규모의 경제를 통한 물류 효율 증대, 전문성·유연성에 의한 고객서비스 향상","src":"이론"},{"t":"단점: 화주가 구체적으로 직접 지휘·통제하기 어려움(통제력 낮음), 고객불만 신속 대처 저하, 핵심정보 유출 가능성, 사내 물류전문지식 축적 어려움, 물류업체의 서비스 질이 기대에 미치지 못할 수 있음","src":"이론"},{"t":"제2자물류(2PL, 물류자회사): 화주기업이 사내 물류조직을 별도 법인으로 분리해 자회사로 독립. 모회사의 물류전략을 잘 이해·실천하는 자회사로 전체 비용을 낮추면서 효과적 서비스 제공. 물류시설·인원·장비를 자회사 소속으로 분리하면 물류관리 책임·물류비 관리의 명확화 실현","src":"이론"},{"t":"성공적 아웃소싱 조건: 화주·물류기업 간 수평적 협력(지휘·통제의 종속관계 탈피), 세부적 물류목표 설정, 표준화된 채널로 지속 의사소통, 충분한 시간을 두고 업체 선정, 업체를 단순 공급업체가 아닌 파트너로 인정","src":"이론"}]}],"함정":[{"x":"수입증대, 운영비용 감소, 운전자본 확대, 고정자본 확대를 목적으로 한다. (4PL)","o":"운전자본·고정자본은 감소를 목적으로 한다.","src":"기출 2024-10"},{"x":"사이클 타임과 운전자본의 증대 (4PL)","o":"사이클 타임과 운전자본의 감소.","src":"기출 2022-25"},{"x":"기업과 고객 간의 거래(B2C) 보다는 기업과 기업 간의 거래(B2B)에 집중한다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-35"},{"x":"제조업체는 물류거점에 대한 자본투입을 최대화하고 전문 물류업체의 인프라를 전략적으로 활용할 수 있다.","o":"자본투입을 최소화한다.","src":"기출 2024-12"},{"x":"자가물류 방식에 비해 화주의 정보 유출 우려가 적다.","o":"3PL은 정보 유출 우려가 있다.","src":"기출 2025-11"},{"x":"4PL: 기능별 서비스와 상하계약관계","o":"4PL은 공동 목표·이익분배·장기 제휴이며 기능별 서비스·상하계약은 3PL 성격.","src":"기출 2021-11"},{"x":"외주물류는 중장기적 협력 관계를 기반으로 이루어지는 반면, 3자물류는 단기적 관계를 기반으로 운영된다.","o":"외주물류는 단기적, 3자물류는 중장기적 관계.","src":"기출 2023-30, 2026-13"},{"x":"외주물류는 주로 최고경영층의 의사결정에 따라 경쟁계약의 형태로 진행되는 반면, 3자물류는 중간관리층의 의사결정에 따라 수의계약 형태로 주로 진행된다.","o":"외주물류가 중간관리층·수의계약, 3자물류가 최고경영층·경쟁계약.","src":"기출 2023-30"},{"x":"외주물류는 주로 능동적·적극적으로 서비스를 제공하는 반면, 3자물류는 주로 수동적 서비스를 제공한다.","o":"외주물류가 수동적, 3자물류가 능동적.","src":"기출 2026-13"},{"x":"서비스 범위 측면에서 외주물류는 종합물류 서비스를 지향하는 반면, 3자물류는 기능별 서비스를 지향한다.","o":"외주물류가 기능별, 3자물류가 종합물류.","src":"기출 2026-13"},{"x":"4PL의 대표적인 형태는 매트릭스형 물류조직이다.","o":"4PL은 3PL·컨설팅·IT업체가 네트워크로 연계된 네트워크형 물류조직","src":"기출 2020-12"}]},"#13":{"묶음":[{"머리":"수요예측 기법","줄":[{"t":"지수평활법: 단기 수요예측에 유용, 최근 수요에 많은 가중치. 오랜 기간 실적이 필요 없고 데이터 처리 시간이 적음","src":"기출 2022-23"},{"t":"회귀분석법(인과형): 수요에 영향을 미치는 독립변수를 파악하고 독립변수와 종속변수 간 함수관계를 통계적으로 추정해 미래 수요를 예측","src":"기출 2023-8"},{"t":"패널조사법(패널동의법): 다수의 의견이 소수보다 우월하다는 전제로 경영자·생산자·소비자·판매자 등이 참여하는 위원회에서 자유로운 의견으로 수요 예측","src":"기출 2026-15"},{"t":"정성적 기법 보기: 시장조사법, 델파이법, 판매원이용법, 패널조사법, 역사적 자료 유추법, 수명주기예측법","src":"기출 2022-23, 2026-15, 2023-8"},{"t":"정량적 기법 보기: 지수평활법, 가중이동평균법, 회귀분석법","src":"기출 2023-8, 2022-23"},{"t":"델파이법: 전문가들의 익명 설문을 반복해 의견을 수렴하는 정성적 기법","src":"보충"},{"t":"수요예측: 장·단기 계획 수립의 기초자료. 물류시설계획·생산계획·재고관리 등 물류운용계획 의사결정에 필수","src":"이론"},{"t":"수요예측기법: 정성적 기법과 정량적 기법. 정량적 기법은 인과형 모형과 시계열분석으로 나뉨","src":"이론"},{"t":"델파이법: 전문가 집단에 여러 차례 설문지를 돌려 의견 수렴. 시간·비용이 많이 들지만 과거 자료가 없거나 불확실성이 큰 경우, 장기예측·기술예측에 적합(생산능력·설비계획·신제품개발·시장전략)","src":"이론"},{"t":"전문가의견법: 경험 많은 전문가들이 자유롭게 의견을 교환해 일치된 결과를 얻음. 단기간·저비용","src":"이론"},{"t":"시장조사법: 설문지·인터뷰·전화 조사로 소비자 의견 조사. 가장 시간·비용이 많이 들지만 비교적 정확","src":"이론"},{"t":"수명주기 유추법: 신제품과 비슷한 기존 제품의 수명주기 단계별 수요변화 자료로 수요 변화를 유추","src":"이론"},{"t":"인과형 모형: 수요와 밀접한 독립변수를 찾아 인과관계를 분석해 미래수요 예측. 회귀분석·계량경제모형·투입-산출모형·시뮬레이션모형","src":"이론"},{"t":"시계열분석: 과거 관측 패턴으로 미래수요 예측. 변동요인은 추세적·계절적·순환적·불규칙 변동. 이동평균법·지수평활법 등, 중·단기예측에 많이 사용","src":"이론"},{"t":"단순이동평균법: 최근 몇 기간 관측치의 평균을 다음 기간 예측치로 사용","src":"이론"},{"t":"가중이동평균법: 최근 값에 가중치를 더 주어 예측치로 사용","src":"이론"},{"t":"지수평활법: 최근 값에 가장 큰 가중치를 주고 오래된 자료일수록 가중치를 지수적으로 감소. 단기 예측에 유용","src":"이론"},{"t":"계산 - 지수평활: 다음기 예측치 = α × 전기 실제치 + (1 − α) × 전기 예측치 = 전기 예측치 + (전기 실제치 − 전기 예측치) × α","src":"이론"},{"t":"풀이 순서(이동평균·가중이동평균·지수평활): 이동기간만큼 최근 실제치 확인 → 이동평균은 단순 평균, 가중이동평균은 최근월부터 가중치 곱해 합산, 지수평활은 α 대입","src":"이론"},{"t":"예: 실제 40·43·42, 3월 예측 45, 이동기간 3 → 이동평균 (40+43+42)÷3 ≈ 41.7. 가중치 0.5·0.3·0.2 → 0.5×42+0.3×43+0.2×40 = 41.9. α=0.8 → 0.8×42+0.2×45 = 42.6","src":"이론"}]},{"머리":"브레인스토밍 진행원칙","줄":[{"t":"자유분방, 비판금지, 의견편승(타인 의견 결합·발전), 전원참여. 질보다 양","src":"기출 2026-14, 보충"}]},{"머리":"자재관리 시스템","줄":[{"t":"MRP(자재소요계획): 주일정계획(MPS) 수립 후 작업완료일로부터 역산하여 일정 산출. MRP-II로 확장되고 ERP로 발전","src":"기출 2026-22, 2024-22"},{"t":"JIT: 최소 재고유지를 통한 낭비제거 목표의 적시생산시스템. 칸반(Kanban) 시스템으로도 불림. 도요타 개발","src":"기출 2024-22, 2026-22"},{"t":"JIT-II: Bose사가 개발. 공급회사 영업과 발주회사 구매를 묶어 하나의 가상기업으로 간주, 공급회사 전문요원이 구매·납품 업무 대행","src":"기출 2022-14, 2024-22"},{"t":"MRP는 도요타가 개발한 시스템이 아님. JIT-II도 도요타가 개발한 것이 아님","src":"기출 2026-22, 2024-22"},{"t":"JIT: 필요한 시기에 필요한 수량만큼 자재를 조달해 낭비적 요소를 근본적으로 제거하려는 무재고 생산시스템. 1950년대 도요타에서 개발","src":"이론"},{"t":"JIT 목표: 재고·제조준비시간·리드타임·불량품·자재취급노력 등 낭비요인 경감","src":"이론"},{"t":"JIT 구성요소: 소규모 lot 생산과 제조준비시간 단축, 생산의 평준화(Heijunka), 작업자의 다기능화, 칸반시스템 운용, 단일 또는 소수 공급자와의 장기 협력관계, 품질관리활동(품질분임조·안돈·카이젠·포카요케)","src":"이론"},{"t":"안돈: 품질문제 발생 시 경고시스템. 카이젠: 지속적 개선 활동. 포카요케: 실수방지 장치","src":"이론"},{"t":"JIT는 요구(주문)에 따라가는 Pull 시스템, MRP는 계획대로 추진하는 Push 시스템","src":"이론"},{"t":"관리목표: JIT는 낭비제거(무재고), MRP는 계획과 통제(필요시 확보). 관리도구: JIT는 눈으로 보는 관리(칸반), MRP는 컴퓨터 처리","src":"이론"},{"t":"생산계획: JIT는 안정된 MPS 필요, MRP는 변경이 잦은 MPS 적용 가능. 자재소요판단: JIT는 칸반, MRP는 자재소요계획","src":"이론"},{"t":"발주로트: JIT는 소로트(small lot), MRP는 경제적 주문량. 재고 관점: JIT는 부채, MRP는 자산","src":"이론"},{"t":"JIT-II: 보스(Bose)사 총책임자 랜스 딕슨이 최초 도입. 제품원가 중 조달물류비 비중 증가 문제를 해결하려고 탄생. Pull 시스템이나 장기 계약관계가 아닌 상호 파트너십 관계를 전제. 공급회사 판매업무와 발주회사 조달업무를 연결한 가상기업(virtual company)을 가정","src":"이론"}]},{"머리":"계산: EOQ·재고 (공식)","줄":[{"t":"EOQ = √(2 × 연간수요 × 1회 주문비 ÷ 단위당 연간 재고유지비). 풀이 순서: D, S, H 확인 → 대입 → 제곱근","src":"보충"},{"t":"연간 총비용 = 주문비(D÷Q×S) + 재고유지비(Q÷2×H). EOQ에서 두 비용이 같음","src":"보충"}]},{"머리":"재고관리와 재주문점","줄":[{"t":"재고: 현재 사용되지 않고 보유 중인 여유자원. 수요에 적시에 대응하는 최적 재고(Right Quantity) 관리가 중요","src":"이론"},{"t":"재고관리 목적: 자재수급의 불규칙 변동에 대비해 결품 방지, 생산·판매를 원활히 해 시장 안정 유지, 주문비·재고유지비·재고부족 기회비용 최소화","src":"이론"},{"t":"재고유지비: 적정재고 유지에 필연적으로 드는 변동비용. 보관료·보험료·감가상각비·제세공과·이자비용","src":"이론"},{"t":"주문비(발주비): 재고를 보충하려 주문할 때 드는 비용. 하역·수송·검사 등","src":"이론"},{"t":"재고부족비: 결품 시 발생하는 기회비용 성격의 손실비용. 판매기회비용, 생산 차질로 인한 신용도 하락 등","src":"이론"},{"t":"계산 - 재주문점(ROP) = 리드타임 동안의 평균수요량 + 안전재고량","src":"이론"},{"t":"계산 - 리드타임 동안 평균수요량 = 일평균수요 × 조달기간. 안전재고량 = 안전계수 × 수요의 표준편차 × √조달기간","src":"이론"},{"t":"풀이 순서(ROP): 일평균수요 × 조달기간 → 안전계수(서비스수준에서 결정) × 표준편차 × √조달기간 → 두 값을 더함","src":"이론"},{"t":"재고관리기법 발전 순서: MRP(자재소요계획) → MRP II(생산자원계획) → ERP(전사적 자원관리)","src":"이론"},{"t":"MRP: 제품 생산수량·일정을 토대로 원자재·부품의 소요량과 소요시기를 역산해 조달계획·일정관리를 수행하는 재고관리법","src":"이론"},{"t":"MRP 목적: 최종제품의 독립적 수요를 추정하고 이에 따라 구성부품의 종속적 수요(dependent demand)를 적시·적량·적소에 공급해 재고 과잉·부족을 해결하고 재고비용 극소화","src":"이론"},{"t":"MRP II(생산자원계획): 원자재뿐 아니라 생산에 필요한 모든 자원을 관리하는 재고통제시스템. MRP가 확대된 개념","src":"이론"},{"t":"ERP: 인사·재무·생산 등 독립 운영되던 정보시스템을 하나로 통합해 인적·물적 자원 활용도를 극대화하는 경영혁신기법","src":"이론"},{"t":"DRP(유통자원계획): 고객과 가장 가까운 곳에서 수요데이터를 얻어 수요를 예측하고 생산계획에 빠르게 반영. 완제품 출고 이후 소매점·도매점에 이르는 유통망 재고를 줄이는 것이 목적","src":"이론"}]},{"머리":"계산: 안전재고 통합(리스크풀링)","줄":[{"t":"공식: 센터 n개를 1개로 통합하면 통합 안전재고 = 개별 안전재고 × √n (각 센터 수요가 독립적이고 표준편차가 같을 때, 안전재고 = z×σ에 비례)","src":"이론"},{"t":"풀이 순서: 개별 센터의 σ에 비례하는 안전재고 확인 → 통합 σ = √(σ² × n) = σ√n → z는 그대로이므로 안전재고도 √n배","src":"이론"},{"t":"예: 센터 4개, 센터당 안전재고 100 → 통합 안전재고 100 × √4 = 200. 분산 운영 시 합계 400","src":"이론"}]}],"함정":[{"x":"양보다 질 (브레인스토밍 진행원칙)","o":"질보다 양을 중시한다.","src":"기출 2026-14"},{"x":"JIT-II는 일본 도요타 자동차가 개발한 시스템이다.","o":"JIT-II는 Bose사가 개발.","src":"기출 2024-22"},{"x":"MRP는 일본 도요타 자동차가 개발한 시스템이다.","o":"도요타가 개발한 것은 JIT.","src":"기출 2026-22"}]},"#14":{"묶음":[{"머리":"마케팅과 물류","줄":[{"t":"마케팅믹스(4P): 제품(Product)·가격(Price)·유통(Place)·촉진(Promotion)","src":"기출 2024-8, 2026-8"},{"t":"물류는 4P 중 유통(Place, 유통채널)과 관련이 깊음","src":"기출 2023-9, 2024-8, 2025-6"},{"t":"물류역량이 강한 기업일수록 수요의 창출·조절에 유리","src":"기출 2023-9, 2026-8"},{"t":"물류는 마케팅뿐 아니라 생산관리 측면까지 확대. 포괄적 마케팅에 포함되며 물류 자체의 마케팅 활동도 가능","src":"기출 2023-9"},{"t":"물류관리는 마케팅믹스와 통합적 관점에서 추진","src":"기출 2026-8"},{"t":"마케팅은 고객 욕구 충족을 목표로 한 고객만족의 실현이 주요 목표","src":"기출 2026-8"},{"t":"탁월한 고객서비스를 제공하는 마케팅은 고객만족을 증대","src":"기출 2024-8"},{"t":"물류와 영업 업무를 각각 전담부서가 수행하면 전문화로 핵심역량 강화. 공동화·통합화·대량화에 의한 규모의 경제로 물류비 절감, 차량 적재효율 향상, 대규모 물류시설 기계화·자동화","src":"기출 2023-10"},{"t":"마케팅: 개인과 조직의 목적을 충족시키는 교환을 창출하기 위해 아이디어·제품 및 서비스·가격결정·촉진·유통을 계획하고 실행하는 과정","src":"이론"},{"t":"마케팅 기능: 교환기능(구매·판매), 물적유통기능(운송·보관), 조성기능(표준화·금융·정보제공·위험부담)","src":"이론"},{"t":"기술혁신으로 품질과 가격이 평준화되면 고객서비스가 마케팅과 물류에서 중요한 비중을 차지","src":"이론"},{"t":"생산과 물류의 상호작용 요소: 공장입지, 구매계획, 제품생산계획","src":"이론"},{"t":"물류는 마케팅뿐 아니라 생산관리·산업공학적·무역학적 측면까지 광범위한 개념으로 확대","src":"이론"}]},{"머리":"유통경로 시스템","줄":[{"t":"전통적 유통경로: 자체적으로 마케팅 기능을 수행하는 독립적 단위로 구성. 구성원 간 결속력은 약하나 유연성이 높음","src":"기출 2023-17"},{"t":"수직적 마케팅 시스템(VMS): 한 주체가 계획된 프로그램으로 경로구성원을 전문적으로 관리·통제. 폐쇄적이어서 신규 진입이 어려움","src":"기출 2025-18, 2023-17"},{"t":"기업형 VMS: 한 경로구성원이 다른 구성원을 법적으로 소유·관리. 특정 유통경로가 다른 경로를 소유·통제","src":"기출 2023-17, 2025-18"},{"t":"계약형 VMS: 경로구성원이 수행할 유통기능을 계약으로 합의. 도소매기관 지원형 연쇄점, 소매기관 협동조합, 프랜차이즈","src":"기출 2023-17, 2025-18"},{"t":"관리형 VMS: 규모·영향력이 큰 구성원이 다른 구성원을 관리(소유·계약 없이)","src":"보충"},{"t":"수직적 통합 정도: 기업형 > 계약형 > 관리형. 경로구성원 통제력도 기업형이 관리형보다 강함","src":"기출 2024-21, 2025-18"},{"t":"전통적 경로보다 전후방 통합 정도가 높고, 구성원 각자의 이익극대화 추구 현상이 줄어듦","src":"기출 2024-21"},{"t":"유통경로: 제품·서비스가 생산자에서 소비자에 이르기까지 거치는 통로 또는 단계","src":"이론"},{"t":"유통경로는 비탄력적이라 한 번 결정되면 전환이 쉽지 않으므로 다른 마케팅 믹스 요소와 달리 신중하게 결정","src":"이론"},{"t":"유통경로는 시간적·장소적 효용뿐 아니라 소유적·형태적 효용도 창출","src":"이론"},{"t":"중간상 역할: 총거래수 최소화의 원칙으로 생산자의 다수 소비자와의 거래를 단순화","src":"이론"},{"t":"중간상 역할: 생산자와 소비자 간 제품구색·구매량의 불일치를 조절. 한 장소에서 다양한 제품 정보를 제공","src":"이론"},{"t":"중간상 역할: 생산자를 대신해 판매 후 서비스를 제공. 중간상 개입으로 생산자의 재고부담을 경감(집중저장의 원칙)","src":"이론"},{"t":"수직적 유통경로(VMS): 생산에서 소비까지 유통과정의 흐름을 체계적으로 통합·조정해 규모의 경제를 실현하도록 설계한 유통경로","src":"이론"},{"t":"VMS 도입 이유: 유통비용 절감과 업태 간 경쟁에 효과적 대응, 자원·원재료의 안정적 확보와 도소매 유통망 확보","src":"이론"},{"t":"기업형 VMS: 한 경로구성원이 다른 구성원을 경제적·법률적으로 소유·관리. 전방통합과 후방통합이 있음","src":"이론"},{"t":"전방통합: 제조회사가 도·소매업체를 소유하거나 도매상이 소매업체를 소유","src":"이론"},{"t":"후방통합: 소매상·도매상이 제조업체를 소유하거나 제조업체가 부품공급업체를 소유","src":"이론"},{"t":"수직적 통합: 유통망 통합을 위한 전방통합과 원료 안정 조달을 위한 후방통합을 합친 개념","src":"이론"},{"t":"계약형 VMS: 경로구성원이 수행할 마케팅 기능을 계약으로 합의해 공식적 경로관계를 형성. 프랜차이즈 시스템, 도매상 후원의 자발적 연쇄점","src":"이론"},{"t":"관리형 VMS: 소유권이나 명시적 계약 없이 상호이익에 바탕한 협력시스템. 한 경로리더의 규모·파워·경영지원으로 조정","src":"이론"},{"t":"수직적 통합 단점: 조직 규모 비대화로 환경변화에 대한 유연성 저하, 초기 투자비용이 큼","src":"이론"},{"t":"유통경로의 힘(프렌치와 레이븐) 권력 5원천: 보상적 권력, 강압적 권력, 합법적 권력(이상 공식적 지위), 준거적 권력(개인적 특성), 전문적 권력(전문 지식·경험)","src":"이론"},{"t":"보상적 권력: 보상을 줄 수 있다는 인식에 기초. 강압적 권력: 해고·징계·작업시간 단축 등을 지시할 수 있는 능력에서 기인. 합법적 권력: 정당한 영향력(권한)을 추종할 의무가 있다는 사고에 기초","src":"이론"},{"t":"준거적 권력: 리더가 바람직한 특별한 자질을 가져 다른 사람이 일체감을 느끼고 따를 때 생김. 전문적 권력: 특정 분야 지식·경험이 높다고 느낄 때 발생","src":"이론"}]},{"머리":"도매기관 유형","줄":[{"t":"도매기관 유형: 상인 도매기관(merchant), 대리 도매기관(agent), 제조업자 도매기관(manufacturer)","src":"기출 2025-22"},{"t":"상인 도매기관: 취급 상품의 소유권을 보유하며 제조업자·소매상과 관련없는 독립 사업자","src":"기출 2026-24"},{"t":"라스트마일·옴니채널 도매기관은 도매기관 유형이 아님","src":"기출 2025-22, 2026-24"},{"t":"Broker(브로커): 구매자·판매자 간 거래 중개가 주된 기능이며 제품 소유권은 없음","src":"기출 2024-23"},{"t":"한정서비스 도매상: 현금거래 도매상(Cash and Carry), 트럭 도매상(Truck Jobber), 직송 도매상(Drop Shipper), 진열 도매상(Rack Jobber)","src":"기출 2022-27, 2024-23"},{"t":"전문품 도매상(Specialty Wholesaler)은 한정서비스 도매상이 아님(완전서비스 도매상)","src":"기출 2022-27"},{"t":"도매업: 제품을 구입해 소매상·기타 상인·산업체·기관 사용자에게 재판매하는 사업단위. 최종소비자에게는 판매하지 않는 것이 원칙","src":"이론"},{"t":"도매상 4유형: 제조업자 도매상, 상인 도매상, 대리인(agent), 브로커(broker)","src":"이론"},{"t":"제조업자 도매상과 상인 도매상은 상품 소유권을 가지고, 대리인과 브로커는 소유권 없이 거래를 촉진","src":"이론"},{"t":"제조업자 도매상: 판매지점, 판매사무소","src":"이론"},{"t":"상인 도매상 - 완전서비스 도매상: 일반상품 도매상, 한정상품 도매상, 전문품 도매상","src":"이론"},{"t":"상인 도매상 - 한정서비스 도매상: 현금거래 도매상, 트럭도매상, 직송도매상, 진열도매상(Rack jobber)","src":"이론"},{"t":"대리인: 제조업자 대리점, 판매 대리인, 구매 대리인, 수수료 상인","src":"이론"},{"t":"도매상의 제조업자를 위한 기능: 시장커버리지 제공, 판매접촉점 창출, 재고유지, 주문처리, 시장정보수집, 고객지원대행","src":"이론"},{"t":"도매상의 소매업자를 위한 기능: 제품공급선, 소매상 서비스 제공, 신용 및 금융지원, 구색편의 제공, 소분판매, 조언 및 기술지원","src":"이론"},{"t":"도매물류의 제조업자를 위한 기능: 주문처리, 물류의 대형집약화 센터설립, 판매의 집약광역화 대응, 시장동향정보 파악(생산조절). 구색편의 제공은 소매업자를 위한 기능","src":"기출 2020-21"}]},{"머리":"소매업태","줄":[{"t":"카테고리 킬러(Category Killer): 할인형 대규모 전문점. 특정 상품군을 전문 취급하고 풍부한 구색과 저렴한 가격. 토이저러스·오피스디포. 대량구매·대량판매·낮은 운영비","src":"기출 2022-29, 2024-23, 2025-21"},{"t":"팩토리 아웃렛: 상설할인매장. 제조업체의 잉여상품·단절상품·재고상품 취급","src":"기출 2024-23"},{"t":"슈퍼마켓: 식료품·일용품 중심, 셀프서비스","src":"기출 2024-23"},{"t":"소매 보기: 백화점, 대중양판점(GMS), 하이퍼마켓, 슈퍼센터","src":"기출 2022-29, 2025-21"},{"t":"소매업: 최종소비자를 대상으로 제품·서비스를 판매하는 활동. 소비자와 직접 접촉해 욕구에 신속하게 반응","src":"이론"},{"t":"소매업의 변화: 오프라인에서 온라인 소매점으로, 최근에는 온·오프라인을 넘나드는 O2O(Online to Offline) 커머스 형태가 등장","src":"이론"},{"t":"소매상의 생산자에 대한 기능: 점포 내 주문처리로 고객서비스 대행, 소비자 정보를 공급자에게 제공, 상품 보관기능으로 생산자 부담 경감, 자체 광고·프로모션","src":"이론"},{"t":"소매상의 소비자에 대한 기능: 다양한 상품구색, 광고·디스플레이 등으로 상품 정보 제공, 상품 저장으로 재고 유지, 신용·할부판매로 금융·구매 편의 제공","src":"이론"},{"t":"백화점: 용역 제공장소를 제외한 매장면적의 합계가 3,000㎡ 이상인 점포의 집단. 현대적 판매시설과 소비자 편익시설을 갖춤","src":"이론"},{"t":"대형마트: 대통령령으로 정하는 용역 제공장소를 제외한 매장면적 합계가 3,000㎡ 이상인 점포의 집단. 점원의 도움 없이 식품·가전·생활용품 중심으로 소매","src":"이론"},{"t":"SSM(Super-Super Market): 유통산업발전법상 준대규모점포. 기업형 슈퍼마켓으로 품목수와 재고량을 적절히 조절","src":"이론"},{"t":"하이퍼마켓: 대형 슈퍼마켓에 할인점·창고소매업 방식을 접목해 저가로 판매. PB 제품 비중이 큼. 매장면적 2,500㎡ 이상, 대규모 주차장 보유","src":"이론"},{"t":"전문점: 매장면적 합계 3,000㎡ 이상인 점포의 집단으로 의류·가전·가정용품 등 특정 품목에 특화","src":"이론"},{"t":"아울렛(outlet): 제조업자·유통업체 등이 비인기상품·재고상품·하자상품·이월상품을 할인가로 판매하는 상설할인점포. 제조업자나 백화점이 소유한 오프프라이스 스토어가 대부분이며 팩토리 아울렛이라고 함","src":"이론"},{"t":"카테고리 킬러: 한정된 제품계열에서 깊이 있는 상품구색으로 전문점과 유사하나 저렴한 가격으로 판매. 대량판매·다점포화·셀프서비스 방식. 예: 서울전자랜드, 하이마트, 토이저러스, ABC마트","src":"이론"},{"t":"회원제 창고형 할인점(MWC): 회비를 낸 회원에게만 구매 자격을 주고 거대한 창고형 점포에서 할인가로 판매","src":"이론"},{"t":"무점포 소매상: 자판기, 방문판매(네트워크 마케팅), 직접 마케팅(인터넷 쇼핑몰·인터넷 상거래), SNS 마케팅 등 온라인·직접판매로 매출 발생","src":"이론"},{"t":"도매상은 소비자가 아닌 다른 상인(소매점 등)에게 판매하고, 소매상은 최종 소비자에게 판매","src":"이론"},{"t":"볼런터리 체인(임의연쇄점): 독립자본으로 운영되는 다수 소매점이 특정 CEH 기능을 체인본부에 위탁. 체인본부에 최소한의 기본 기능만 요구되어 재정적 부담이 적음","src":"기출 2020-22"}]},{"머리":"CRM","줄":[{"t":"CRM의 목적: 고객 확보·유지 및 고객 충성도 증대","src":"기출 2026-29"},{"t":"마케팅 분야에서 상품관리·프로모션관리·채널관리 영역에 사용","src":"기출 2026-29"},{"t":"도입 효과: 우량고객·신규고객·교차판매 증가로 수익성 향상. 고객 유지·획득비용 감소, 타겟 마케팅으로 고객당 영업비용 절감","src":"기출 2026-29"},{"t":"자재공급에서 최종소비까지 전체 공급사슬의 고객 대응성을 높이는 개념은 SCM이며 CRM이 아님","src":"기출 2026-29"}]},{"머리":"유통경로 이론","줄":[{"t":"연기-투기이론: 경로구성원 중 누가 재고보유 위험을 부담하는가에 따라 경로구조가 결정","src":"이론"},{"t":"기능위양이론: 유통기관은 비용우위가 있는 마케팅 기능만 수행하고 나머지는 다른 경로구성원에게 위양","src":"이론"},{"t":"거래비용이론(윌리엄슨): 수직적 계열화 비용과 시장거래 비용의 상대적 크기에 따라 유통경로 길이의 범위가 결정","src":"이론"},{"t":"게임이론: 수직적 경쟁관계의 제조업자와 중간상이 각자 이익 극대화를 위해 자신과 상대방 행위를 조정하는 과정에서 경로구조가 결정","src":"이론"},{"t":"대리인이론: 의뢰인이 대리인의 결정·행동에 의존한다는 개념에서, 개별 경로구성원(의뢰인)에게 가장 큰 성과를 주는 대리인을 찾아 계약하며 경로구조가 결정","src":"이론"},{"t":"체크리스트법: 경로구성원의 마케팅 능력과 소비자의 유통서비스 요구를 구체화한 요인(시장요인·제품요인·기업요인·경로구성원 등)을 고려해 경로 길이를 결정","src":"이론"}]}],"함정":[{"x":"물류와 마케팅 기능이 상호작용하는 분야는 하역관리와 설비관리 등이 있다.","o":"출제 오답(바른 수치 미확인). 마케팅과 물류의 상호작용은 재고·운송·창고·주문처리·고객서비스 쪽(추정).","src":"기출 2023-9, 보충(추정)"},{"x":"영업소와 고객 간 직배송이 확대되므로 고객서비스가 향상된다.","o":"출제 오답(바른 수치 미확인). 영업소 통합·집약으로 직배송은 줄고 거점 중심으로 바뀜(추정).","src":"기출 2023-10, 보충(추정)"},{"x":"수직적 유통경로 시스템은 신규 구성원의 진입이 상대적으로 용이한 개방형 네트워크이다.","o":"폐쇄형 네트워크로 신규 진입이 어렵다.","src":"기출 2023-17"},{"x":"기업형 VMS의 대표적 유형은 프랜차이즈 시스템이다.","o":"프랜차이즈는 계약형 VMS.","src":"기출 2024-21"},{"x":"경로구성원에 대한 통제력은 관리형 VMS가 기업형 VMS보다 더 강하다.","o":"기업형 VMS의 통제력이 더 강하다.","src":"기출 2025-18"},{"x":"Rack Jobber는 완전서비스 도매상(Full-service wholesaler)에 속한다.","o":"Rack Jobber는 한정서비스 도매상.","src":"기출 2024-23"},{"x":"물류는 마케팅믹스 중에서 촉진과 가장 밀접한 관계가 있다.","o":"유통(Place)과 가장 밀접.","src":"기출 2026-8"},{"x":"CRM은 자재공급에서 최종소비까지 전체 공급사슬의 고객 대응성을 높임으로써, 고객의 편의를 증진하면서도 전체 공급사슬이 최소비용으로 운용될 수 있도록 관리하는 기법과 개념을 의미한다.","o":"그 설명은 SCM. CRM은 고객 확보·유지 중심.","src":"기출 2026-29"},{"x":"[수직적 유통경로시스템(VMS: Vertical Marketing System)] 관리형 VMS는 수직적 유통경로시스템 중에서 통합 또는 통제 정도가 가장 강한 시스템이다.","o":"통제력 강도는 기업형 > 계약형 > 관리형. 관리형이 가장 약함","src":"기출 2020-20"}]},"#15":{"묶음":[{"머리":"e-조달","줄":[{"t":"장점: 운영비용 절감, 조달효율성 개선, 조달가격 절감, 문서처리 비용 감소","src":"기출 2021-19, 2025-20"},{"t":"장점: 구매업무 처리시간 절감, 프로세스 자동화로 구매비용 절감, 실시간 정보로 재고·예산 관리","src":"기출 2025-20"},{"t":"구매자와 판매자 간 밀접한 관계 구축은 e-조달의 장점으로 보지 않음. 신용정보·거래정보 유출 위험은 존재","src":"기출 2021-19, 2025-20"}]},{"머리":"공급업체 선정 방법","줄":[{"t":"협의에 의한 방법: 다수 공급업체의 제안서를 받아 평가한 뒤 협상으로 가장 유리한 업체와 계약","src":"기출 2021-20"},{"t":"기타 방법: 입찰(일반경쟁), 제한경쟁, 지명경쟁, 수의계약","src":"기출 2021-20"},{"t":"제한경쟁은 자격 제한, 지명경쟁은 특정 업체 지명, 수의계약은 특정 업체와 임의 계약","src":"보충"}]},{"머리":"집중구매","줄":[{"t":"장점: 구입절차 표준화로 구매비용 절감, 대량구매로 가격·거래조건 유리, 공통자재 표준화·단순화, 수입 등 복잡한 구매에 유리","src":"기출 2021-21"},{"t":"단점: 긴급수요 발생 시 대응에 불리","src":"기출 2021-21"},{"t":"집중구매: 하나 또는 소수의 공급업체로부터 집중적으로 구매. 안정적 품질관리나 통합적 경영관리시스템을 적용할 때 유리","src":"이론"},{"t":"집중구매 적용 품목: 전사 공통품목, 표준화된 품목, 수요 많은 품목, 구매량에 따라 가격차이가 큰 품목","src":"이론"},{"t":"집중구매 장점: 가격·거래조건 유리, 시장조사 용이, 절차가 복잡한 구매에 유리, 구매효과 측정 용이","src":"이론"},{"t":"집중구매 단점: 구매부서·사업장별 자주성이 없고 수속이 복잡, 긴급조달 어려움, 사업장별 재고파악 어려움, 조달기간과 운임 증가","src":"이론"},{"t":"분산구매: 유통업체가 다수의 공급업체와 거래해 구매위험을 분산. 목표시장 변화에 대한 유연성이 증가하고 제품개발·기술개발·상품공급 측면에서 독립성이 강함","src":"이론"},{"t":"분산구매 적용 품목: 시장성 품목, 구매량과 가격 간 관계가 없는 품목, 소량·소액 품목, 사무용 소모품, 수리용 부속품","src":"이론"},{"t":"분산구매 장점: 자주적 구매·사업장 특수요구 반영 용이, 긴급수요 시 유리, 구매수속 신속 처리","src":"이론"},{"t":"분산구매 단점: 본사 방침과 다른 자재 구매 발생, 구입단가가 비싸고 구매경비 증가, 구입처와 거리가 멀면 적절한 자재 구입 어려움","src":"이론"}]},{"머리":"구매 전략과 공급업체 관계","줄":[{"t":"구매전략: 총소유비용(TCO) 절감 중시. 공급자 수를 줄이는 물량통합과 공급자와의 운영통합","src":"기출 2023-16"},{"t":"JIT 구매: 적기에 필요한 품목을 필요한 양만큼 확보. 공급자 정보공유 필요성 증대. 품질 향상을 위해 구매자가 공급자 활동이 안정적으로 수행되도록 협력","src":"기출 2023-16"},{"t":"장기 협력 공급업체 특징: 건전한 재무상태, 유연한 공급능력, 안정적(신뢰있는) 노사관계, 정보시스템의 높은 상호운용성","src":"기출 2025-19, 2026-23"},{"t":"품질·원가의 높은 변동성은 장기 협력 공급업체의 특징이 아님","src":"기출 2025-19, 2026-23"}]},{"머리":"MRO","줄":[{"t":"MRO: Maintenance(유지)·Repair(보수)·Operation(운영)의 약자. 공장에서 최적화된 생산을 위해 필요한 소모성 자재 또는 관련 산업","src":"이론"},{"t":"MRO 개념 확대: 전자상거래를 통해 기업이 쓰는 원자재를 제외한 모든 간접자재, 또는 기업 구매부문을 대신해 전략적으로 구매·관리하는 회사","src":"이론"},{"t":"MRO 중요성: 글로벌 경쟁에서 비용절감 중요성이 강조되며 관리 영역으로 부각. 원가절감이 블루오션으로 인식되어 전자상거래 MRO 전문기업에 전략적으로 아웃소싱","src":"이론"},{"t":"전자상거래 MRO 성공요건: ERP 등 통합 데이터베이스 구축, 시스템 확장성·통합성, 비계획 구매 대응, 철저한 공급업체 관리, MRO 자재 토탈 서비스, 구매 대상 품목의 표준화","src":"이론"}]}],"함정":[{"x":"긴급수요 발생 시 대응에 유리하다. (집중구매)","o":"긴급수요 대응에는 불리하다.","src":"기출 2021-21"},{"x":"최근에는 총소유비용 절감보다 구매단가 인하를 위한 협상 전략이 더 중요해졌다.","o":"구매단가 인하 협상보다 총소유비용(TCO) 절감이 중요해졌다.","src":"기출 2023-16"},{"x":"e-조달: 구매자와 판매자 간에 밀접한 관계가 구축된다.","o":"e-조달의 장점으로 보기 어렵다.","src":"기출 2021-19"},{"x":"e-조달: 신용정보 및 거래정보의 유출 위험이 없다.","o":"정보 유출 위험이 있다.","src":"기출 2025-20"}]},"#16":{"묶음":[{"머리":"정의와 대상","줄":[{"t":"물류표준화: 원활한 물류를 위해 ①시설·장비의 종류·형상·치수·구조 ②포장의 종류·형상·치수·구조·방법 ③물류용어·물류회계·물류 관련 전자문서 등을 물류표준으로 통일하고 단순화","src":"물류정책기본법 제2조 제1항 제7호"},{"t":"물류표준: 산업표준화법에 따른 한국산업표준(KS) 중 물류활동과 관련된 것","src":"물류정책기본법 제2조 제1항 제6호"},{"t":"표준화 대상: 수송, 보관, 포장, 물류정보. 물류조직은 대상이 아님","src":"기출 2021-32"},{"t":"목적: 단위화물체계 보급, 물류기기와의 연계성 향상, 물류비 절감, 물류활동 효율화. 납품주기 단축·납품횟수 증대는 목적이 아님","src":"기출 2024-31, 2022-8"},{"t":"운송·보관·하역·포장 정보의 일관처리로 효율성 제고","src":"기출 2022-8"},{"t":"자원·에너지 절감 효과: 재료의 경량화","src":"기출 2021-33"},{"t":"하드웨어 표준화: 파렛트, 내수용 컨테이너, 물류시설 및 장비, 적재함, 보관랙","src":"기출 2022-6, 2026-34"},{"t":"소프트웨어 표준화: 포장치수, 물류용어, 거래단위","src":"기출 2022-6, 2026-34"},{"t":"물류표준화: 화물유통 장비와 포장의 규격·구조 등을 통일·단순화. 포장·하역·보관·운송·정보 각 단계의 취급단위를 표준 규격화하고 기기·용기·설비의 규격·강도·재질을 표준화해 호환성과 연계성을 확보하는 유닛로드시스템(ULS) 구축","src":"이론"},{"t":"목적: 단순화·규격화로 물류활동의 기준을 부여해 물류효율성 제고","src":"이론"},{"t":"목적: 기업차원의 미시적 물류뿐 아니라 국가차원의 거시적 물류효율성 제고","src":"이론"},{"t":"목적: 물류의 호환성·연계성 확보로 물류비 절감","src":"이론"},{"t":"목적: 신기술·신소재, 하역·보관의 기계화·자동화, 수·배송 합리화","src":"이론"},{"t":"목적: 글로벌 국제물류 환경변화에 대응하기 위한 국제표준화 연계","src":"이론"},{"t":"물류정책기본법 제2조 7호 물류표준화 대상: 시설·장비의 종류·형상·치수·구조 / 포장의 종류·형상·치수·구조·방법 / 물류용어·물류회계·물류 관련 전자문서 등 물류체계 효율화에 필요한 사항","src":"이론"},{"t":"물류표준화는 단위적재시스템(ULS) 구축이 필요하고 포장·하역·재고설비 등의 표준화가 전제","src":"이론"},{"t":"물류 부문 표준화: 포장표준화, 운송용기·장비표준화(파렛트·컨테이너), 보관시설 표준화(랙·창고 기둥간격), 물류정보 및 시스템 표준화, 물류용어 및 물류회계 표준화","src":"이론"},{"t":"소프트웨어 부문 표준화: 물류용어 통일, 거래단위·전표 표준화(크기·양식·기재내용), 표준코드 활용, 포장치수 표준화","src":"이론"},{"t":"하드웨어 부문 표준화: 파렛트, 내수용 컨테이너 규격화, 지게차, 트럭적재함, 보관시설(랙·건물사양), 기타 물류기기","src":"이론"},{"t":"물류표준화 대상 분야: 수송·보관·하역·포장·정보화 부문 모두 해당","src":"기출 2020-34"}]},{"머리":"물류모듈","줄":[{"t":"물류모듈: 물류시설·장비의 규격·치수가 일정한 배수 또는 분할 관계로 조합된 집합체로, 표준화를 위한 기준치수","src":"기출 2022-8, 2024-33, 2025-33"},{"t":"Unit Load 치수: NULS(Net Unit Load Size)와 PVS(Plan View Size)","src":"기출 2022-8, 2024-33"},{"t":"배수치수 모듈: 1,140mm×1,140mm Unit Load Size를 기준으로 최대 허용공차 −40mm를 인정하는 Plan View Unit Load Size를 기본단위로 함","src":"기출 2021-34, 2022-8"},{"t":"물류모듈은 포장 치수와 독립적으로 정하는 것이 아니라 포장 치수를 물류모듈에 맞춤","src":"기출 2025-33"},{"t":"물류모듈화: 물류시스템 구성요소(화물 단위적재, 하역·운반기기, 트럭·철도화차·선박 등 운송장비, 보관기기·시설)의 치수·사양에 관한 기준척도 및 대칭계열","src":"이론"},{"t":"한국산업표준(KS): 유닛로드용 파렛트 표준은 T-11형(1,100×1,100mm)과 T-12형(1,200×1,000mm) 2가지","src":"이론"},{"t":"유닛로드시스템은 파렛트를 기본으로 하는 것이 가장 일반적. 유닛로드 치수 표준화를 위해 화물자동차·컨테이너·파렛트의 정합성이 필요","src":"이론"},{"t":"ISO 표준파렛트 정사각형: 1,140×1,140(호주), 1,100×1,100(아시아·태평양지역), 1,067(42\")×1,067(42\")","src":"이론"},{"t":"ISO 표준파렛트 직사각형: 1,200×800(유럽 R189), 1,200×1,000(한국·독일·네덜란드), 1,219(48\")×1,016(40\")(미국)","src":"이론"},{"t":"분할계열치수: NULS(Net Unit Load Size) 1,100×1,100mm 기준으로 T-11형 파렛트를 분할해 박스를 적재함에 적재. 220×220(5×5, 100%), 366×220(3×5, 99.8%), 550×275(2×4, 100%), 550×366(2×3, 99.8%)","src":"이론"},{"t":"포장단위 치수: 95% 이상 적재효율치수로 69종류의 포장모듈치수를 규정. T-11형·T-12형 모두에 적용되는 포장모듈치수: 600×500, 550×366, 500×300, 440×330mm","src":"이론"},{"t":"배수계열치수: PVS(Plan View Size, 1,140×1,140mm) 기준, 최대허용공차 -40mm. 파렛트 단위 화물 적재 시 주로 사용","src":"이론"},{"t":"파렛트 적재: 8톤 트럭 12매, 11톤 트럭 16매. 20ft 컨테이너 10매(2단 20매), 40ft 컨테이너 20매(2단 40매)","src":"이론"},{"t":"풀이 순서(컨테이너 파렛트 수): 20ft 1단 10매 → 2단이면 ×2 = 20매(T-11형)","src":"이론"}]},{"머리":"파렛트 표준과 적재효율","줄":[{"t":"T-11형 표준 파렛트: 1,100mm × 1,100mm","src":"기출 2021-31, 2024-33"},{"t":"적재효율 = (1단에 적재된 박스 면적 합) ÷ 파렛트 면적 × 100","src":"기출 2021-31"},{"t":"풀이 순서: 박스 면적 × 적재수 → 파렛트 면적(1,100×1,100)으로 나눔 → 가장 작은 값이 효율 최저","src":"기출 2021-31"},{"t":"예: 733×366×4 ÷ (1,100×1,100) ≈ 88.7%로 보기 중 최저. 1,100×275 박스 4개는 100%","src":"기출 2021-31, 2024-33"},{"t":"랙 보관량 풀이: 가용 높이 = 랙 높이 − 파렛트 높이 → 단수 = 가용 높이 ÷ 박스 높이(내림) → 1단 적재수 × 단수","src":"기출 2026-32"},{"t":"예: (2,000−144)÷245=7.57 → 7단. 1,100×1,100에 550×275 박스는 2×4=8개 → 8×7=56개","src":"기출 2026-32"}]},{"머리":"파렛트 적재 방식","줄":[{"t":"교대배열(교호열) 쌓기: 홀수단은 물품을 모두 같은 방향으로 정돈, 짝수단은 90도 회전해 교대로 겹쳐 쌓음. 화물이 갈라질 염려가 적고 정방형 파렛트에 적합. 적재 시간이 길게 소요","src":"기출 2022-9, 2026-37"},{"t":"적재 형태 보기: 블록(Block), 벽돌(Brick), 풍차(Pinwheel), 스플릿(Split), 교대배열(Row)","src":"기출 2022-9, 2026-37"}]},{"머리":"단위적재시스템(ULS)","줄":[{"t":"ULS: 화물을 중량 또는 체적으로 일정하게 단위화하여 하역·수송·보관을 기계화·합리화하는 시스템","src":"기출 2023-27, 2025-32, 2026-33"},{"t":"ULS 도입 시 거래단위 표준화 필요. 포장비용 절감, 적재효율 향상","src":"기출 2025-32"},{"t":"운송·보관·하역 등 작업의 일관화·기계화. 파렛트·하역장비·적재함·보관설비 등의 표준화 필요","src":"기출 2026-33"},{"t":"Unit Load가 생성된 후 해당 상품의 운반·하역 실시. 파렛트 적재 화물의 붕괴·훼손 가능성 고려","src":"기출 2025-32, 2026-33"},{"t":"서비스 수준을 높이려고 고객이 지정한 규격의 파렛트를 쓰는 것은 ULS 취지에 맞지 않음(표준 파렛트 사용)","src":"기출 2025-32"},{"t":"ULS(유닛로드시스템): 화물을 일정 중량·크기로 단위화·규격화해 기계로 하역·수송하는 방식","src":"이론"},{"t":"ULS 도입 선결요건: 수송용 적재함 규격, 포장단위 치수, 운반·하역장비, 보관설비, 거래단위, 파렛트의 표준화","src":"이론"},{"t":"ULS 효과: 작업효율 향상, 운반 활성화, 물류비용 감소, 하역·운송 중 화물 손상 감소, 운송·보관업무의 효율적 운용","src":"이론"},{"t":"지역·국가별 표준 파렛트의 종류와 규격은 서로 다름","src":"이론"}]},{"머리":"포장 표준화","줄":[{"t":"포장표준화 4요소: 치수·강도·재료·기법 표준화(관리의 표준화를 추가하기도 함)","src":"기출 2023-22"},{"t":"포장 치수는 파렛트·컨테이너 치수에 정합. 포장이 표준화되어야 기계화·자동화·파렛트화·컨테이너화 용이. 포장비·포장재료비·포장작업비 절감","src":"기출 2023-22"},{"t":"포장의 모듈화: 하역·보관·운송 합리화를 위해 제품에 최적화된 포장치수를 선택해 포장의 단위화를 가능하게 함","src":"기출 2024-32"},{"t":"포장: 물품 유통과정에서 가치·상태를 보호하기 위해 적합한 재료·용기를 부여하는 것. 물류과정의 시발점이며 물류비 절감의 주요수단","src":"이론"},{"t":"포장설계 고려사항: 하역성·표시성·작업성·경제성·보호성","src":"이론"},{"t":"포장 기능: 공업포장(내용물 보호·보전성, 취급 사용의 편리성), 상업포장(상품성·정보성, 판매 촉진성), 녹색물류 및 유통성(친환경물류, 유통합리화와 경제성)","src":"이론"},{"t":"포장 유형(제품 기준): 낱포장(단위포장), 속포장(내부포장), 겉포장(외부포장)","src":"이론"},{"t":"공업포장: 수송포장·물류포장이라고도 함. 보관·운송·판매의 위험요소 최소화. 물류에서는 공업포장이 중심. 상업포장: 소비자포장. 소비자가 구입하기 쉬운 단위로 분할하고 내용 설명을 표시","src":"이론"},{"t":"골판지: 파도 모양 골심지의 한쪽 또는 양쪽 면에 라이너를 붙인 것. 종류는 편면골판지·양면골판지·2중·3중 양면골판지. 골의 크기 A골 > B골 > E골","src":"이론"},{"t":"화인(shipping mark): 포장 외부에 특정 기호·포장번호·목적항 등을 표시해 다른 화물과 식별. 주화인, 부화인, 품질표시, 목적지표시, 화물번호, 원산지표시, 주의표시, 중량표시","src":"이론"},{"t":"주화인: 특정 기호 안에 수하인 상호 등을 약자로 표시. 부화인(Counter Mark): 임의기재사항. 주화인이 다른 화물과 동일한 경우 식별을 돕는 보조 표시","src":"이론"},{"t":"목적항표시: 화물이 운송과정에서 잘못 전달되는 것을 방지하는 필수 화인. 복수항로는 \"New York via Seattle\"처럼 표시. 화물번호: 상업송장·적하목록(Manifest) 등과 대조하기 위한 일련번호","src":"이론"},{"t":"원산지표시: 생산국을 외장 맨 아래에 국가명으로 표시. 우리나라는 \"MADE IN KOREA\"","src":"이론"},{"t":"취급주의 표시: 화물 보호와 취급자 안전사고 방지를 위해 한국산업표준으로 규정(포장 용기의 취급 및 적재에 대한 그래픽 심볼 KS T ISO 780, 위험물 취급주의표지 KS T 0008)","src":"이론"},{"t":"포장표준화: 사용되는 기기·용기 등을 대상으로 포장의 치수·강도·재료·기법 4요소를 통일","src":"이론"},{"t":"포장표준화 필요성: ULS 채택을 위해 포장화물의 파렛트화·컨테이너화가 선결조건. 파렛트·컨테이너 규격 표준화로 물류비 절감. 하역 능률 향상으로 유통비용 절감. 포장비·포장재료비·포장작업비 절감","src":"이론"},{"t":"포장합리화 방안: 포장의 간소화·경량화, 포장재료 개선, 포장화물 단위화, 포장 표준화·모듈화, ULS 추진, 포장의 대형화 및 비용절감","src":"이론"},{"t":"포장합리화 6원칙: 대형화·대량화 / 집중화·집약화 / 규격화·표준화 / 사양변경 / 재질변경 / 시스템화·단위화","src":"이론"},{"t":"사양변경의 원칙: 포장의 보호성에서 벗어나지 않는 범위에서 사양을 바꿔 비용절감. 재질변경의 원칙: 재질 변경으로 비용절감","src":"이론"},{"t":"포장 모듈화: 제품 규격에 맞춰 포장규격·파렛트 규격을 선택해 ULS의 파렛트화·컨테이너화를 가능하게 하고 하역 기계화·자동화, 화물파손 방지, 적재 신속화에 기여","src":"이론"},{"t":"ULS는 일관운송용 평파렛트(KS T 1372)에 의한 일관파렛트화 구축. 표준파렛트 사용은 일관운송용 파렛트에 의한 물류표준화","src":"이론"},{"t":"파렛트화(Palletization): 화물을 정해진 치수로 파렛트 위에 쌓고 함께 묶어 규격화. 장점: 하역·작업능률 향상, 화물파손 감소·물품보호, 재고조사 편의, 상하차 시간 단축으로 트럭 운행효율 향상","src":"이론"},{"t":"컨테이너화(Containerization): 국제적으로 통일된 규격 컨테이너로 수송. 장점: 대량 취급 용이, 화물흐름 신속화, 물류표준화·효율화, 복합·연계운송 활성화","src":"이론"}]},{"머리":"파렛트풀시스템(PPS)","줄":[{"t":"파렛트풀시스템: 파렛트의 규격·강도·재질을 표준화해 여러 기업이 공동 이용함으로써 물류효율을 높이고 비용을 절감하는 제도","src":"이론"},{"t":"효과: 발송지에서 최종 도착지까지 일관 파렛트화·일관운송, 업종 간 공동 이용으로 성수기·비수기 수요변동 대응, 공파렛트 회수문제 해소, 물류비 부담 감소","src":"이론"},{"t":"즉시교환방식: 송화주가 파렛트화된 화물을 운송사에 위탁하는 시점에 동일 수의 파렛트를 운송사에서 인수하고, 수화주는 인수할 때 동일 수의 파렛트를 운송사에 인도","src":"이론"},{"t":"리스방식: 개별 기업이 파렛트를 보유하지 않고 필요에 따라 리스. 파렛트 풀 운영기관이 사용자의 거점(depot)에 규격 파렛트를 공급","src":"이론"},{"t":"대차결제방식: 현장에서 즉시 교환하지 않고 일정 시간 이내에 파렛트를 운송사에 반환","src":"이론"},{"t":"교환·리스 병용방식: 즉시교환 + 리스·렌탈. 사용자 편의성이 좋으나 책임소재가 불명확한 문제","src":"이론"}]}],"함정":[{"x":"배수치수 모듈은 1,140mm × 1,140mm Unit Load Size를 기준으로 하고, 최대 허용공차 -80mm를 인정하고 있는 Plan View Unit Load Size를 기본단위로 하고 있다.","o":"최대 허용공차는 −40mm.","src":"기출 2022-8"},{"x":"T-11형 파렛트는 11톤 트럭에 최대 12매가 적재되도록 물류모듈 배수관계가 정립되어 있다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2024-33"},{"x":"치수표준화는 비용절감효과가 빠르게 나타나지만 강도표준화는 그 효과가 나타나기까지 오랜 시간이 걸린다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-22"},{"x":"서비스 수준을 높이기 위해 고객이 지정한 규격의 파렛트를 구비하여 활용한다.","o":"표준 파렛트를 사용한다.","src":"기출 2025-32"},{"x":"주문시기 및 주문량 표준화를 통한 물동량 평준화가 필요하다.","o":"출제 오답(바른 수치 미확인). ULS는 거래단위·파렛트 등을 표준화한다.","src":"기출 2026-33"},{"x":"한국산업표준(KS)으로 제정된 수송포장계열치수는 1,140 mm를 정수로 나눈 배수모듈 시스템이다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2025-33"},{"x":"Unit Load의 최대허용치수(Maximum Plan View Size)는 1,100 mm × 1,100 mm이다.","o":"출제 오답(바른 수치 미확인). 배수모듈 기준은 1,140×1,140.","src":"기출 2025-33"},{"x":"상품성을 높이기 위해서 상품의 포장 치수를 물류 모듈과 독립적으로 결정하는 것이 바람직하다.","o":"포장 치수를 물류모듈에 맞춘다.","src":"기출 2025-33"},{"x":"적재함 폭이 2,340 mm인 8 톤 트럭에는 일관수송용 T-1 표준파렛트 16 매가 적재된다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2025-33"}]},"#17":{"묶음":[{"머리":"정의와 대상","줄":[{"t":"물류공동화: 물류기업이나 화주기업이 물류활동의 효율성을 높이기 위해 시설·장비·인력·조직·정보망 등을 공동으로 이용하는 것","src":"물류정책기본법 제2조 제1항 제5호"},{"t":"공동화 추진 대상: 수·배송, 보관, 포장, 물류정보 기능. 제품개발 기능은 대상 아님","src":"기출 2026-35"},{"t":"물류공동화: 동일지역의 동일·유사업종을 중심으로 물류활동에 필요한 인프라를 둘 이상의 파트너와 연계해 이용함으로써 물류효율을 높이고 비용절감의 공동이익을 추구하는 협력관계","src":"이론"},{"t":"공동화 영역: 수·배송 공동화, 보관 공동화, 하역 공동화, 물류가공(포장) 공동화, 정보 공동화","src":"이론"},{"t":"공동화 목적: 대량 처리로 물류비 절감, 인력 부족 대응, 수·배송 효율 향상, 중복투자 감소","src":"이론"}]},{"머리":"필요성","줄":[{"t":"다빈도 소량 수·배송 증가(소비자 욕구 다양화, 전자상거래)","src":"기출 2021-36, 2023-26, 2025-36"},{"t":"주문단위 소량화, 물류비용 증가, 배송차량 적재효율 저하","src":"기출 2021-36"},{"t":"화물량 증가에 따른 도로혼잡·환경오염 문제, 새로운 시설·설비 투자 위험부담 감소 필요","src":"기출 2023-26"},{"t":"소비자의 물류서비스 차별화 요구 증가는 공동화의 필요성 설명이 아님","src":"기출 2023-26"}]},{"머리":"기대 효과","줄":[{"t":"물류비용 절감, 차량 적재율 향상과 공차율 감소, 물류업무 인원 감소, 물류작업 생산성 향상","src":"기출 2022-2, 2023-19"},{"t":"교통혼잡 완화, 환경오염 방지, 물가 상승 억제 기여","src":"기출 2022-2, 2023-19, 2025-36"},{"t":"화주기업: 규모의 경제로 단위당 물류비 절감, 고객 서비스 수준 향상, 핵심역량 강화","src":"기출 2025-34, 2026-36"},{"t":"운수업자: 물류정보시스템 구축 촉진, 화물 대량화에 의한 운송효율 향상","src":"기출 2025-34, 2026-36"},{"t":"물류인력 고용증대는 기대 효과가 아님","src":"기출 2023-19"}]},{"머리":"전제 조건","줄":[{"t":"대상 기업 간 배송조건의 유사성, 물류업무의 유사성","src":"기출 2023-21, 2026-38"},{"t":"공동수배송을 주도할 중심업체(간사 역할 회사) 존재","src":"기출 2023-21, 2024-34, 2026-38"},{"t":"기업 간 공동수배송에 대한 이해 일치, 공동의 목표","src":"기출 2022-4, 2023-21, 2024-34, 2026-38"},{"t":"일정 지역 내 참여 복수 기업(화주) 존재. 배송처 분포밀도가 높으면 적재율 증가로 비용 절감","src":"기출 2023-21, 2024-34, 2022-4"},{"t":"물류표준화 선행(화물 규격, 포장, 파렛트 규격). 표준물류심벌·통일 전표·교환 가능 파렛트","src":"기출 2021-35, 2022-4, 2024-34"},{"t":"화물형태가 규격화된 품목이 적합. 비규격품·목재·골재·위험물은 효과가 낮음","src":"기출 2022-4, 2023-21, 2024-34"},{"t":"자사 정보시스템·각종 규격·서비스를 공유(시스템 개방 포함). 운영규칙과 비용산정 기준 수립·체계화","src":"기출 2021-35, 2022-4, 2026-38"},{"t":"자사 물류시스템과 외부 물류시스템의 연계 필요","src":"이론"},{"t":"표준물류심벌(GS1 코드), 통일전표, 외부와 교환 가능한 파렛트 등 표준용기 사용","src":"이론"},{"t":"서비스 내용의 명확화·표준화. 통일된 기준에 근거한 물류비 산정·체계화","src":"이론"},{"t":"일정지역 내 공동화에 참여하는 복수 화주 존재. VAN·EDI 등 외부 시스템과 연결되도록 자사 시스템 개방","src":"이론"}]},{"머리":"문제점","줄":[{"t":"새로운 공동배송센터·정보시스템 투자 위험부담","src":"기출 2024-35"},{"t":"참여기업의 기밀유지 문제 발생 가능성이 높아짐","src":"기출 2024-35, 2026-36"},{"t":"포장·전표·용기 표준화가 어려우면 효율 저하. 이해 조정·의사소통·의사결정 지연","src":"기출 2024-35"},{"t":"차별화된 배송서비스를 경쟁전략으로 둔 기업은 참여를 기피. 긴급 수요 대응 능력 저하로 기피하는 경우","src":"기출 2025-36"},{"t":"화주 입장: 기업비밀 노출 우려(납입가격·판매액·거래조건·고객명단), 물류서비스 차별화의 한계, 서비스 수준 저하 우려, 비용배분 분쟁 소지, 긴급 수요 대처에 취약","src":"이론"},{"t":"물류기업 입장: 배송순서 조절이 어려움, 출하시간의 집중화, 상품관리의 어려움(제품 혼재·발주방식 차이·결품관리)","src":"이론"}]},{"머리":"공동 수·배송 유형","줄":[{"t":"배송공동형: 배송만 공동화. 화물거점시설까지의 공동화는 포함하지 않음","src":"기출 2021-37"},{"t":"집배송공동형: 배송센터 배송뿐 아니라 화물의 보관·집하까지 공동화(주문처리 제외)","src":"기출 2022-3, 2024-36, 2021-37"},{"t":"집배송공동형 중 특정화주공동형: 동일 화주가 조합·연합회를 만들어 공동화","src":"기출 2021-37, 2024-36"},{"t":"집배송공동형 중 운송업자공동형: 다수 운송사업자가 불특정 다수 화주의 집배송을 공동화(지역 분담 집화·배송)","src":"기출 2021-37, 2024-36, 2025-35"},{"t":"노선집하공동형(노선집화): 노선업자가 화물을 공동 집화하여 각지로 발송","src":"기출 2021-37, 2022-3"},{"t":"납품대행형: 운송업자가 화주를 대신하여 납입선에 납품을 대행","src":"기출 2021-37, 2022-3"},{"t":"공동수주·공동배송형: 공동으로 수주하고 공동 배송","src":"기출 2022-3"},{"t":"배송공동형: 배송은 공동화하고 화물거점시설까지의 운송은 개별 화주가 하는 형태","src":"이론"},{"t":"공동납품대행형: 착화주의 주도로 공동화. 유통가공·상품내용 검사 등 작업대행. 백화점·할인점 등에서 하는 유형으로, 참가 도매업자가 선정한 운송사업자가 배송거점을 정해 납품 상품을 집화·분류·포장·레이블링한 뒤 배달·납품","src":"이론"},{"t":"공동수주·공동배송형: 운송업자가 협동조합을 설립해 공동으로 수주하고 공동 배송","src":"이론"},{"t":"노선집화공동형: 노선의 집화망을 공동화해 화주가 지정한 노선업자에게 화물을 넘기는 형태","src":"이론"},{"t":"공동수주·공동배송형: 운송업자가 협동조합을 설립하고 화주로부터 수주를 받아 조합원에게 배차를 지시. 주문처리부터 보관·운송·배송까지 모든 업무를 공동화","src":"기출 2020-36"}]},{"머리":"공동 수·배송 개념과 효과","줄":[{"t":"공동수·배송: 하나의 차량에 다양한 화주의 화물을 혼재해 운송함으로써 운송 대형화(적재율 향상·규모의 경제)와 순회배송을 가능하게 하는 운송기법","src":"이론"},{"t":"혼재(consolidation): 다수 화주로부터 위탁받은 소규모 화물을 화차·트럭·컨테이너(항공 컨테이너 포함) 등 대규모 취급단위로 만들어 운송","src":"이론"},{"t":"도입배경: 주문단위의 다빈도·소량화, 운송비·하역비 등 물류비용 증가, 배송차량 적재효율 저하, 도시지역 물류시설 설치 제약, 보관·운송 물류인력 확보 곤란, 상권 확대 및 빈번한 교차수송","src":"이론"},{"t":"기대효과: 물류비용 절감, 교통혼잡 완화·차량감소로 환경오염 방지, 교차배송 감소, 물류기업 인력부족 대처, 운송 대형화로 경제성과 물류센터 효율성 향상, 중복·교차배송 문제 해결, 영차율 증가·공차율 감소","src":"이론"},{"t":"장애요인: 참여업체의 구성, 참여기업 간 의견조정 문제, 긴급 수요 대처에 취약, 회사 기밀유지 문제","src":"이론"},{"t":"전제조건: 일정지역 내 영업·화물특성이 유사한 다수 화주 존재, 대상화물이 공동화에 적합, 참여기업 간 이해도 높고 목표 일치, 경제성·서비스 수준 향상이라는 목적 일치, 주도(주관)하는 책임기업 존재, 배송조건이 유사하고 물류표준화 선행","src":"이론"},{"t":"화주 측면 장점: 화물의 소량화·다빈도 운송 대응, 계획적 배송으로 신속·정확, 공간절약에 의한 유휴시설 이용, 물류인력 효율적 이용, 전표처리·운임 지불업무 합리화, 물류비 절감","src":"이론"},{"t":"화물운송사업자 측면 장점: 규모의 경제로 화물 대량화, 적재효율·운행효율 향상, 물류시설 효율적 이용과 작업 기계화·자동화, 전표처리·운임청구 합리화, 중복배송 감소·교통지체 완화로 집배효율 제고, 물류비 절감","src":"이론"},{"t":"공동 수·배송 효과: 공간 활용 증대, 주문단위 소량화 대응, 교통혼잡 완화, 대기오염·소음 등 환경문제 개선","src":"기출 2020-35"}]}],"함정":[{"x":"납품대행형은 화주가 납입선에 대행으로 납품하는 것이다.","o":"납품대행형은 운송업자가 화주를 대신해 납입선에 납품하는 것(추정).","src":"기출 2021-37, 보충(추정)"},{"x":"자사의 물류시스템과 타사의 물류시스템을 연계시켜 하나의 시스템으로 운영해야 하지만 회사 보안을 위해 시스템 개방은 포함하지 않는다.","o":"시스템 개방(정보 공유)이 포함되어야 한다.","src":"기출 2021-35"},{"x":"차량 적재율과 공차율이 증가한다.","o":"적재율은 증가하고 공차율은 감소한다.","src":"기출 2022-2"},{"x":"자사의 정보시스템, 각종 규격 및 서비스에 대한 공유를 지양해야 한다.","o":"공유가 필요하다.","src":"기출 2022-4"},{"x":"화물형태가 일정하지 않은 비규격품, 목재, 골재, 위험물 등은 공동배송에 효과가 높다.","o":"비규격품은 효과가 낮고 규격화된 품목이 적합.","src":"기출 2024-34"},{"x":"참여기업의 기밀유지 문제가 발생할 가능성이 낮아진다.","o":"기밀유지 문제 발생 가능성이 높다.","src":"기출 2024-35"},{"x":"동일 지역 내에 공동물류센터가 없으면 공동수배송을 실시할 수 없다.","o":"출제 오답(바른 수치 미확인). 공동물류센터 유무가 필수 조건은 아님.","src":"기출 2025-36"},{"x":"제품 매출이나 거래조건 등 화주의 영업기밀을 보호하는 기능이 강화될 수 있다.","o":"영업기밀 노출 위험이 있다.","src":"기출 2026-36"},{"x":"제품특성을 반영하여 화주별로 최적의 파렛트 규격을 정해야 한다.","o":"파렛트 규격은 표준화한다.","src":"기출 2026-38"},{"x":"공동 수·배송의 효과로 운송차량의 공차율이 증가한다.","o":"공차율은 감소하고 영차율(적재율)이 증가","src":"기출 2020-35"}]},"#18":{"묶음":[{"머리":"역물류","줄":[{"t":"역물류: 순물류와 반대 방향의 물류 흐름. 반품물류·폐기물류·회수물류 포함","src":"기출 2025-1, 2023-31, 2022-22"},{"t":"소비단계의 불량품·반품·폐기 제품을 회수해 상태별로 분류 후 재활용하는 과정의 물류활동 포함","src":"기출 2022-33"},{"t":"역물류는 수작업이 많아 자동화가 어려움","src":"기출 2022-33"},{"t":"회수물류: 파렛트·컨테이너 등 물류용기의 재활용을 위한 회수","src":"기출 2025-1"},{"t":"사용 완료된 일회용 소모성 자재는 회수물류가 아니라 폐기물류 대상","src":"기출 2025-1"},{"t":"온라인 쇼핑 증가로 반품물류 중요성 증가","src":"기출 2025-1"},{"t":"순물류와 역물류 비교 - 품질: 순물류 일정 / 역물류 상이. 가격: 순물류 일정 / 역물류 상이","src":"이론"},{"t":"순물류와 역물류 비교 - 회계: 순물류 물류비용 파악 용이 / 역물류 파악 어려움. 제품수명주기: 순물류 관리 용이 / 역물류 관리 어려움","src":"이론"},{"t":"순물류와 역물류 비교 - 구성원: 순물류는 공급망 구성원 간 거래조건이 단순, 역물류는 복잡하고 자동화가 어려움","src":"이론"},{"t":"역물류의 특징: 대상의 품질·가격이 다르고 고객·시장을 파악하기 어려워 물자의 수량·발생시기를 예측할 수 없음. 프로세스 추적·가시성 확보가 어려움. 물류비용 파악이 복잡. 수작업이 많아 자동화가 곤란","src":"이론"}]},{"머리":"녹색물류","줄":[{"t":"녹색물류는 순물류(Forward Logistics)와 역물류를 포괄","src":"기출 2025-38"},{"t":"기후변화 영향으로 자원재생형 녹색물류 중요. 운송 온실가스 저감대책 수립·실행이 녹색물류활동","src":"기출 2025-38"},{"t":"녹색물류인증: 기업의 환경부하 저감사업 실적을 평가해 인증","src":"기출 2025-38"},{"t":"수배송 공동화 등 공동 물류활동 확산은 환경오염을 줄임","src":"기출 2025-38"},{"t":"관련 제도: 저탄소녹색성장기본법, 온실가스·에너지 목표관리제, 탄소배출권거래제, 생산자책임재활용제도(EPR)","src":"기출 2021-39"},{"t":"제조물책임법(PL)은 녹색물류 관련 제도가 아님","src":"기출 2021-39"},{"t":"EPR(생산자책임재활용): 효율적 자원이용, 폐기물 발생 감소, 재활용 촉진","src":"기출 2024-39"},{"t":"ISO 14000 시리즈가 환경경영 기본방침. ISO 9000은 품질경영","src":"기출 2024-39, 보충"},{"t":"교토의정서(1997) 6대 온실가스: 이산화탄소(CO2)·메탄(CH4)·아산화질소(N2O)·수소불화탄소(HFCs)·과불화탄소(PFCs)·육불화황(SF6)","src":"기출 2024-39"},{"t":"우리나라는 2050 탄소중립 선언, 2030년까지 국가 온실가스 감축목표를 2018년 대비 40%로 설정","src":"기출 2024-39"},{"t":"국내 육상운송부문 이산화탄소 절감 대책으로 친환경 운송수단 전환","src":"기출 2024-39"},{"t":"녹색물류: 공급망에서 물류활동으로 발생하는 온실가스뿐 아니라 미세먼지·폐기물·물 사용량 등 각종 환경문제를 제로화하려는 물류시스템","src":"이론"},{"t":"녹색물류 접근: 역물류(폐기물류·회수물류) 개선, 온실가스·미세먼지 저감을 위한 물류시설·장비 개선, 지속가능 사회발전 측면","src":"이론"},{"t":"녹색물류는 제품·포장재의 감량과 폐기물 최소화, 포장상자·배출가스의 환경영향 최소화, 온실가스 배출량 감소 방안. 비용절감과 기업 이미지 제고 가능","src":"이론"},{"t":"우리나라는 폐기물을 다량 발생시키는 생산자에게 감량·회수·재활용 의무를 부여하는 생산자책임재활용제도 운영","src":"이론"},{"t":"녹색물류시스템 문제점: 투자비용이 기업 부담이 되어 물류활동이 위축될 수 있어 정부 지원책이 중요. 고객서비스가 강조될수록 반품처리용 독자 물류시스템 구축으로 비용이 상승해 비용과 서비스 수준 간 상충관계 고려","src":"이론"},{"t":"역물류는 고객에게 완제품을 운송하는 것과 고객으로부터 폐기물 등을 회수하는 활동. 환경·교통 영향까지 포괄하므로 녹색물류보다 협의의 개념","src":"이론"},{"t":"녹색물류 범위: 순물류 및 역물류 전 과정. 역물류 범위: 판매물류 → 회수물류 → 폐기물류","src":"이론"},{"t":"녹색물류 목표: 자재의 순환시스템 구축으로 환경문제 해결. 중점: 물자 재활용 촉진, 친환경 대체재 활용, 대기오염·소음 감축","src":"이론"},{"t":"역물류 목표: 소비 이후 공급사슬 최적화로 자본·자원 절약. 중점: 이윤극대화, 물류비 절감, 서비스 개선","src":"이론"},{"t":"ESG경영: 기업의 비재무적 성과측정 기준. Environment(기후변화·환경오염물질 저감·친환경 제품개발), Social(산업안전·하도급거래·서비스 안전성·공정경쟁), Governance(주주권리·이사회 구성 및 활동·감사제도·배당)","src":"이론"},{"t":"녹색물류는 기업의 핵심 관점인 비용·서비스에 환경이라는 사회적 가치를 추가로 고려하고 3가지를 조정·통합","src":"이론"}]},{"머리":"계산: 연비법 CO2 배출량","줄":[{"t":"공식: CO2 배출량(kg) = 주행거리(km) ÷ 연비(km/L) × 배출계수(kg/L)","src":"기출 2022-31, 2023-34"},{"t":"풀이 순서: 개선 전·후 연료사용량 계산(거리÷연비) → 배출계수 곱함 → 차이가 감소량. 목표 감축 문제는 목표 배출량을 식에 넣어 연비 역산","src":"기출 2022-31, 2023-34, 2024-38, 2026-39"},{"t":"예: 100,000km, 연비 4→5, 계수 0.002 → 50kg → 40kg, 감소 10kg","src":"기출 2022-31"},{"t":"예: 150,000km, 연비 5, 감축 10kg → 현재 60kg → 목표 50kg → 연비 6.0","src":"기출 2023-34"},{"t":"예: 180,000km, 개선 후 연비 6(배출 60kg), 30kg 감소 → 개선 전 90kg → 연비 4","src":"기출 2024-38"},{"t":"예: 120,000km, 연비 6(배출 40kg), 25% 감소 → 30kg → 연비 8","src":"기출 2026-39"},{"t":"환경부담금 비교: 절감 배출량 × 부담금 계수 ≥ 도입비용이 되는 최소 주행거리. 예: 주행거리 d km에서 절감 배출 0.0002d kg × 50만원 = 100d원 ≥ 1,500만원 → d ≥ 150,000km","src":"기출 2025-40"}]},{"머리":"녹색물류 추진방향과 실천","줄":[{"t":"녹색물류 추진방향: 물류공동화·표준화 개선, 차량 대형화를 통한 물류대형화로 다빈도 배송 감소, 모달시프트 추진, 회수물류 활성화, 탄소배출 저감장치 확대·저공해 운송수단 도입, 포장 감소·경량화","src":"이론"},{"t":"모달시프트: 도로(공로) 중심의 고비용 운송체계에서 철도·연안운송 중심으로 운송수단을 전환. 도로운송은 온실가스 배출이 많고 교통혼잡·도로파괴를 유발. 운송분담률 철도 7.5%→20%, 연안해운 19%→25% 전환 목표","src":"이론"},{"t":"오존층 파괴 방지: 염화불화탄소(프레온가스, CFCs) 대체물질 사용, 냉각시스템 탈루검사","src":"이론"},{"t":"대기오염 방지: 디젤연료(경유) 사용 시 연료첨가물, 저유황분 연료 사용. 소음·진동 방지: 차량 브레이크 방음장치 설치","src":"이론"},{"t":"온실가스 저감정책: 무허가 비영업차량의 허가제 차량 전환, 물류공동화 확대, 물류거점 집약화를 통한 물류 대형화, 탄소배출권 거래제도 도입, 특별대책지역 통행접근금지","src":"이론"},{"t":"온실가스 배출 유형: 이동 연소 배출(차량·선박·항공기 연료 연소), 공정 배출(공정시설의 화학적 생산활동), 탈루 배출(저장시설·관 파손 등)","src":"이론"},{"t":"2020 물류분야 온실가스 감축 이행계획 감축 대상: 철도·연안해운 전환수송(modal shift), 3PL 및 공동물류 활성화, Green Port와 녹색물류 전환사업, ITS 구축 등","src":"이론"},{"t":"CO2 배출량(kg) = 연료사용량(L) × 이산화탄소 배출계수(kg-CO2/L). 연료법·연비법·개량 톤-킬로법으로 수치화","src":"이론"}]},{"머리":"친환경 물류와 환경협약","줄":[{"t":"친환경 물류: 녹색물류와 유사하게 쓰이나, 원재료 탐색부터 최종소비자, 사용 후 재활용·재사용·폐기까지 전 과정에서 환경을 보호하고 유해 요소·행위를 원천 차단하거나 최소화하는 활동","src":"이론"},{"t":"친환경 물류 측면: 친환경 포장재 사용, 감량(Reduce)·재사용(Reuse)·재활용(Recycle) 중시","src":"이론"},{"t":"생산자책임재활용제도(EPR): 제조단계에서 폐기에 이르는 전 과정에 대한 책임 부과","src":"이론"},{"t":"물류정책기본법 제59조(환경친화적 물류의 촉진): 국토교통부장관·해양수산부장관 또는 시·도지사가 환경친화적 물류 시책을 마련. 환경친화적 운송수단·포장재료 사용, 기존 시설·장비·운송수단의 환경친화적 변경 시 행정적·재정적 지원 가능","src":"이론"},{"t":"물류정책기본법 제60조: 국토교통부장관·해양수산부장관 또는 시·도지사는 물류기업·화주기업에 환경친화적 운송수단으로의 전환(Modal shift)을 권고하고 지원할 수 있음","src":"이론"},{"t":"물류정책기본법 제60조의2: 국토교통부, 관계 행정기관, 물류관련협회·전문기관·단체, 물류기업·화주기업 등이 환경친화적 물류활동 촉진을 위해 녹색물류협의기구를 설치·운영할 수 있음","src":"이론"},{"t":"몬트리올 의정서: CFC(염화불화탄소)·프레온가스·할론 등 오존층 파괴물질의 생산·사용 규제","src":"이론"},{"t":"바젤협약: 유해 폐기물의 국가 간 이동을 금지하는 협약","src":"이론"},{"t":"교토의정서: 기후변화협약의 구체적 이행 방안으로 선진국의 온실가스 감축 목표치를 규정. 1997년 채택, 2005년 발효","src":"이론"},{"t":"파리협정: 2016년 11월 발효, 2021년부터 교토의정서를 대체. 지구 평균기온 목표치를 처음 명문화. 선진국 위주 감축의무를 모든 당사국으로 확대. 종료시점 없이 지속적 기후변화 대응 체제","src":"이론"},{"t":"RoHS: 유해물질사용 제한지침. 납·크롬·카드뮴·수은 등 6개 물질 사용규제. WEEE: 폐전자제품 처리지침. EuP: 에너지 사용제품의 친환경설계 지침","src":"이론"},{"t":"ISO 14001: 환경경영시스템. 기업의 모든 조직활동·제품·서비스와 관련된 환경영향을 체계적으로 관리","src":"이론"},{"t":"REACH(신화학물질관리제도): 우리나라는 2015년부터 화학물질의 등록 및 평가 등에 관한 법률·화학물질관리법 시행","src":"이론"}]}],"함정":[{"x":"사용이 완료된 일회용 소모성 자재는 회수물류의 대상이다.","o":"일회용 소모성 자재는 폐기물류 대상.","src":"기출 2025-1"},{"x":"수배송 공동화 등 공동 물류활동의 확산은 환경오염을 촉진한다.","o":"환경오염을 줄인다.","src":"기출 2025-38"},{"x":"ISO 9000 시리즈는 환경경영을 기본방침으로 한다.","o":"환경경영은 ISO 14000 시리즈. ISO 9000은 품질경영.","src":"기출 2024-39, 보충"},{"x":"대상제품의 재고파악 및 가시성 확보가 용이하다. (역물류)","o":"역물류는 재고파악·가시성 확보가 어렵다.","src":"기출 2022-33"},{"x":"[순물류·역물류 비교] 구성원 측면: 순물류는 공급망 구성원 간 거래조건이 복잡하고, 역물류는 단순하다.","o":"순물류는 거래조건이 단순하고, 역물류는 복잡하며 자동화가 어려움","src":"기출 2020-37"},{"x":"녹색물류 추진방향: 소량 다빈도 수송 추진","o":"녹색물류는 차량 대형화·물류 대형화로 다빈도 배송을 줄이는 방향. 공동 수·배송, 모달시프트, 회수물류 활성화, 저공해 운송수단 도입이 추진방향","src":"기출 2020-39"}]},"#19":{"묶음":[{"머리":"정의","줄":[{"t":"물류보안: 공항·항만과 물류시설에 폭발물·무기류 등 위해물품을 은닉·반입하는 행위 및 물류 시설·장비·인력·조직·정보망·화물 등에 위해를 가할 목적의 불법행위를 사전에 방지하기 위한 조치","src":"물류정책기본법 제2조 제1항 제13호"},{"t":"물류보안(Supply Chain Security): 원자재 공급·생산·보관·운송과 소비자 전달까지 물류 전 구간에 걸쳐 완벽한 보안시스템을 구축하는 것","src":"이론"},{"t":"물류정책기본법 제2조 물류보안: 공항·항만과 물류시설에 폭발물·무기류 등 위해물품을 은닉·반입하는 행위와 물류시설·장비·조직·인력·정보망·화물 등에 위해를 가할 목적의 불법행위를 사전에 방지하기 위한 조치","src":"이론"},{"t":"물류보안제도는 적용범위에 따라 공급사슬의 특정 구간을 대상으로 하는 제도와 공급사슬 전체를 대상으로 하는 제도로 구분","src":"이론"}]},{"머리":"제도별 내용","줄":[{"t":"C-TPAT: 2002년 미국 세관이 도입한 민관협력 프로그램. 수입업자·선사·운송회사·관세사 등 공급사슬 당사자 대상. 미국 세관의 보안기준 충족 시 통관절차 간소화","src":"기출 2021-38, 2022-40"},{"t":"CSI(컨테이너 보안구상): 미국 세관(CBP)이 미국 외부 주요 항만에 세관원을 파견해 위험도 높은 컨테이너를 사전 검사","src":"기출 2024-37"},{"t":"ISPS code: 해상화물 운송선박·항만시설의 해상테러 가능성 대비. 국제해사기구(IMO) 제정","src":"기출 2024-37"},{"t":"ISO 28000: 보안관리시스템 구축·인증 시 보안 자격을 인정하는 국제인증제도(국제표준화기구). 보안경영 인증제도","src":"기출 2022-40, 2024-37"},{"t":"AEO: 세계관세기구(WCO) 기준에 따라 물류기업이 일정 수준 이상 기준 충족 시 통관절차 간소화","src":"기출 2022-40"},{"t":"SAFE Port Act(SPA, 항만보안법 2006): CSI·SFI·C-TPAT 등의 법적 근거 부여","src":"기출 2024-37, 2023-33"},{"t":"ISF(Importer Security Filing, 10+2 rule): 항만보안법으로 법제화. 적재 24시간 전 미국 세관에 온라인 신고 의무. 수입자 신고사항 10가지, 운송사 신고사항 2가지","src":"기출 2023-33"},{"t":"CIP(Container Inspection Program): 수입 위험물 컨테이너가 국제해상 위험물 규칙(IMDG Code)을 지키는지 점검하는 제도","src":"기출 2025-37"},{"t":"C-TPAT: 반테러 민관협력제도. 미국 최초의 물류보안제도. 2001년 9·11 테러 이후 2002년 미국 세관이 도입. 수입업자·선사·운송회사·관세사 등 공급사슬 당사자가 대상. 미국 세관의 보안기준 충족 시 통관절차 간소화","src":"이론"},{"t":"미국은 C-TPAT에 더해 2003년 해운보안법, 2006년 항만보안법 등을 제정해 물류보안 강화","src":"이론"},{"t":"CSI(컨테이너 보안협정): 미국 수출물량이 많은 외국항만에 미국 세관원을 파견해 미국행 컨테이너 위험도를 사전 평가하고 주재국 세관직원의 화물검사에 입회. 2002년 1월 시행","src":"이론"},{"t":"24시간 전 적하목록 제출제도(24 Hour Advance Manifest Rule): 미국 세관은 미국행 화물·미국 항만에 기항하는 모든 수출화물에 대해 선적 24시간 전까지 적하목록 제출을 의무화","src":"이론"},{"t":"ISPS Code: IMO(국제해사기구) 22차 총회에서 해상화물 운반 선박·항만시설의 해상테러에 대비해 제정. 위험물 감지방법과 보안사고 예방방법 가이드라인 제시","src":"이론"},{"t":"CIP(위험물컨테이너점검제도): 수입 위험물컨테이너의 적재·수납·표찰 등이 국제해상위험물규칙(IMDG Code)을 준수하는지 점검해 위험물 운송 중 사고 예방","src":"이론"},{"t":"ISF(Importer Security Filing): 선적지에서 출항 24시간 전에 미국 세관에 온라인 신고하는 24시간 전 적하목록 제출제도. 10+2 Rule","src":"이론"},{"t":"ICSC(컨테이너 안전협약): 컨테이너의 구조상 안전요건을 다루는 협약","src":"이론"},{"t":"SPA(SAFE Port Act): CSI·SFI·C-TPAT 등에 법적 근거를 부여하고, 미국 관세국경보호청(CBP)이 미국 외부 주요 항만에 세관원을 파견해 위험도 높은 컨테이너를 사전 검사","src":"이론"},{"t":"ISO 28000: ISO 기술표준원이 국제 인증기준을 우리나라 실정에 맞게 조정한 제도. 제조·서비스·보관·운송 등 공급사슬 모든 단계 조직이 인증 대상. 제3자 인증기관의 ISO 28000 인증을 취득하면 국제표준에 적합한 물류보안체계를 갖춘 것으로 공인","src":"이론"},{"t":"ISO 인증시리즈: 9001 품질경영시스템, 14001 환경경영시스템, 26000 CSR(기업의 사회적 책임), 27001 정보보안, 28000 물류보안경영시스템, 50001 에너지 경영시스템","src":"이론"},{"t":"AEO: 9·11 이후 미국의 무역안전조치를 세계관세기구(WCO) 차원에서 수용하며 무역안전과 원활화를 조화하려 도입한 인증제도. 세관이 정한 물류보안기준 충족 시 통관 절차 간소화 특혜. 우리나라는 2009년 3월부터 종합인증우수업체(AEO) 제도 시행","src":"이론"},{"t":"AEO: 세관이 물류기업이 일정 수준 이상 기준을 충족하면 통관절차 등을 간소화. 세계관세기구(WCO)가 무역안전과 원활화를 조화하는 표준협력 제도로 도입. 상호인정협약(MRA)으로 상대국에서도 통관상 혜택","src":"기출 2020-38"}]}],"함정":[{"x":"국제표준화기구의 보안경영 인증: ISO 6780","o":"ISO 28000.","src":"기출 2022-40"}]}};
